#[cfg(any(feature = "p2p_ws", feature = "connect"))]
struct CompletedToriiProxyRequest {
    completed_at: Instant,
    late_response_logged: bool,
    generation: u64,
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
#[derive(Default)]
struct CompletedToriiProxyRequests {
    entries: BTreeMap<Hash, CompletedToriiProxyRequest>,
    insertion_order: VecDeque<(u64, Hash)>,
    next_generation: u64,
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
impl CompletedToriiProxyRequests {
    fn next_generation(&mut self) -> u64 {
        self.next_generation = self.next_generation.wrapping_add(1);
        if self.next_generation == 0 {
            self.next_generation = 1;
        }
        self.next_generation
    }

    fn discard_stale_front(&mut self) {
        while let Some((generation, request_id)) = self.insertion_order.front() {
            if self
                .entries
                .get(request_id)
                .is_some_and(|entry| entry.generation == *generation)
            {
                break;
            }
            self.insertion_order.pop_front();
        }
    }

    fn remove_oldest(&mut self) -> bool {
        self.discard_stale_front();
        let Some((generation, request_id)) = self.insertion_order.pop_front() else {
            return false;
        };
        if self
            .entries
            .get(&request_id)
            .is_some_and(|entry| entry.generation == generation)
        {
            self.entries.remove(&request_id);
        }
        true
    }

    fn prune(&mut self, now: Instant) {
        loop {
            self.discard_stale_front();
            let Some((generation, request_id)) = self.insertion_order.front() else {
                break;
            };
            let Some(entry) = self.entries.get(request_id) else {
                self.insertion_order.pop_front();
                continue;
            };
            if entry.generation != *generation {
                self.insertion_order.pop_front();
                continue;
            }
            if now.saturating_duration_since(entry.completed_at) < TORII_PROXY_COMPLETED_TTL {
                break;
            }
            self.remove_oldest();
        }
        while self.entries.len() > TORII_PROXY_COMPLETED_CAP && self.remove_oldest() {}
    }

    fn record(&mut self, request_id: Hash, completed_at: Instant) {
        self.prune(completed_at);
        while self.entries.len() >= TORII_PROXY_COMPLETED_CAP && self.remove_oldest() {}
        let generation = self.next_generation();
        self.entries.insert(
            request_id.clone(),
            CompletedToriiProxyRequest {
                completed_at,
                late_response_logged: false,
                generation,
            },
        );
        self.insertion_order.push_back((generation, request_id));
    }
}

fn json_string_or_null(opt: Option<String>) -> norito::json::native::Value {
    opt.map(norito::json::native::Value::from)
        .unwrap_or(norito::json::native::Value::Null)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PipelineStatusKind {
    Queued,
    Approved,
    Committed,
    Applied,
    Rejected,
    Expired,
}

const PIPELINE_STATUS_CACHE_CAP: usize = 1_500_000;
const PIPELINE_STATUS_CACHE_TTL: Duration = Duration::from_secs(15 * 60);
const PIPELINE_STATUS_CACHE_PRUNE_INTERVAL_SECS: u64 = 30;
const PIPELINE_STATUS_CACHE_INDEX_REBUILD_SLOP: usize = 1_024;
const PIPELINE_STATUS_CACHE_INDEX_REBUILD_MULTIPLIER: usize = 4;
#[cfg(any(feature = "p2p_ws", feature = "connect"))]
const TORII_PROXY_COMPLETED_TTL: Duration = Duration::from_secs(30);
#[cfg(any(feature = "p2p_ws", feature = "connect"))]
const TORII_PROXY_COMPLETED_CAP: usize = 16_384;

impl PipelineStatusKind {
    fn as_str(self) -> &'static str {
        match self {
            Self::Queued => "Queued",
            Self::Approved => "Approved",
            Self::Committed => "Committed",
            Self::Applied => "Applied",
            Self::Rejected => "Rejected",
            Self::Expired => "Expired",
        }
    }

    fn rank(self) -> u8 {
        match self {
            Self::Queued => 0,
            Self::Approved => 1,
            Self::Expired => 2,
            Self::Rejected => 3,
            Self::Committed => 4,
            Self::Applied => 5,
        }
    }

    fn is_terminal(self) -> bool {
        matches!(self, Self::Applied | Self::Rejected | Self::Expired)
    }
}

#[derive(Clone, Debug)]
struct PipelineStatusEntry {
    kind: PipelineStatusKind,
    block_height: Option<NonZeroU64>,
    rejection: Option<iroha_data_model::transaction::error::TransactionRejectionReason>,
    observed_at: Instant,
}

impl PipelineStatusEntry {
    fn fresh(
        kind: PipelineStatusKind,
        block_height: Option<NonZeroU64>,
        rejection: Option<iroha_data_model::transaction::error::TransactionRejectionReason>,
    ) -> Self {
        Self::at_time(kind, block_height, rejection, Instant::now())
    }

    fn at_time(
        kind: PipelineStatusKind,
        block_height: Option<NonZeroU64>,
        rejection: Option<iroha_data_model::transaction::error::TransactionRejectionReason>,
        observed_at: Instant,
    ) -> Self {
        Self {
            kind,
            block_height,
            rejection,
            observed_at,
        }
    }

    fn merge_from_event(&mut self, incoming: PipelineStatusEntry) {
        let incoming_observed_at = incoming.observed_at;
        match incoming.kind.rank().cmp(&self.kind.rank()) {
            std::cmp::Ordering::Greater => {
                *self = incoming;
                return;
            }
            std::cmp::Ordering::Equal => {
                if self.block_height.is_none() {
                    self.block_height = incoming.block_height;
                }
                if self.rejection.is_none() && incoming.rejection.is_some() {
                    self.rejection = incoming.rejection;
                }
            }
            std::cmp::Ordering::Less => {}
        }
        if incoming_observed_at > self.observed_at {
            self.observed_at = incoming_observed_at;
        }
    }
}

#[derive(Clone, Debug)]
struct PendingBlockStatus {
    kind: PipelineStatusKind,
    block_hash: HashOf<BlockHeader>,
    observed_at: Instant,
}

#[derive(Debug)]
struct PipelineStatusCache {
    entries: DashMap<HashOf<SignedTransaction>, PipelineStatusEntry>,
    pending_blocks: DashMap<NonZeroU64, PendingBlockStatus>,
    entry_order: parking_lot::Mutex<VecDeque<(Instant, HashOf<SignedTransaction>)>>,
    pending_order: parking_lot::Mutex<VecDeque<(Instant, NonZeroU64)>>,
    entry_count: AtomicUsize,
    pending_count: AtomicUsize,
    capacity: usize,
    ttl: Duration,
    start: Instant,
    last_prune_secs: std::sync::atomic::AtomicU64,
    entry_order_unsorted: AtomicBool,
    pending_order_unsorted: AtomicBool,
    prune_lock: parking_lot::Mutex<()>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum BlockRecordOutcome {
    Recorded,
    MissingBlock,
    HashMismatch,
}

impl PipelineStatusCache {
    fn new() -> Self {
        Self::with_limits(PIPELINE_STATUS_CACHE_CAP, PIPELINE_STATUS_CACHE_TTL)
    }

    fn with_limits(capacity: usize, ttl: Duration) -> Self {
        let cap = capacity.max(1);
        Self {
            entries: DashMap::new(),
            pending_blocks: DashMap::new(),
            entry_order: parking_lot::Mutex::new(VecDeque::new()),
            pending_order: parking_lot::Mutex::new(VecDeque::new()),
            entry_count: AtomicUsize::new(0),
            pending_count: AtomicUsize::new(0),
            capacity: cap,
            ttl,
            start: Instant::now(),
            last_prune_secs: std::sync::atomic::AtomicU64::new(0),
            entry_order_unsorted: AtomicBool::new(false),
            pending_order_unsorted: AtomicBool::new(false),
            prune_lock: parking_lot::Mutex::new(()),
        }
    }

    fn record_transaction_event(
        &self,
        event: &iroha_data_model::events::pipeline::TransactionEvent,
    ) {
        let (kind, rejection) = match event.status() {
            TransactionStatus::Queued => (PipelineStatusKind::Queued, None),
            TransactionStatus::Expired => (PipelineStatusKind::Expired, None),
            TransactionStatus::Approved => (PipelineStatusKind::Approved, None),
            TransactionStatus::Rejected(reason) => {
                (PipelineStatusKind::Rejected, Some((**reason).clone()))
            }
        };
        let now = Instant::now();
        let incoming = PipelineStatusEntry::at_time(kind, event.block_height(), rejection, now);
        self.record_entry_inner(*event.hash(), incoming);
        self.prune_if_needed(now);
    }

    fn record_block_event(
        &self,
        event: &iroha_data_model::events::pipeline::BlockEvent,
        kura: &Kura,
    ) {
        let kind = match event.status {
            BlockStatus::Committed => PipelineStatusKind::Committed,
            BlockStatus::Applied => PipelineStatusKind::Applied,
            _ => return,
        };
        let height = event.header.height();
        let block_hash = event.header.hash();
        let now = Instant::now();
        match self.record_block_results(height, block_hash, kind, kura, now) {
            BlockRecordOutcome::Recorded => {
                self.remove_pending_by_height(&height);
                self.prune_if_needed(now);
            }
            BlockRecordOutcome::MissingBlock => {
                self.record_pending_block(
                    height,
                    PendingBlockStatus {
                        kind,
                        block_hash,
                        observed_at: now,
                    },
                );
                self.prune_if_needed(now);
            }
            BlockRecordOutcome::HashMismatch => {}
        }
    }

    fn lookup(&self, hash: &HashOf<SignedTransaction>) -> Option<PipelineStatusEntry> {
        self.entries.get(hash).map(|entry| entry.clone())
    }

    fn record_entry(&self, hash: HashOf<SignedTransaction>, entry: PipelineStatusEntry) {
        self.record_entry_inner(hash, entry);
        self.prune_if_needed(Instant::now());
    }

    fn record_entry_inner(&self, hash: HashOf<SignedTransaction>, incoming: PipelineStatusEntry) {
        let observed_at = match self.entries.entry(hash) {
            DashEntry::Occupied(mut entry) => {
                entry.get_mut().merge_from_event(incoming);
                entry.get().observed_at
            }
            DashEntry::Vacant(entry) => {
                let observed_at = incoming.observed_at;
                self.entry_count.fetch_add(1, AtomicOrdering::Relaxed);
                entry.insert(incoming);
                observed_at
            }
        };
        self.push_entry_order(hash, observed_at);
    }

    fn record_pending_block(&self, height: NonZeroU64, pending: PendingBlockStatus) {
        let observed_at = pending.observed_at;
        match self.pending_blocks.entry(height) {
            DashEntry::Occupied(mut entry) => {
                entry.insert(pending);
            }
            DashEntry::Vacant(entry) => {
                self.pending_count.fetch_add(1, AtomicOrdering::Relaxed);
                entry.insert(pending);
            }
        }
        self.push_pending_order(height, observed_at);
    }

    fn push_entry_order(&self, hash: HashOf<SignedTransaction>, observed_at: Instant) {
        let mut order = self.entry_order.lock();
        if order
            .back()
            .is_some_and(|(last_observed_at, _)| observed_at < *last_observed_at)
        {
            self.entry_order_unsorted
                .store(true, AtomicOrdering::Relaxed);
        }
        order.push_back((observed_at, hash));
    }

    fn push_pending_order(&self, height: NonZeroU64, observed_at: Instant) {
        let mut order = self.pending_order.lock();
        if order
            .back()
            .is_some_and(|(last_observed_at, _)| observed_at < *last_observed_at)
        {
            self.pending_order_unsorted
                .store(true, AtomicOrdering::Relaxed);
        }
        order.push_back((observed_at, height));
    }

    fn refresh_pending_blocks(&self, kura: &Kura) {
        if self.pending_blocks.is_empty() {
            return;
        }
        let now = Instant::now();
        let pending: Vec<_> = self
            .pending_blocks
            .iter()
            .map(|entry| (*entry.key(), entry.value().clone()))
            .collect();
        for (height, pending) in pending {
            match self.record_block_results(height, pending.block_hash, pending.kind, kura, now) {
                BlockRecordOutcome::Recorded | BlockRecordOutcome::HashMismatch => {
                    self.remove_pending_by_height(&height);
                }
                BlockRecordOutcome::MissingBlock => {}
            }
        }
        self.prune_if_needed(now);
    }

    fn prune_if_needed(&self, now: Instant) {
        let elapsed_secs = now.saturating_duration_since(self.start).as_secs().max(1);
        let last_prune = self
            .last_prune_secs
            .load(std::sync::atomic::Ordering::Relaxed);
        let prune_due =
            elapsed_secs.saturating_sub(last_prune) >= PIPELINE_STATUS_CACHE_PRUNE_INTERVAL_SECS;
        let over_cap = self.entry_count.load(AtomicOrdering::Relaxed) > self.capacity
            || self.pending_count.load(AtomicOrdering::Relaxed) > self.capacity;
        if !over_cap && !prune_due {
            return;
        }

        let Some(_guard) = self.prune_lock.try_lock() else {
            return;
        };

        let last_prune = self
            .last_prune_secs
            .load(std::sync::atomic::Ordering::Relaxed);
        let prune_due =
            elapsed_secs.saturating_sub(last_prune) >= PIPELINE_STATUS_CACHE_PRUNE_INTERVAL_SECS;
        let over_cap = self.entry_count.load(AtomicOrdering::Relaxed) > self.capacity
            || self.pending_count.load(AtomicOrdering::Relaxed) > self.capacity;
        if !over_cap && !prune_due {
            return;
        }
        self.last_prune_secs
            .store(elapsed_secs, std::sync::atomic::Ordering::Relaxed);
        self.prune(now);
    }

    fn prune(&self, now: Instant) {
        self.rebuild_order_indexes_if_needed();
        if !self.ttl.is_zero() {
            self.prune_stale_entries(now);
            self.prune_stale_pending_blocks(now);
        }

        self.evict_over_capacity();
        self.compact_order_indexes_if_needed();
    }

    fn evict_over_capacity(&self) {
        self.evict_entries_over_capacity();
        self.evict_pending_over_capacity();
    }

    fn prune_stale_entries(&self, now: Instant) {
        let ttl = self.ttl;
        let mut order = self.entry_order.lock();
        while let Some((observed_at, hash)) = order.front().copied() {
            if now.saturating_duration_since(observed_at) <= ttl {
                break;
            }
            order.pop_front();
            let should_remove = self.entries.get(&hash).is_some_and(|entry| {
                entry.observed_at == observed_at
                    && now.saturating_duration_since(entry.observed_at) > ttl
            });
            if should_remove {
                self.remove_entry_by_hash(&hash);
            }
        }
    }

    fn prune_stale_pending_blocks(&self, now: Instant) {
        let ttl = self.ttl;
        let mut order = self.pending_order.lock();
        while let Some((observed_at, height)) = order.front().copied() {
            if now.saturating_duration_since(observed_at) <= ttl {
                break;
            }
            order.pop_front();
            let should_remove = self.pending_blocks.get(&height).is_some_and(|entry| {
                entry.observed_at == observed_at
                    && now.saturating_duration_since(entry.observed_at) > ttl
            });
            if should_remove {
                self.remove_pending_by_height(&height);
            }
        }
    }

    fn evict_entries_over_capacity(&self) {
        while self.entries.len() > self.capacity {
            if self.remove_oldest_entry() {
                continue;
            }
            self.rebuild_entry_order_index();
            if self.entry_order.lock().is_empty() {
                break;
            }
        }
    }

    fn evict_pending_over_capacity(&self) {
        while self.pending_blocks.len() > self.capacity {
            if self.remove_oldest_pending_block() {
                continue;
            }
            self.rebuild_pending_order_index();
            if self.pending_order.lock().is_empty() {
                break;
            }
        }
    }

    fn remove_oldest_entry(&self) -> bool {
        let mut order = self.entry_order.lock();
        while let Some((observed_at, hash)) = order.pop_front() {
            let should_remove = self
                .entries
                .get(&hash)
                .is_some_and(|entry| entry.observed_at == observed_at);
            if should_remove {
                self.remove_entry_by_hash(&hash);
                return true;
            }
        }
        false
    }

    fn remove_oldest_pending_block(&self) -> bool {
        let mut order = self.pending_order.lock();
        while let Some((observed_at, height)) = order.pop_front() {
            let should_remove = self
                .pending_blocks
                .get(&height)
                .is_some_and(|entry| entry.observed_at == observed_at);
            if should_remove {
                self.remove_pending_by_height(&height);
                return true;
            }
        }
        false
    }

    fn rebuild_order_indexes_if_needed(&self) {
        if self
            .entry_order_unsorted
            .swap(false, AtomicOrdering::Relaxed)
        {
            self.rebuild_entry_order_index();
        }
        if self
            .pending_order_unsorted
            .swap(false, AtomicOrdering::Relaxed)
        {
            self.rebuild_pending_order_index();
        }
    }

    fn compact_order_indexes_if_needed(&self) {
        if Self::order_index_needs_rebuild(self.entry_order.lock().len(), self.entries.len()) {
            self.rebuild_entry_order_index();
        }
        if Self::order_index_needs_rebuild(
            self.pending_order.lock().len(),
            self.pending_blocks.len(),
        ) {
            self.rebuild_pending_order_index();
        }
    }

    fn order_index_needs_rebuild(index_len: usize, live_len: usize) -> bool {
        let live_bound = live_len
            .saturating_mul(PIPELINE_STATUS_CACHE_INDEX_REBUILD_MULTIPLIER)
            .saturating_add(PIPELINE_STATUS_CACHE_INDEX_REBUILD_SLOP);
        index_len > live_bound
    }

    fn rebuild_entry_order_index(&self) {
        let mut ordered: Vec<_> = self
            .entries
            .iter()
            .map(|entry| (entry.observed_at, *entry.key()))
            .collect();
        ordered.sort_by_key(|(observed_at, _)| *observed_at);
        *self.entry_order.lock() = ordered.into_iter().collect();
    }

    fn rebuild_pending_order_index(&self) {
        let mut ordered: Vec<_> = self
            .pending_blocks
            .iter()
            .map(|entry| (entry.observed_at, *entry.key()))
            .collect();
        ordered.sort_by_key(|(observed_at, _)| *observed_at);
        *self.pending_order.lock() = ordered.into_iter().collect();
    }

    fn remove_entry_by_hash(&self, hash: &HashOf<SignedTransaction>) -> bool {
        if self.entries.remove(hash).is_some() {
            Self::decrement_live_count(&self.entry_count);
            true
        } else {
            false
        }
    }

    fn remove_pending_by_height(&self, height: &NonZeroU64) -> bool {
        if self.pending_blocks.remove(height).is_some() {
            Self::decrement_live_count(&self.pending_count);
            true
        } else {
            false
        }
    }

    fn decrement_live_count(count: &AtomicUsize) {
        let _ = count.fetch_update(
            AtomicOrdering::Relaxed,
            AtomicOrdering::Relaxed,
            |current| Some(current.saturating_sub(1)),
        );
    }

    fn record_block_results(
        &self,
        height: NonZeroU64,
        expected_hash: HashOf<BlockHeader>,
        kind: PipelineStatusKind,
        kura: &Kura,
        now: Instant,
    ) -> BlockRecordOutcome {
        let height_usize = match usize::try_from(height.get()) {
            Ok(value) => value,
            Err(_) => {
                iroha_logger::debug!(
                    height = height.get(),
                    "pipeline status cache skipped block: height exceeds usize"
                );
                return BlockRecordOutcome::MissingBlock;
            }
        };
        let Some(height_nz) = NonZeroUsize::new(height_usize) else {
            return BlockRecordOutcome::MissingBlock;
        };
        let Some(block) = kura.get_block(height_nz) else {
            iroha_logger::debug!(
                height = height.get(),
                "pipeline status cache skipped block: block not in kura"
            );
            return BlockRecordOutcome::MissingBlock;
        };
        let block_ref = block.as_ref();
        if block_ref.hash() != expected_hash {
            iroha_logger::debug!(
                height = height.get(),
                "pipeline status cache skipped block: hash mismatch"
            );
            return BlockRecordOutcome::HashMismatch;
        }
        for (index, entrypoint, result) in block_ref.entrypoint_results() {
            if index >= block_ref.external_entrypoint_count() {
                break;
            }
            let (entry_kind, rejection) = match &result.0 {
                Ok(_) => (kind, None),
                Err(reason) => (PipelineStatusKind::Rejected, Some(reason.clone())),
            };
            let incoming = PipelineStatusEntry::at_time(entry_kind, Some(height), rejection, now);
            let hash =
                HashOf::<SignedTransaction>::from_untyped_unchecked(Hash::from(entrypoint.hash()));
            self.record_entry_inner(hash, incoming);
        }
        BlockRecordOutcome::Recorded
    }
}

fn telemetry_unavailable_response(
    endpoint: &'static str,
    telemetry: &routing::MaybeTelemetry,
) -> axum::response::Response {
    #[cfg(feature = "telemetry")]
    {
        Error::telemetry_profile_forbidden(endpoint, telemetry.profile()).into_response()
    }

    #[cfg(not(feature = "telemetry"))]
    {
        let _ = endpoint;
        let _ = telemetry;
        axum::http::StatusCode::SERVICE_UNAVAILABLE.into_response()
    }
}

#[cfg(all(feature = "app_api", feature = "telemetry"))]
fn collect_peer_urls(
    _online_peers: &OnlinePeersProvider,
    configured: &[telemetry::peers::ToriiUrl],
) -> Vec<telemetry::peers::ToriiUrl> {
    if configured.is_empty() {
        // Avoid probing P2P ports; peer telemetry requires explicit Torii URLs.
        iroha_logger::debug!("peer telemetry disabled: no peer_telemetry_urls configured");
        return Vec::new();
    }

    let mut urls = configured.to_vec();
    urls.sort();
    urls.dedup();
    urls
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ConnScheme {
    Http,
    Ws,
    NoritoRpc,
}

impl ConnScheme {
    fn from_request<B>(req: &axum::http::Request<B>) -> Self {
        if req
            .headers()
            .get(axum::http::header::UPGRADE)
            .and_then(|value| value.to_str().ok())
            .map_or(false, |v| v.eq_ignore_ascii_case("websocket"))
        {
            Self::Ws
        } else if matches!(
            req.uri().path(),
            iroha_torii_shared::uri::TRANSACTION | iroha_torii_shared::uri::QUERY
        ) || req
            .headers()
            .get(axum::http::header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .map_or(false, |ct| ct.contains(crate::utils::NORITO_MIME_TYPE))
        {
            Self::NoritoRpc
        } else {
            Self::Http
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Http => "http",
            Self::Ws => "ws",
            Self::NoritoRpc => "norito_rpc",
        }
    }
}

/// Held admission permit and telemetry accounting for one active request or
/// upgraded connection.
pub(crate) struct PreAuthRequestGuard {
    permit: limits::PreAuthPermit,
    telemetry: routing::MaybeTelemetry,
    scheme: ConnScheme,
}

impl Drop for PreAuthRequestGuard {
    fn drop(&mut self) {
        let scheme = self.scheme;
        self.telemetry
            .with_metrics(|telemetry| telemetry.dec_torii_active_conn(scheme.label()));
    }
}

/// Single-owner handoff for extending a pre-authentication permit beyond the
/// HTTP upgrade response and into the upgraded WebSocket task.
///
/// The middleware owns the guard initially. Ordinary responses keep it in the
/// response body, while a WebSocket handler takes it immediately before
/// calling `on_upgrade`. Taking the guard more than once returns `None`, so a
/// permit can never be duplicated across response and upgrade lifetimes.
#[derive(Clone)]
pub(crate) struct PreAuthGuardHandoff(Arc<parking_lot::Mutex<Option<PreAuthRequestGuard>>>);

impl PreAuthGuardHandoff {
    fn new(guard: PreAuthRequestGuard) -> Self {
        Self(Arc::new(parking_lot::Mutex::new(Some(guard))))
    }

    /// Transfer the guard to the caller if no previous owner has taken it.
    pub(crate) fn take(&self) -> Option<PreAuthRequestGuard> {
        self.0.lock().take()
    }
}

/// Take the request's pre-authentication guard for an upgraded WebSocket task.
///
/// `None` is accepted for direct handler tests that do not install Torii's
/// production middleware stack. The production router always supplies this
/// extension.
pub(crate) fn take_preauth_upgrade_guard(
    handoff: Option<Extension<PreAuthGuardHandoff>>,
) -> Option<PreAuthRequestGuard> {
    handoff.and_then(|Extension(handoff)| handoff.take())
}

fn hold_preauth_guard_in_response_body(
    response: axum::response::Response,
    guard: PreAuthRequestGuard,
) -> axum::response::Response {
    use http_body_util::BodyExt as _;

    let (parts, body) = response.into_parts();
    // `map_frame` preserves data frames, trailers, errors, and the original
    // size hint. Capturing the guard in the mapper ties its lifetime to the
    // actual HTTP body instead of merely to handler execution.
    let guarded_body = body.map_frame(move |frame| {
        let _guard = &guard;
        frame
    });
    axum::response::Response::from_parts(parts, Body::new(guarded_body))
}

impl AppState {
    async fn acquire_preauth(
        &self,
        ip: Option<IpAddr>,
        scheme: ConnScheme,
    ) -> Result<PreAuthRequestGuard, limits::RejectReason> {
        let permit = self.preauth_gate.acquire(ip, Some(scheme.label())).await?;
        let telemetry = self.telemetry.clone();
        telemetry.with_metrics(|telemetry| telemetry.inc_torii_active_conn(scheme.label()));
        Ok(PreAuthRequestGuard {
            permit,
            telemetry,
            scheme,
        })
    }

    fn record_preauth_reject(&self, reason: limits::RejectReason) {
        self.telemetry
            .with_metrics(|telemetry| telemetry.inc_torii_pre_auth_reject(reason.metric_label()));
    }

    fn record_norito_rpc_gate(&self, outcome: &'static str) {
        let stage = self.norito_rpc.stage.label();
        self.telemetry
            .with_metrics(|telemetry| telemetry.inc_torii_norito_rpc_gate(stage, outcome));
    }

    fn norito_rpc_config(&self) -> &NoritoRpcTransport {
        &self.norito_rpc
    }

    /// Returns whether a validated API token may identify the caller for rate limiting.
    ///
    /// Callers must validate the request with [`validate_api_token`] before
    /// allowing the header value to contribute to a rate-limit key.
    fn api_token_enforced(&self) -> bool {
        self.require_api_token && !self.api_tokens_set.is_empty()
    }

    fn check_norito_rpc_allowed(
        &self,
        headers: &axum::http::HeaderMap,
        remote_ip: Option<IpAddr>,
    ) -> Result<(), Box<axum::response::Response>> {
        let provided_token = norito_rpc_token_from_headers(headers);
        match evaluate_norito_rpc_gate(
            self.norito_rpc_config(),
            &self.norito_rpc_mtls_trusted_proxy_nets,
            headers,
            remote_ip,
        ) {
            Ok(()) => {
                self.record_norito_rpc_gate("allowed");
                Ok(())
            }
            Err(failure) => {
                let outcome = match failure {
                    NoritoRpcGateFailure::Disabled => "disabled",
                    NoritoRpcGateFailure::CanaryDenied => {
                        if provided_token.is_some() {
                            "canary_denied"
                        } else {
                            "canary_missing_token"
                        }
                    }
                    NoritoRpcGateFailure::MtlsRequired => "mtls_required",
                };
                self.record_norito_rpc_gate(outcome);
                Err(Box::new(norito_rpc_error_response(failure)))
            }
        }
    }

    fn rpc_capabilities(&self) -> RpcCapabilitiesResponse {
        RpcCapabilitiesResponse {
            norito_rpc: RpcNoritoRpcCapability::from(self.norito_rpc_config()),
        }
    }

    fn rpc_ping(&self) -> RpcPingResponse {
        let timestamp_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis() as u64;
        RpcPingResponse {
            ok: true,
            unix_time_ms: timestamp_ms,
            norito_rpc: RpcNoritoRpcCapability::from(self.norito_rpc_config()),
        }
    }

    /// Clone the telemetry handle for downstream helpers.
    pub(crate) fn telemetry_handle(&self) -> routing::MaybeTelemetry {
        self.telemetry.clone()
    }

    #[cfg(feature = "app_api")]
    pub(crate) fn sorafs_cache(&self) -> Option<Arc<RwLock<sorafs::ProviderAdvertCache>>> {
        self.sorafs_cache.clone()
    }

    #[cfg(feature = "app_api")]
    pub(crate) fn sorafs_node(&self) -> &sorafs_node::NodeHandle {
        &self.sorafs_node
    }

    #[cfg(feature = "app_api")]
    pub(crate) fn stream_token_issuer(&self) -> Option<Arc<sorafs::StreamTokenIssuer>> {
        self.stream_token_issuer.clone()
    }

    #[cfg(feature = "app_api")]
    pub(crate) fn stream_token_concurrency(&self) -> &sorafs::StreamTokenConcurrencyTracker {
        &self.stream_token_concurrency
    }

    #[cfg(feature = "app_api")]
    pub(crate) fn stream_token_quota(&self) -> &sorafs::StreamTokenQuotaTracker {
        &self.stream_token_quota
    }

    #[cfg(feature = "app_api")]
    fn blinded_resolver(&self) -> Option<&Arc<sorafs::BlindedCidResolver>> {
        self.sorafs_blinded_resolver.as_ref()
    }

    #[cfg(feature = "app_api")]
    #[allow(clippy::result_large_err)]
    fn evaluate_gateway_policy(
        &self,
        ctx: sorafs::gateway::RequestContext<'_>,
    ) -> Result<(), sorafs::gateway::PolicyViolation> {
        let Some(policy) = &self.sorafs_gateway_policy else {
            return Ok(());
        };
        match policy.evaluate(&ctx) {
            sorafs::gateway::PolicyDecision::Allow => Ok(()),
            sorafs::gateway::PolicyDecision::Deny(violation) => {
                #[cfg(feature = "telemetry")]
                {
                    let (reason, detail) = violation.telemetry_labels();
                    self.telemetry.with_metrics(|metrics| {
                        metrics.record_sorafs_gar_violation(reason, detail);
                    });
                }
                self.publish_gar_violation_event(&ctx, &violation);
                Err(violation)
            }
        }
    }

    #[cfg(feature = "app_api")]
    fn publish_gar_violation_event(
        &self,
        ctx: &sorafs::gateway::RequestContext<'_>,
        violation: &sorafs::gateway::PolicyViolation,
    ) {
        let payload = sorafs::gateway::build_gar_violation_event(ctx, violation);
        let data_event = DataEvent::Sorafs(SorafsGatewayEvent::GarViolation(payload));
        let event = SharedDataEvent::from(data_event);
        if let Err(err) = self.events.send(EventBox::Data(event)) {
            iroha_logger::warn!(?err, "failed to broadcast SoraFS GAR violation event");
        }
    }

    #[cfg(feature = "app_api")]
    fn current_tls_snapshot(&self) -> Option<sorafs::gateway::TlsStateSnapshot> {
        let state = self.sorafs_gateway_tls_state.as_ref()?;
        let snapshot = state.try_read().ok()?.clone();
        #[cfg(feature = "telemetry")]
        self.telemetry
            .with_metrics(|metrics| snapshot.apply_metrics(metrics, SystemTime::now()));
        Some(snapshot)
    }

    #[cfg(feature = "app_api")]
    fn provider_supports_chunk_range(&self, provider_id: &[u8; 32]) -> Option<bool> {
        self.provider_supports_capability(provider_id, CapabilityType::ChunkRangeFetch)
    }

    #[cfg(feature = "app_api")]
    fn provider_supports_capability(
        &self,
        provider_id: &[u8; 32],
        capability: CapabilityType,
    ) -> Option<bool> {
        if let Some(override_entry) = self.sorafs_chunk_range_overrides.get(provider_id) {
            if capability == CapabilityType::ChunkRangeFetch {
                return Some(*override_entry);
            }
        }
        let cache = self.sorafs_cache.as_ref()?;
        let guard = cache.try_read().ok()?;
        let record = guard.record_by_provider(provider_id)?;
        let supported = record.known_capabilities().contains(&capability);
        Some(supported)
    }
}

#[derive(Debug, PartialEq, Eq)]
enum NoritoRpcGateFailure {
    Disabled,
    CanaryDenied,
    MtlsRequired,
}

#[derive(
    Debug,
    Clone,
    PartialEq,
    Eq,
    crate::json_macros::JsonSerialize,
    crate::json_macros::JsonDeserialize,
    norito::derive::NoritoSerialize,
    norito::derive::NoritoDeserialize,
)]
/// Response body for `/rpc/capabilities`.
struct RpcCapabilitiesResponse {
    /// Norito-RPC capability advert.
    norito_rpc: RpcNoritoRpcCapability,
}

#[derive(
    Debug,
    Clone,
    PartialEq,
    Eq,
    crate::json_macros::JsonSerialize,
    crate::json_macros::JsonDeserialize,
    norito::derive::NoritoSerialize,
    norito::derive::NoritoDeserialize,
)]
/// Response body for `/rpc/ping`.
struct RpcPingResponse {
    /// Whether the node is healthy.
    ok: bool,
    /// Current UNIX timestamp reported by the node (milliseconds).
    unix_time_ms: u64,
    /// Norito-RPC capability advert.
    norito_rpc: RpcNoritoRpcCapability,
}

#[derive(
    Debug,
    Clone,
    PartialEq,
    Eq,
    crate::json_macros::JsonSerialize,
    crate::json_macros::JsonDeserialize,
    norito::derive::NoritoSerialize,
    norito::derive::NoritoDeserialize,
)]
/// Norito-RPC rollout summary shared with RPC clients.
struct RpcNoritoRpcCapability {
    /// Whether Norito-RPC decoding is enabled.
    enabled: bool,
    /// Whether ingress requires mTLS before allowing Norito-RPC.
    require_mtls: bool,
    /// Rollout stage label (`disabled`, `canary`, `ga`).
    stage: String,
    /// Size of the canary allowlist.
    canary_allowlist_size: usize,
}

impl From<&NoritoRpcTransport> for RpcNoritoRpcCapability {
    fn from(value: &NoritoRpcTransport) -> Self {
        Self {
            enabled: value.enabled,
            require_mtls: value.require_mtls,
            stage: value.stage.label().to_string(),
            canary_allowlist_size: value.allowed_clients.len(),
        }
    }
}

fn evaluate_norito_rpc_gate(
    cfg: &NoritoRpcTransport,
    trusted_proxy_nets: &[limits::IpNet],
    headers: &HeaderMap,
    remote_ip: Option<IpAddr>,
) -> Result<(), NoritoRpcGateFailure> {
    if !cfg.enabled {
        return Err(NoritoRpcGateFailure::Disabled);
    }
    if cfg.require_mtls && !norito_rpc_mtls_present(headers, remote_ip, trusted_proxy_nets) {
        return Err(NoritoRpcGateFailure::MtlsRequired);
    }
    match cfg.stage {
        NoritoRpcStage::Disabled => Err(NoritoRpcGateFailure::Disabled),
        NoritoRpcStage::Ga => Ok(()),
        NoritoRpcStage::Canary => {
            let token =
                norito_rpc_token_from_headers(headers).ok_or(NoritoRpcGateFailure::CanaryDenied)?;
            if cfg.allowed_clients.iter().any(|allowed| allowed == token) {
                Ok(())
            } else {
                Err(NoritoRpcGateFailure::CanaryDenied)
            }
        }
    }
}

fn norito_rpc_token_from_headers(headers: &HeaderMap) -> Option<&str> {
    headers
        .get(HEADER_API_TOKEN)
        .and_then(|value| value.to_str().ok())
        .filter(|value| !value.is_empty())
}

fn norito_rpc_mtls_present(
    headers: &HeaderMap,
    remote: Option<IpAddr>,
    trusted_proxies: &[limits::IpNet],
) -> bool {
    limits::has_trusted_forwarded_header(headers, remote, trusted_proxies, HEADER_MTLS_FORWARD)
}

fn norito_rpc_error_response(failure: NoritoRpcGateFailure) -> axum::response::Response {
    match failure {
        NoritoRpcGateFailure::Disabled => norito_rpc_error(
            StatusCode::FORBIDDEN,
            NORITO_RPC_DISABLED_CODE,
            "Norito-RPC is disabled on this Torii node",
        ),
        NoritoRpcGateFailure::CanaryDenied => norito_rpc_error(
            StatusCode::FORBIDDEN,
            NORITO_RPC_CANARY_DENIED_CODE,
            "Norito-RPC canary allowlist rejected this token",
        ),
        NoritoRpcGateFailure::MtlsRequired => norito_rpc_error(
            StatusCode::FORBIDDEN,
            NORITO_RPC_MTLS_REQUIRED_CODE,
            "Norito-RPC requires mTLS at ingress",
        ),
    }
}

fn norito_rpc_error(
    status: StatusCode,
    code: &str,
    message: &'static str,
) -> axum::response::Response {
    match axum::response::Response::builder()
        .status(status)
        .header(HEADER_NORITO_RPC_ERROR, code)
        .header(
            axum::http::header::RETRY_AFTER,
            NORITO_RPC_RETRY_AFTER_SECONDS,
        )
        .body(Body::from(message))
    {
        Ok(response) => response,
        Err(err) => {
            iroha_logger::error!(?err, "failed to build Norito-RPC gate error response");
            axum::response::Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .body(Body::from("failed to evaluate Norito-RPC gate"))
                .expect("static response build succeeds")
        }
    }
}

async fn inject_remote_addr_header(
    State(app): State<SharedAppState>,
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    use axum::{extract::ConnectInfo, http::header::HeaderName};

    let header = HeaderName::from_static(limits::REMOTE_ADDR_HEADER);
    let remote_ip = req
        .extensions()
        .get::<ConnectInfo<std::net::SocketAddr>>()
        .map(|connect| connect.0.ip());
    let resolved = limits::ingress_remote_ip(req.headers(), remote_ip, &app.trusted_proxy_nets);
    req.headers_mut().remove(&header);
    if let Some(ip) = resolved {
        if let Ok(value) = ip.to_string().parse() {
            req.headers_mut().insert(header, value);
        }
    }

    Ok(next.run(req).await)
}

const REQUEST_ID_HEADER: &str = "x-request-id";
const MAX_REQUEST_ID_LENGTH: usize = 128;

#[derive(Clone, Debug)]
struct RequestCorrelationId(String);

fn valid_incoming_request_id(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= MAX_REQUEST_ID_LENGTH
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b':'))
}

fn generate_request_id() -> String {
    static SEQUENCE: AtomicU64 = AtomicU64::new(1);

    let timestamp_nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let sequence = SEQUENCE.fetch_add(1, AtomicOrdering::Relaxed);
    let process_id = std::process::id();
    let mut material = Vec::with_capacity(16 + 8 + 4);
    material.extend_from_slice(&timestamp_nanos.to_le_bytes());
    material.extend_from_slice(&sequence.to_le_bytes());
    material.extend_from_slice(&process_id.to_le_bytes());
    hex::encode(blake3_hash(&material).as_bytes())
}

fn single_valid_incoming_request_id(headers: &HeaderMap) -> Option<&str> {
    let mut values = headers.get_all(REQUEST_ID_HEADER).iter();
    let value = values.next()?;
    if values.next().is_some() {
        return None;
    }
    value
        .to_str()
        .ok()
        .filter(|value| valid_incoming_request_id(value))
}

async fn attach_request_id(
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    let request_id = single_valid_incoming_request_id(req.headers())
        .map(str::to_owned)
        .unwrap_or_else(generate_request_id);
    req.extensions_mut()
        .insert(RequestCorrelationId(request_id.clone()));

    let mut response = next.run(req).await;
    if let Ok(value) = HeaderValue::from_str(&request_id) {
        response
            .headers_mut()
            .insert(HeaderName::from_static(REQUEST_ID_HEADER), value);
    }
    Ok(response)
}

async fn inject_loopback_connect_info_when_missing(
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    if req
        .extensions()
        .get::<axum::extract::ConnectInfo<std::net::SocketAddr>>()
        .is_none()
    {
        req.extensions_mut()
            .insert(axum::extract::ConnectInfo(std::net::SocketAddr::from((
                [127, 0, 0, 1],
                0,
            ))));
    }

    Ok(next.run(req).await)
}

async fn enforce_preauth(
    State(app): State<SharedAppState>,
    mut req: axum::http::Request<Body>,
    next: Next,
) -> Result<axum::response::Response, Infallible> {
    use axum::{extract::ConnectInfo, response::IntoResponse};

    let transport_ip = req
        .extensions()
        .get::<ConnectInfo<std::net::SocketAddr>>()
        .map(|ci| ci.0.ip());
    // `inject_remote_addr_header` runs before this middleware and replaces any
    // untrusted caller-supplied value with the accepted transport address.
    // Use that normalized client address so trusted reverse-proxy traffic does
    // not collapse into a single pre-auth bucket keyed by the proxy itself.
    let remote_ip = limits::effective_remote_ip(req.headers(), transport_ip);
    let scheme = ConnScheme::from_request(&req);
    match app.acquire_preauth(remote_ip, scheme).await {
        Ok(guard) => {
            if matches!(scheme, ConnScheme::NoritoRpc) {
                if let Err(resp) = app.check_norito_rpc_allowed(req.headers(), remote_ip) {
                    drop(guard);
                    return Ok(*resp);
                }
            }

            let handoff = PreAuthGuardHandoff::new(guard);
            req.extensions_mut().insert(handoff.clone());
            let response = next.run(req).await;
            Ok(match handoff.take() {
                Some(guard) => hold_preauth_guard_in_response_body(response, guard),
                None => response,
            })
        }
        Err(reason) => {
            app.record_preauth_reject(reason);
            let (status, code, message) = match reason {
                limits::RejectReason::GlobalCap => (
                    StatusCode::SERVICE_UNAVAILABLE,
                    "preauth_global_capacity",
                    "Torii pre-auth global connection limit reached.",
                ),
                limits::RejectReason::IpCap => (
                    StatusCode::TOO_MANY_REQUESTS,
                    "preauth_ip_capacity",
                    "Torii pre-auth per-IP connection limit reached.",
                ),
                limits::RejectReason::RateLimited => (
                    StatusCode::TOO_MANY_REQUESTS,
                    "preauth_rate_limited",
                    "Torii pre-auth rate limit exceeded.",
                ),
                limits::RejectReason::Banned => (
                    StatusCode::TOO_MANY_REQUESTS,
                    "preauth_temporarily_banned",
                    "Torii pre-auth temporary ban is in effect.",
                ),
                limits::RejectReason::SchemeCap => (
                    StatusCode::TOO_MANY_REQUESTS,
                    "preauth_scheme_capacity",
                    "Torii pre-auth transport connection limit reached.",
                ),
            };
            let payload = ErrorEnvelope::new(code, message).with_details(ErrorDetails {
                retry_after_seconds: Some(1),
                ..Default::default()
            });
            let mut response = utils::respond_with_status_and_format(
                status,
                payload,
                early_rejection_response_format(req.headers()),
            );
            response.headers_mut().insert(
                axum::http::header::RETRY_AFTER,
                HeaderValue::from_static("1"),
            );
            append_vary_accept(response.headers_mut());
            Ok(response)
        }
    }
}

