#[cfg(feature = "app_api")]
#[axum::debug_handler]
async fn handler_explorer_account_detail(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    AxPath(account_raw): AxPath<String>,
) -> Result<AxResponse, Error> {
    let remote_ip = remote.ip();
    let rate_limit_bypassed =
        limits::is_allowed_by_cidr(&headers, Some(remote_ip), &app.api_rate_limit_bypass_nets);
    if !rate_limit_bypassed {
        check_access(&app, &headers, Some(remote_ip), "v1/explorer/accounts/{id}").await?;
    }
    let (parsed_account_id, canonical_account_id) = routing::parse_account_path_segment_with_state(
        app.state.as_ref(),
        &account_raw,
        &app.telemetry_handle(),
        CONTEXT_EXPLORER_ACCOUNT_DETAIL,
    )?;
    let visibility = torii_visibility_account_from_headers(
        &app,
        &headers,
        &method,
        &uri,
        &[],
        CONTEXT_EXPLORER_ACCOUNT_DETAIL,
    )?;
    let use_target_account_routes =
        trusted_internal_read_source(app.as_ref(), &headers, remote_ip) || visibility.is_signed();
    let route_scope = torii_account_read_route_scope(
        &parsed_account_id,
        visibility.caller(),
        use_target_account_routes,
    );
    let routes = match torii_account_read_routes(
        app.as_ref(),
        &parsed_account_id,
        visibility.caller(),
        use_target_account_routes,
    ) {
        Ok(routes) => routes,
        Err(response) => return Ok(response),
    };
    Ok(execute_torii_singleton_read_for_routes(
        &app,
        routes,
        route_scope,
        ToriiReadEndpointV1::ExplorerAccountDetail,
        vec![canonical_account_id],
        None,
        Vec::new(),
    )
    .await)
}

