#[cfg(feature = "app_api")]
fn handle_incoming_soracloud_generated_hf_proxy_authority_failure(
    app: &SharedAppState,
    request: &SoracloudLocalReadRequest,
    error: &SoracloudRuntimeExecutionError,
) {
    maybe_request_soracloud_generated_hf_reconcile(app, request, error);
}

#[cfg(feature = "app_api")]
fn resolve_incoming_soracloud_proxy_forward_target(
    app: &SharedAppState,
    request: &SoracloudLocalReadRequest,
    error: &SoracloudRuntimeExecutionError,
) -> Option<iroha_data_model::peer::PeerId> {
    if error.kind != SoracloudRuntimeExecutionErrorKind::Unavailable {
        return None;
    }
    if !local_soracloud_proxy_receiver_is_assigned_host(app, request).ok()? {
        return None;
    }
    resolve_soracloud_local_read_proxy_target(app, request)
        .ok()
        .flatten()
}

#[cfg(feature = "app_api")]
fn local_soracloud_proxy_receiver_is_assigned_host(
    app: &SharedAppState,
    request: &SoracloudLocalReadRequest,
) -> Result<bool, SoracloudRuntimeExecutionError> {
    if request.handler_name != "infer" {
        return Ok(false);
    }
    let Some(runtime) = app.soracloud_runtime.as_ref() else {
        return Ok(false);
    };
    let Some(local_peer_id) = runtime.local_peer_id() else {
        return Ok(false);
    };
    let local_peer_id: iroha_data_model::peer::PeerId = local_peer_id.parse().map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!("invalid local Soracloud peer id `{local_peer_id}`: {error}"),
        )
    })?;

    let state_view = app.state.view();
    let Some(bundle) = state_view.world().soracloud_service_revisions().get(&(
        request.service_name.clone(),
        request.service_version.clone(),
    )) else {
        return Ok(false);
    };
    let Some(binding) =
        iroha_core::soracloud_runtime::soracloud_hf_generated_source_binding(bundle)
    else {
        return Ok(false);
    };
    let Some(placement) = iroha_core::soracloud_runtime::resolve_generated_hf_active_placement(
        state_view.world(),
        request.service_name.as_str(),
        &binding.source_id,
    )
    .map_err(|message| {
        SoracloudRuntimeExecutionError::new(SoracloudRuntimeExecutionErrorKind::Internal, message)
    })?
    else {
        return Ok(false);
    };

    Ok(placement.assigned_hosts.iter().any(|assignment| {
        assignment.peer_id == local_peer_id.to_string()
            && assignment.status
                != iroha_data_model::soracloud::SoraHfPlacementHostStatusV1::Retired
    }))
}

#[cfg(feature = "app_api")]
fn validate_generated_hf_proxy_response_authority(
    app: &SharedAppState,
    request: &SoracloudLocalReadRequest,
    target_peer_id: &iroha_data_model::peer::PeerId,
    response: &iroha_core::soracloud_runtime::SoracloudLocalReadResponse,
) -> Result<(), SoracloudRuntimeExecutionError> {
    if request.handler_name != "infer" {
        return Ok(());
    }

    let state_view = app.state.view();
    let Some(bundle) = state_view.world().soracloud_service_revisions().get(&(
        request.service_name.clone(),
        request.service_version.clone(),
    )) else {
        return Ok(());
    };
    let Some(binding) =
        iroha_core::soracloud_runtime::soracloud_hf_generated_source_binding(bundle)
    else {
        return Ok(());
    };
    let Some(receipt) = response.runtime_receipt.as_ref() else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "proxied generated HF response from primary peer `{target_peer_id}` omitted runtime receipt attribution"
            ),
        ));
    };
    receipt.validate().map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "proxied generated HF response from primary peer `{target_peer_id}` returned an invalid runtime receipt: {error}"
            ),
        )
    })?;
    if receipt.service_name.as_ref() != request.service_name
        || receipt.service_version != request.service_version
        || receipt.handler_name.as_ref() != request.handler_name
        || receipt.handler_class != request.handler_class.handler_class()
        || receipt.request_commitment != request.request_commitment
    {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "proxied generated HF response from primary peer `{target_peer_id}` returned a runtime receipt that does not match the request envelope"
            ),
        ));
    }
    if receipt.result_commitment != response.result_commitment
        || receipt.certified_by != response.certified_by
    {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "proxied generated HF response from primary peer `{target_peer_id}` returned a runtime receipt that does not match the response commitments"
            ),
        ));
    }

    let placement = iroha_core::soracloud_runtime::resolve_generated_hf_active_placement(
        state_view.world(),
        request.service_name.as_str(),
        &binding.source_id,
    )
    .map_err(|message| {
        SoracloudRuntimeExecutionError::new(SoracloudRuntimeExecutionErrorKind::Internal, message)
    })?
    .ok_or_else(|| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "generated HF service `{}` has no active placement for source `{}` while validating proxy response",
                request.service_name, binding.source_id
            ),
        )
    })?;
    let primary_assignment = placement
        .assigned_hosts
        .iter()
        .find(|assignment| {
            assignment.role
                == iroha_data_model::soracloud::SoraHfPlacementHostRoleV1::Primary
                && assignment.status
                    == iroha_data_model::soracloud::SoraHfPlacementHostStatusV1::Warm
        })
        .ok_or_else(|| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!(
                    "generated HF service `{}` has no warm authoritative primary host while validating proxy response",
                    request.service_name
                ),
            )
        })?;
    if receipt.placement_id != Some(placement.placement_id)
        || receipt.selected_validator_account_id.as_ref()
            != Some(&primary_assignment.validator_account_id)
        || receipt.selected_peer_id.as_deref() != Some(primary_assignment.peer_id.as_str())
    {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "proxied generated HF response from primary peer `{target_peer_id}` returned receipt attribution that does not match authoritative placement `{}`",
                placement.placement_id
            ),
        ));
    }
    Ok(())
}

#[cfg(all(feature = "app_api", any(feature = "p2p_ws", feature = "connect")))]
async fn execute_soracloud_local_read_via_proxy(
    app: &SharedAppState,
    target_peer_id: iroha_data_model::peer::PeerId,
    request: SoracloudLocalReadRequest,
) -> Result<iroha_core::soracloud_runtime::SoracloudLocalReadResponse, SoracloudRuntimeExecutionError>
{
    let report_request = request.clone();
    let Some(runtime) = app.soracloud_runtime.as_ref() else {
        let error = SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            "Soracloud runtime is unavailable on this ingress node",
        );
        handle_soracloud_generated_hf_local_proxy_execution_failure(app, &report_request, &error);
        return Err(error);
    };
    let Some(network) = app.p2p.as_ref() else {
        let error = SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            "Soracloud proxy routing requires an attached P2P network",
        );
        handle_soracloud_generated_hf_local_proxy_execution_failure(app, &report_request, &error);
        return Err(error);
    };

    let request_id = Hash::new(
        norito::to_bytes(&(
            "soracloud:local-read-proxy",
            app.soracloud_proxy_sequence
                .fetch_add(1, std::sync::atomic::Ordering::Relaxed),
            request.request_commitment,
            target_peer_id.clone(),
        ))
        .expect("Soracloud proxy request id encoding should be infallible"),
    );
    let (tx, rx) = tokio::sync::oneshot::channel();
    app.soracloud_proxy_pending.lock().await.insert(
        request_id,
        PendingSoracloudProxyRequest {
            sender: tx,
            expected_peer_id: target_peer_id.clone(),
            request: report_request.clone(),
        },
    );
    network.post(iroha_p2p::Post {
        peer_id: target_peer_id.clone(),
        priority: iroha_p2p::Priority::High,
        data: iroha_core::NetworkMessage::SoracloudLocalReadProxyRequest(Box::new(
            SoracloudLocalReadProxyRequestV1 {
                schema_version: SORACLOUD_LOCAL_READ_PROXY_REQUEST_VERSION_V1,
                request_id,
                request,
            },
        )),
    });

    match tokio::time::timeout(runtime.local_read_proxy_timeout(), rx).await {
        Ok(Ok(SoracloudLocalReadProxyOutcomeV1::Ok(response))) => {
            match validate_generated_hf_proxy_response_authority(
                app,
                &report_request,
                &target_peer_id,
                &response,
            ) {
                Ok(()) => Ok(response),
                Err(error) => {
                    handle_soracloud_generated_hf_proxy_validation_failure(
                        app,
                        &report_request,
                        &target_peer_id,
                        &error,
                    );
                    Err(error)
                }
            }
        }
        Ok(Ok(SoracloudLocalReadProxyOutcomeV1::Err(error))) => {
            handle_soracloud_generated_hf_proxy_execution_failure(
                app,
                &report_request,
                &target_peer_id,
                &error,
            );
            Err(error)
        }
        Ok(Err(_)) => {
            let error = SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!(
                    "Soracloud proxy request `{request_id}` to primary peer `{target_peer_id}` closed before returning a response"
                ),
            );
            handle_soracloud_generated_hf_proxy_execution_failure(
                app,
                &report_request,
                &target_peer_id,
                &error,
            );
            Err(error)
        }
        Err(_) => {
            app.soracloud_proxy_pending.lock().await.remove(&request_id);
            let error = SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!(
                    "Soracloud proxy request `{request_id}` to primary peer `{target_peer_id}` timed out"
                ),
            );
            handle_soracloud_generated_hf_proxy_execution_failure(
                app,
                &report_request,
                &target_peer_id,
                &error,
            );
            Err(error)
        }
    }
}

#[cfg(all(feature = "app_api", not(any(feature = "p2p_ws", feature = "connect"))))]
async fn execute_soracloud_local_read_via_proxy(
    _app: &SharedAppState,
    target_peer_id: iroha_data_model::peer::PeerId,
    _request: SoracloudLocalReadRequest,
) -> Result<iroha_core::soracloud_runtime::SoracloudLocalReadResponse, SoracloudRuntimeExecutionError>
{
    Err(SoracloudRuntimeExecutionError::new(
        SoracloudRuntimeExecutionErrorKind::Unavailable,
        format!("Soracloud proxy routing to primary peer `{target_peer_id}` requires P2P support"),
    ))
}

#[cfg(feature = "app_api")]
fn validate_incoming_soracloud_proxy_request_authority(
    app: &SharedAppState,
    request: &SoracloudLocalReadRequest,
) -> Result<(), SoracloudRuntimeExecutionError> {
    let expected_request_commitment = soracloud_local_read_request_commitment(request);
    if request.request_commitment != expected_request_commitment {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::InvalidRequest,
            format!(
                "Soracloud proxy request commitment `{}` does not match the canonical generated-HF request envelope `{expected_request_commitment}`",
                request.request_commitment
            ),
        ));
    }

    if request.handler_name != "infer"
        || request.handler_class != iroha_core::soracloud_runtime::SoracloudLocalReadKind::Query
    {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::InvalidRequest,
            "Soracloud proxy execution only supports generated HF `infer` query handlers",
        ));
    }

    let Some(runtime) = app.soracloud_runtime.as_ref() else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            "Soracloud runtime is unavailable on the authoritative primary host",
        ));
    };
    let Some(local_peer_id) = runtime.local_peer_id() else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            "Soracloud runtime does not advertise a local peer id for proxy execution",
        ));
    };
    let local_peer_id: iroha_data_model::peer::PeerId = local_peer_id.parse().map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!("invalid local Soracloud peer id `{local_peer_id}`: {error}"),
        )
    })?;

    let state_view = app.state.view();
    let Some(bundle) = state_view.world().soracloud_service_revisions().get(&(
        request.service_name.clone(),
        request.service_version.clone(),
    )) else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::InvalidRequest,
            format!(
                "missing admitted Soracloud revision `{}` for service `{}`",
                request.service_version, request.service_name
            ),
        ));
    };
    let Some(binding) =
        iroha_core::soracloud_runtime::soracloud_hf_generated_source_binding(bundle)
    else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::InvalidRequest,
            format!(
                "Soracloud proxy execution only supports generated HF services; `{}` is not generated-HF bound",
                request.service_name
            ),
        ));
    };

    let primary_assignment = iroha_core::soracloud_runtime::resolve_generated_hf_primary_assignment(
        state_view.world(),
        request.service_name.as_str(),
        &binding.source_id,
    )
    .map_err(|message| {
        SoracloudRuntimeExecutionError::new(SoracloudRuntimeExecutionErrorKind::Unavailable, message)
    })?
    .ok_or_else(|| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "generated HF service `{}` has no warm authoritative primary host for proxy execution",
                request.service_name
            ),
        )
    })?;
    let primary_peer_id: iroha_data_model::peer::PeerId =
        primary_assignment.peer_id.parse().map_err(|error| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!(
                    "generated HF service `{}` has an invalid authoritative primary peer id `{}`: {error}",
                    request.service_name, primary_assignment.peer_id
                ),
            )
        })?;
    if primary_peer_id != local_peer_id {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "local peer `{local_peer_id}` is not the authoritative warm primary `{primary_peer_id}` for generated HF service `{}`",
                request.service_name
            ),
        ));
    }

    Ok(())
}

#[cfg(feature = "app_api")]
async fn process_incoming_soracloud_proxy_request(
    app: SharedAppState,
    network: iroha_core::IrohaNetwork,
    peer: iroha_data_model::peer::Peer,
    proxy_request: SoracloudLocalReadProxyRequestV1,
) {
    let outcome = if proxy_request.schema_version != SORACLOUD_LOCAL_READ_PROXY_REQUEST_VERSION_V1 {
        SoracloudLocalReadProxyOutcomeV1::Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::InvalidRequest,
            format!(
                "unsupported Soracloud local-read proxy request schema_version `{}`",
                proxy_request.schema_version
            ),
        ))
    } else {
        match validate_incoming_soracloud_proxy_request_authority(&app, &proxy_request.request) {
            Ok(()) => match app.soracloud_runtime.as_ref() {
                Some(runtime) => match runtime.execute_local_read(proxy_request.request) {
                    Ok(response) => SoracloudLocalReadProxyOutcomeV1::Ok(response),
                    Err(error) => SoracloudLocalReadProxyOutcomeV1::Err(error),
                },
                None => SoracloudLocalReadProxyOutcomeV1::Err(SoracloudRuntimeExecutionError::new(
                    SoracloudRuntimeExecutionErrorKind::Unavailable,
                    "Soracloud runtime is unavailable on the authoritative primary host",
                )),
            },
            Err(error) => {
                if let Some(primary_peer_id) = resolve_incoming_soracloud_proxy_forward_target(
                    &app,
                    &proxy_request.request,
                    &error,
                ) {
                    match execute_soracloud_local_read_via_proxy(
                        &app,
                        primary_peer_id.clone(),
                        proxy_request.request.clone(),
                    )
                    .await
                    {
                        Ok(response) => SoracloudLocalReadProxyOutcomeV1::Ok(response),
                        // `execute_soracloud_local_read_via_proxy()` already reports
                        // generated-HF proxy validation and execution failures against the
                        // authoritative primary before returning the error here.
                        Err(forward_error) => SoracloudLocalReadProxyOutcomeV1::Err(forward_error),
                    }
                } else {
                    handle_incoming_soracloud_generated_hf_proxy_authority_failure(
                        &app,
                        &proxy_request.request,
                        &error,
                    );
                    SoracloudLocalReadProxyOutcomeV1::Err(error)
                }
            }
        }
    };

    network.post(iroha_p2p::Post {
        peer_id: peer.id().clone(),
        priority: iroha_p2p::Priority::High,
        data: iroha_core::NetworkMessage::SoracloudLocalReadProxyResponse(Box::new(
            SoracloudLocalReadProxyResponseV1 {
                schema_version: SORACLOUD_LOCAL_READ_PROXY_RESPONSE_VERSION_V1,
                request_id: proxy_request.request_id,
                outcome,
            },
        )),
    });
}

#[cfg(feature = "app_api")]
async fn process_incoming_soracloud_proxy_response(
    app: &SharedAppState,
    responder_peer_id: iroha_data_model::peer::PeerId,
    proxy_response: SoracloudLocalReadProxyResponseV1,
) {
    let mut pending_requests = app.soracloud_proxy_pending.lock().await;
    let Some((expected_peer_id, request)) = pending_requests
        .get(&proxy_response.request_id)
        .map(|pending| (pending.expected_peer_id.clone(), pending.request.clone()))
    else {
        iroha_logger::warn!(
            peer_id = %responder_peer_id,
            request_id = %proxy_response.request_id,
            "ignoring Soracloud local-read proxy response without a pending request"
        );
        return;
    };

    if expected_peer_id != responder_peer_id {
        drop(pending_requests);
        iroha_logger::warn!(
            peer_id = %responder_peer_id,
            expected_peer_id = %expected_peer_id,
            request_id = %proxy_response.request_id,
            "ignoring Soracloud local-read proxy response from an unexpected peer"
        );
        request_soracloud_generated_hf_proxy_responder_reconcile(
            app,
            &request,
            &responder_peer_id,
            &expected_peer_id,
        );
        return;
    }

    let Some(pending) = pending_requests.remove(&proxy_response.request_id) else {
        iroha_logger::warn!(
            peer_id = %responder_peer_id,
            request_id = %proxy_response.request_id,
            "ignoring Soracloud local-read proxy response whose pending request disappeared"
        );
        return;
    };
    drop(pending_requests);

    if proxy_response.schema_version != SORACLOUD_LOCAL_READ_PROXY_RESPONSE_VERSION_V1 {
        let _ = pending
            .sender
            .send(SoracloudLocalReadProxyOutcomeV1::Err(
                SoracloudRuntimeExecutionError::new(
                    SoracloudRuntimeExecutionErrorKind::Unavailable,
                    format!(
                        "Soracloud proxy response for request `{}` from peer `{}` used unsupported schema_version `{}`",
                        proxy_response.request_id, responder_peer_id, proxy_response.schema_version
                    ),
                ),
            ));
        return;
    }

    let _ = pending.sender.send(proxy_response.outcome);
}

fn insert_routing_headers(
    response: &mut Response,
    routing_decision: RoutingDecision,
    routed_by: &'static str,
) {
    if let Ok(lane_header) = HeaderValue::from_str(&routing_decision.lane_id.as_u32().to_string()) {
        response.headers_mut().insert(
            HeaderName::from_static("x-iroha-route-lane-id"),
            lane_header,
        );
    }
    if let Ok(dataspace_header) =
        HeaderValue::from_str(&routing_decision.dataspace_id.as_u64().to_string())
    {
        response.headers_mut().insert(
            HeaderName::from_static("x-iroha-route-dataspace-id"),
            dataspace_header,
        );
    }
    response.headers_mut().insert(
        HeaderName::from_static("x-iroha-routed-by"),
        HeaderValue::from_static(routed_by),
    );
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn insert_route_transport_header(response: &mut Response, transport: &'static str) {
    response.headers_mut().insert(
        HeaderName::from_static("x-iroha-route-transport"),
        HeaderValue::from_static(transport),
    );
}

const PREFER_RETURN_MINIMAL: &str = "return=minimal";

fn header_contains_preference(value: &HeaderValue, preference: &str) -> bool {
    value.to_str().is_ok_and(|raw| {
        raw.split(',')
            .any(|part| part.trim().eq_ignore_ascii_case(preference))
    })
}

fn transaction_submission_prefers_minimal_response(headers: &HeaderMap) -> bool {
    headers
        .get_all("prefer")
        .iter()
        .any(|value| header_contains_preference(value, PREFER_RETURN_MINIMAL))
}

fn signed_transaction_hash_for_entrypoint(
    entrypoint: &TransactionEntrypoint,
) -> Option<HashOf<SignedTransaction>> {
    match entrypoint {
        TransactionEntrypoint::External(signed) => Some(signed.hash()),
        TransactionEntrypoint::SealedReveal(reveal) => Some(reveal.signed_transaction().hash()),
        TransactionEntrypoint::SealedCommitment(_)
        | TransactionEntrypoint::PrivateKaigi(_)
        | TransactionEntrypoint::Time(_) => None,
    }
}

fn insert_transaction_submission_identity_headers(
    response: &mut Response,
    entrypoint_hash: &HashOf<TransactionEntrypoint>,
    signed_transaction_hash: Option<&HashOf<SignedTransaction>>,
) {
    if let Ok(header) = HeaderValue::from_str(&entrypoint_hash.to_string()) {
        response.headers_mut().insert(
            HeaderName::from_static("x-iroha-entrypoint-hash"),
            header.clone(),
        );
        response
            .headers_mut()
            .insert(HeaderName::from_static("x-iroha-transaction-hash"), header);
    }
    if let Some(signed_transaction_hash) = signed_transaction_hash
        && let Ok(header) = HeaderValue::from_str(&signed_transaction_hash.to_string())
    {
        response.headers_mut().insert(
            HeaderName::from_static("x-iroha-signed-transaction-hash"),
            header,
        );
    }
}

fn transaction_submission_response(
    app: &AppState,
    entrypoint_hash: HashOf<TransactionEntrypoint>,
    signed_transaction_hash: Option<HashOf<SignedTransaction>>,
    routing_decision: RoutingDecision,
    routed_by: &'static str,
    minimal_response: bool,
    format: ResponseFormat,
) -> Response {
    let tx_hash =
        HashOf::<SignedTransaction>::from_untyped_unchecked(Hash::from(entrypoint_hash.clone()));
    let mut response = if minimal_response {
        let mut response = Response::new(Body::empty());
        *response.status_mut() = StatusCode::ACCEPTED;
        response.headers_mut().insert(
            HeaderName::from_static("preference-applied"),
            HeaderValue::from_static(PREFER_RETURN_MINIMAL),
        );
        response
    } else {
        let submitted_at_height = u64::try_from(app.state.committed_height()).unwrap_or(0);
        let submitted_at_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_millis().min(u128::from(u64::MAX)) as u64)
            .unwrap_or(0);
        let payload = TransactionSubmissionReceiptPayload {
            tx_hash,
            entrypoint_hash,
            signed_transaction_hash: signed_transaction_hash.clone(),
            submitted_at_ms,
            submitted_at_height,
            signer: app.da_receipt_signer.public_key().clone(),
        };
        match TransactionSubmissionReceipt::try_sign(payload, &app.da_receipt_signer) {
            Ok(receipt) => {
                utils::respond_with_status_and_format(StatusCode::ACCEPTED, receipt, format)
            }
            Err(err) => {
                let envelope = ErrorEnvelope::new(
                    "transaction_submission_receipt_signing_failed",
                    format!("failed to sign transaction submission receipt: {err}"),
                );
                utils::respond_with_status_and_format(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    envelope,
                    format,
                )
            }
        }
    };
    insert_transaction_submission_identity_headers(
        &mut response,
        &entrypoint_hash,
        signed_transaction_hash.as_ref(),
    );
    insert_routing_headers(&mut response, routing_decision, routed_by);
    response
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn queue_plan_synced_admission_response(
    app: &AppState,
    routing_decision: RoutingDecision,
    expected_binding: QueuePlanAdmissionBindingV2,
    durable_admission: queue::QueuePlanDurableAdmissionV2,
) -> Response {
    let receipt_signer = PeerId::new(app.torii_proxy_bridge_signer.public_key().clone());
    let durable_binding =
        match QueuePlanAdmissionBindingV2::try_from_durable_admission(&durable_admission) {
            Ok(binding) => binding,
            Err(error) => {
                return torii_proxy_error_response(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "queue_plan_synced_receipt_signing_failed",
                    format!("durable admission binding is malformed: {error}"),
                );
            }
        };
    if durable_binding != expected_binding {
        return torii_proxy_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "queue_plan_synced_receipt_signing_failed",
            "durable queue admission claim does not match the exact ingress binding",
        );
    }
    let coordinator = expected_binding
        .admission_context
        .route_incarnations
        .first()
        .expect("validated QueuePlan binding has a coordinator");
    let Some(validator_index) = coordinator
        .validator_set
        .iter()
        .position(|validator| validator == &receipt_signer)
        .and_then(|index| u16::try_from(index).ok())
    else {
        return torii_proxy_error_response(
            StatusCode::INTERNAL_SERVER_ERROR,
            "queue_plan_synced_signer_mismatch",
            format!(
                "QueuePlanSynced receipt signer `{receipt_signer}` is not in the exact coordinator roster"
            ),
        );
    };
    let signing_bytes = match queue_plan_admission_attestation_signing_bytes_v2(
        expected_binding.canonical_hash(),
        validator_index,
    ) {
        Ok(bytes) => bytes,
        Err(error) => {
            return torii_proxy_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "queue_plan_synced_receipt_signing_failed",
                format!("failed to encode QueuePlan attestation: {error}"),
            );
        }
    };
    let response = match app.local_peer_id.as_ref() {
        Some(local_peer_id) if *local_peer_id == receipt_signer => {
            Signature::try_new(app.torii_proxy_bridge_signer.private_key(), &signing_bytes)
                .map(|signature| QueuePlanAdmissionCertificateV2 {
                    version: QUEUE_PLAN_ADMISSION_CERTIFICATE_VERSION_V2,
                    binding: expected_binding.clone(),
                    attestations: vec![QueuePlanAdmissionAttestationV2 {
                        version: QUEUE_PLAN_ADMISSION_ATTESTATION_VERSION_V2,
                        validator_index,
                        signature,
                    }],
                })
                .map_err(|error| {
                    (
                        "queue_plan_synced_receipt_signing_failed",
                        error.to_string(),
                    )
                })
        }
        Some(local_peer_id) => Err((
            "queue_plan_synced_signer_mismatch",
            format!(
                "configured local peer `{local_peer_id}` does not match the QueuePlanSynced receipt signer `{receipt_signer}`"
            ),
        )),
        None => Err((
            "queue_plan_synced_signer_mismatch",
            "QueuePlanSynced admission requires a configured local peer id".to_owned(),
        )),
    };
    let mut response = match response {
        Ok(certificate) => (StatusCode::ACCEPTED, utils::NoritoBody(certificate)).into_response(),
        Err((code, error)) => utils::respond_with_status_and_format(
            StatusCode::INTERNAL_SERVER_ERROR,
            ErrorEnvelope::new(
                code,
                format!("failed to produce QueuePlanSynced admission receipt: {error}"),
            ),
            ResponseFormat::Norito,
        ),
    };
    insert_transaction_submission_identity_headers(
        &mut response,
        &expected_binding.entrypoint_hash,
        expected_binding.signed_transaction_hash.as_ref(),
    );
    insert_routing_headers(&mut response, routing_decision, "proxy");
    response
}

fn routing_resolve_error_to_torii_error(
    app: &SharedAppState,
    error: queue::RoutingResolveError,
) -> Error {
    Error::PushIntoQueue {
        source: Box::new(queue::Error::UnresolvedRoute {
            reason: error.to_string(),
        }),
        backpressure: current_torii_backpressure(app.as_ref()),
    }
}

fn resolve_signed_query_routing(
    app: &AppState,
    query: &SignedQuery,
) -> Result<RoutingDecision, queue::RoutingResolveError> {
    resolve_signed_query_authority_routing(app, &query.payload.authority)
}

fn resolve_signed_query_authority_routing(
    app: &AppState,
    authority: &AccountId,
) -> Result<RoutingDecision, queue::RoutingResolveError> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    iroha_core::queue::resolve_query_routing_decision(
        &nexus.routing_policy,
        &nexus.lane_catalog,
        &nexus.dataspace_catalog,
        authority,
        Some(&state_view),
    )
}

fn resolve_signed_query_routing_for_app(
    app: &AppState,
    query: &SignedQuery,
) -> Result<RoutingDecision, queue::RoutingResolveError> {
    match signed_query_scope_for_app(app, query) {
        SignedQueryScope::TargetAccount(account_id) => {
            resolve_torii_target_account_routes(app, &account_id).map(|mut routes| {
                debug_assert!(
                    routes.len() <= 1,
                    "single-route signed-query proxy requests must not expand into fanout routes"
                );
                routes.pop().unwrap_or_else(RoutingDecision::default)
            })
        }
        SignedQueryScope::TargetAlias(alias) => {
            resolve_torii_target_alias_routes(app, &alias).map(|mut routes| {
                debug_assert!(
                    routes.len() <= 1,
                    "single-route signed-query proxy requests must not expand into fanout routes"
                );
                routes.pop().unwrap_or_else(RoutingDecision::default)
            })
        }
        SignedQueryScope::TargetDomain(domain_id) => {
            resolve_torii_target_domain_routes(app, &domain_id).map(|mut routes| {
                debug_assert!(
                    routes.len() <= 1,
                    "single-route signed-query proxy requests must not expand into fanout routes"
                );
                routes.pop().unwrap_or_else(RoutingDecision::default)
            })
        }
        SignedQueryScope::PublicControlPlane
        | SignedQueryScope::LocalReplicated
        | SignedQueryScope::AuthorityRouted
        | SignedQueryScope::CrossDataspaceFanout => resolve_signed_query_routing(app, query),
    }
}

fn torii_lane_active_for_routing(
    app: &AppState,
    nexus: &iroha_config::parameters::actual::Nexus,
    lane_id: LaneId,
) -> bool {
    !nexus.enabled || app.state.is_lane_active_for_authority(lane_id)
}

fn torii_active_lane_ids_for_status(
    app: &AppState,
    nexus: &iroha_config::parameters::actual::Nexus,
) -> Vec<u32> {
    let mut lane_ids = nexus
        .lane_catalog
        .lanes()
        .iter()
        .filter(|lane| torii_lane_active_for_routing(app, nexus, lane.id))
        .map(|lane| lane.id.as_u32())
        .collect::<Vec<_>>();
    lane_ids.sort_unstable();
    lane_ids.dedup();
    lane_ids
}

fn torii_autoscale_capacity_lane_ids_for_status(
    app: &AppState,
    nexus: &iroha_config::parameters::actual::Nexus,
) -> Vec<u32> {
    if !nexus.enabled || !nexus.autoscale.enabled {
        return Vec::new();
    }
    let mut lane_ids = nexus
        .lane_catalog
        .lanes()
        .iter()
        .filter(|lane| lane.is_autoscale_managed_elastic())
        .filter(|lane| torii_lane_active_for_routing(app, nexus, lane.id))
        .map(|lane| lane.id.as_u32())
        .collect::<Vec<_>>();
    lane_ids.sort_unstable();
    lane_ids.dedup();
    lane_ids
}

fn resolve_torii_route_for_dataspace_id(
    app: &AppState,
    dataspace_id: iroha_data_model::nexus::DataSpaceId,
) -> Result<RoutingDecision, queue::RoutingResolveError> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let lane_id = nexus
        .lane_catalog
        .lanes()
        .iter()
        .filter(|lane| {
            lane.dataspace_id == dataspace_id && torii_lane_active_for_routing(app, nexus, lane.id)
        })
        .map(|lane| lane.id)
        .min()
        .or_else(|| {
            (dataspace_id != DataSpaceId::UNIVERSAL).then(|| {
                nexus
                    .lane_catalog
                    .lanes()
                    .iter()
                    .find(|lane| {
                        lane.id == LaneId::SINGLE
                            && lane.dataspace_id == DataSpaceId::UNIVERSAL
                            && torii_lane_active_for_routing(app, nexus, lane.id)
                    })
                    .map(|lane| lane.id)
            })?
        })
        .ok_or(queue::RoutingResolveError::NoLaneForDataspace { dataspace_id })?;

    iroha_core::queue::resolve_routing_decision(
        RoutingDecision::new(lane_id, dataspace_id),
        &nexus.lane_catalog,
        &nexus.dataspace_catalog,
    )
}

fn torii_routes_for_dataspaces(
    app: &AppState,
    dataspaces: impl IntoIterator<Item = iroha_data_model::nexus::DataSpaceId>,
) -> Result<Vec<RoutingDecision>, queue::RoutingResolveError> {
    let mut routes = BTreeMap::new();
    for dataspace_id in dataspaces {
        let route = resolve_torii_route_for_dataspace_id(app, dataspace_id)?;
        routes.entry(route.dataspace_id).or_insert(route);
    }
    Ok(routes.into_values().collect())
}

fn torii_target_account_routes(
    app: &AppState,
    account_id: &AccountId,
) -> Result<Vec<RoutingDecision>, Response> {
    resolve_torii_target_account_routes(app, account_id).map_err(|error| {
        torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!("failed to resolve target-account routes for {account_id}: {error}"),
        )
    })
}

fn resolve_torii_target_account_routes(
    app: &AppState,
    account_id: &AccountId,
) -> Result<Vec<RoutingDecision>, queue::RoutingResolveError> {
    let state_view = app.state.view();
    let world = state_view.world();
    let account_scope = world.account_scope_entry(account_id).map_err(|_error| {
        queue::RoutingResolveError::UnknownDataspace {
            dataspace_id: DataSpaceId::UNIVERSAL,
        }
    })?;

    let mut dataspaces: BTreeSet<_> = account_scope.map_or_else(
        || {
            // Fresh private-dataspace accounts can be queryable on another authoritative peer
            // before the local world view can derive their account scope. Do not collapse those
            // reads to GLOBAL only; fan out across every configured dataspace route instead.
            torii_all_dataspace_routes(app)
                .into_iter()
                .map(|route| route.dataspace_id)
                .collect()
        },
        |entry| {
            entry
                .iter()
                .map(|(dataspace_id, _)| *dataspace_id)
                .collect()
        },
    );
    dataspaces.extend(torii_public_dataspace_ids(app));

    torii_routes_for_dataspaces(app, dataspaces)
}

fn torii_target_alias_routes(
    app: &AppState,
    alias: &iroha_data_model::account::AccountAlias,
) -> Result<Vec<RoutingDecision>, Response> {
    resolve_torii_target_alias_routes(app, alias).map_err(|error| {
        torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!("failed to resolve target-alias routes for {alias:?}: {error}"),
        )
    })
}

fn resolve_torii_target_alias_routes(
    app: &AppState,
    alias: &iroha_data_model::account::AccountAlias,
) -> Result<Vec<RoutingDecision>, queue::RoutingResolveError> {
    torii_routes_for_dataspaces(app, [alias.dataspace])
}

fn torii_target_domain_routes(
    app: &AppState,
    domain_id: &iroha_data_model::domain::DomainId,
) -> Result<Vec<RoutingDecision>, Response> {
    resolve_torii_target_domain_routes(app, domain_id).map_err(|error| {
        torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!("failed to resolve target-domain routes for {domain_id}: {error}"),
        )
    })
}

fn resolve_torii_target_domain_routes(
    app: &AppState,
    domain_id: &iroha_data_model::domain::DomainId,
) -> Result<Vec<RoutingDecision>, queue::RoutingResolveError> {
    let dataspace_id = app
        .state
        .view()
        .nexus()
        .dataspace_catalog
        .by_alias(domain_id.dataspace().as_ref())
        .map(|entry| entry.id)
        .ok_or(queue::RoutingResolveError::UnknownDataspace {
            dataspace_id: DataSpaceId::UNIVERSAL,
        })?;

    torii_routes_for_dataspaces(app, [dataspace_id])
}

fn torii_proxy_error_response(
    status: StatusCode,
    code: &'static str,
    message: impl Into<String>,
) -> Response {
    let payload = ErrorEnvelope::new(code, message.into());
    let mut response = (status, NoritoBody(payload)).into_response();
    if let Ok(header) = HeaderValue::from_str(code) {
        response
            .headers_mut()
            .insert(HeaderName::from_static("x-iroha-reject-code"), header);
    }
    response
}

#[cfg(feature = "app_api")]
fn torii_canonical_auth_required_response(
    code: &'static str,
    message: impl Into<String>,
) -> Response {
    let mut response = torii_proxy_error_response(StatusCode::UNAUTHORIZED, code, message);
    response.headers_mut().insert(
        axum::http::header::WWW_AUTHENTICATE,
        HeaderValue::from_static("Signature"),
    );
    response
}

#[cfg(feature = "app_api")]
fn torii_alias_permission_denied_response(message: impl Into<String>) -> Response {
    torii_proxy_error_response(StatusCode::FORBIDDEN, "permission_denied", message)
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
const TORII_PROXY_DEFAULT_MAX_HOPS: u8 = 3;

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
const TORII_INTERNAL_PROXY_HTTP_PATH: &str = "/v1/internal/torii/proxy";

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
#[derive(Clone, Debug, PartialEq, Eq)]
struct AuthoritativeLanePeerStatus {
    peer_id: PeerId,
    torii_url: Option<String>,
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
#[derive(Debug)]
struct AuthoritativeLanePeers {
    authoritative: Vec<PeerId>,
    online: Vec<PeerId>,
    offline: Vec<AuthoritativeLanePeerStatus>,
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn authoritative_lane_peer_statuses(
    app: &AppState,
    routing_decision: RoutingDecision,
) -> Vec<AuthoritativeLanePeerStatus> {
    let manifest_bindings = app
        .state
        .manifest_lane_validator_bindings(routing_decision.lane_id);
    if !manifest_bindings.is_empty() {
        return manifest_bindings
            .into_iter()
            .map(|binding| AuthoritativeLanePeerStatus {
                peer_id: binding.peer_id,
                torii_url: binding.torii_url,
            })
            .collect();
    }

    app.state
        .authoritative_lane_peer_ids(routing_decision.lane_id)
        .into_iter()
        .map(|peer_id| AuthoritativeLanePeerStatus {
            peer_id,
            torii_url: None,
        })
        .collect()
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn authoritative_lane_peer_statuses_at_height(
    app: &AppState,
    routing_decision: RoutingDecision,
    authority_height: u64,
) -> Vec<AuthoritativeLanePeerStatus> {
    let manifest_bindings = app
        .state
        .manifest_lane_validator_bindings_at_height(routing_decision.lane_id, authority_height);
    if !manifest_bindings.is_empty() {
        return manifest_bindings
            .into_iter()
            .map(|binding| AuthoritativeLanePeerStatus {
                peer_id: binding.peer_id,
                torii_url: binding.torii_url,
            })
            .collect();
    }

    app.state
        .authoritative_lane_peer_ids_at_height(routing_decision.lane_id, authority_height)
        .into_iter()
        .map(|peer_id| AuthoritativeLanePeerStatus {
            peer_id,
            torii_url: None,
        })
        .collect()
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn authoritative_lane_peers(
    app: &AppState,
    routing_decision: RoutingDecision,
) -> AuthoritativeLanePeers {
    let online_peer_ids: HashSet<PeerId> = app
        .online_peers
        .get()
        .into_iter()
        .map(|peer| peer.id().clone())
        .collect();
    let statuses = authoritative_lane_peer_statuses(app, routing_decision);
    let authoritative = statuses
        .iter()
        .map(|status| status.peer_id.clone())
        .collect();
    let mut online = Vec::new();
    let mut offline = Vec::new();
    for status in statuses {
        if online_peer_ids.contains(&status.peer_id) {
            online.push(status.peer_id);
        } else {
            offline.push(status);
        }
    }
    AuthoritativeLanePeers {
        authoritative,
        online,
        offline,
    }
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ToriiProxyUnavailableReason {
    MissingAuthoritativeBinding,
    AuthoritativePeersOffline,
    LoopPreventionExhausted,
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
impl ToriiProxyUnavailableReason {
    fn as_label(self) -> &'static str {
        match self {
            Self::MissingAuthoritativeBinding => "missing_authoritative_binding",
            Self::AuthoritativePeersOffline => "authoritative_peers_offline",
            Self::LoopPreventionExhausted => "loop_prevention_exhausted",
        }
    }

    fn ingress_message(self, routing_decision: RoutingDecision) -> String {
        match self {
            Self::MissingAuthoritativeBinding => format!(
                "no authoritative peer binding is registered for lane {} dataspace {}",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
            Self::AuthoritativePeersOffline => format!(
                "all authoritative peers are currently unavailable for lane {} dataspace {}",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
            Self::LoopPreventionExhausted => format!(
                "no authoritative peers remain after loop prevention for lane {} dataspace {}",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
        }
    }

    fn forwarded_message(self, routing_decision: RoutingDecision, hop_count: u8) -> String {
        match self {
            Self::LoopPreventionExhausted => format!(
                "no authoritative proxy candidates remain for lane {} dataspace {} after {} hops",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64(),
                hop_count
            ),
            _ => self.ingress_message(routing_decision),
        }
    }
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
#[derive(Clone, Debug, PartialEq, Eq)]
enum ToriiProxyCandidate {
    Local(PeerId),
    P2p(PeerId),
    HttpBridge { peer_id: PeerId, torii_url: String },
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
impl ToriiProxyCandidate {
    fn peer_id(&self) -> &PeerId {
        match self {
            Self::Local(peer_id) | Self::P2p(peer_id) | Self::HttpBridge { peer_id, .. } => peer_id,
        }
    }

    fn transport_label(&self) -> &'static str {
        match self {
            Self::Local(_) => "local_quorum",
            Self::P2p(_) => "p2p_proxy",
            Self::HttpBridge { .. } => "http_bridge",
        }
    }
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
#[derive(Debug)]
struct ToriiProxyCandidatePeers {
    peers: Vec<ToriiProxyCandidate>,
    authoritative_count: usize,
    authoritative_total_count: usize,
    offline_authoritative_count: usize,
    bridge_authoritative_count: usize,
    loop_prevention_drops: usize,
    unavailable_reason: Option<ToriiProxyUnavailableReason>,
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn insert_route_unavailable_diagnostics(
    response: &mut Response,
    routing_decision: RoutingDecision,
    reason: ToriiProxyUnavailableReason,
    authoritative_total_count: usize,
    offline_authoritative_count: usize,
    loop_prevention_drops: usize,
) {
    insert_routing_headers(response, routing_decision, "proxy");
    response.headers_mut().insert(
        HeaderName::from_static("x-iroha-route-unavailable-reason"),
        HeaderValue::from_static(reason.as_label()),
    );
    insert_usize_header(
        response,
        "x-iroha-route-authoritative-total",
        authoritative_total_count,
    );
    insert_usize_header(
        response,
        "x-iroha-route-authoritative-offline",
        offline_authoritative_count,
    );
    insert_usize_header(
        response,
        "x-iroha-route-loop-prevention-drops",
        loop_prevention_drops,
    );
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn torii_route_unavailable_response(
    routing_decision: RoutingDecision,
    reason: ToriiProxyUnavailableReason,
    message: impl Into<String>,
    authoritative_total_count: usize,
    offline_authoritative_count: usize,
    loop_prevention_drops: usize,
) -> Response {
    let mut response = torii_proxy_error_response(
        StatusCode::SERVICE_UNAVAILABLE,
        "route_unavailable",
        message,
    );
    insert_route_unavailable_diagnostics(
        &mut response,
        routing_decision,
        reason,
        authoritative_total_count,
        offline_authoritative_count,
        loop_prevention_drops,
    );
    response
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn effective_proxy_routing_decision(
    request_kind: &'static str,
    resolved_route: RoutingDecision,
    ingress_hint: RoutingDecision,
) -> RoutingDecision {
    if resolved_route != ingress_hint {
        iroha_logger::warn!(
            request_kind,
            resolved_lane = resolved_route.lane_id.as_u32(),
            resolved_dataspace = resolved_route.dataspace_id.as_u64(),
            ingress_lane = ingress_hint.lane_id.as_u32(),
            ingress_dataspace = ingress_hint.dataspace_id.as_u64(),
            "Torii proxy receiver recomputed a different route than the ingress hint"
        );
    }
    resolved_route
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ProxyRoutingPlanMismatch {
    ingress_digest: Hash,
    receiver_digest: Hash,
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn validate_proxy_routing_plan_hint(
    expected_plan: ToriiRoutingPlanHintV1,
) -> Result<RoutingPlan, iroha_core::torii_proxy::ToriiRoutingPlanHintError> {
    expected_plan.try_into_routing_plan()
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn validate_proxy_routing_plan(
    request_kind: &'static str,
    resolved_plan: RoutingPlan,
    ingress_hint: RoutingPlan,
) -> Result<RoutingPlan, ProxyRoutingPlanMismatch> {
    if resolved_plan != ingress_hint {
        let receiver_digest = resolved_plan.digest();
        let ingress_digest = ingress_hint.digest();
        iroha_logger::warn!(
            request_kind,
            resolved_digest = %receiver_digest,
            ingress_digest = %ingress_digest,
            resolved_lane = resolved_plan.coordinator_route().lane_id.as_u32(),
            resolved_dataspace = resolved_plan.coordinator_route().dataspace_id.as_u64(),
            ingress_lane = ingress_hint.coordinator_route().lane_id.as_u32(),
            ingress_dataspace = ingress_hint.coordinator_route().dataspace_id.as_u64(),
            "Torii proxy receiver rejected a different routing plan than the ingress hint"
        );
        return Err(ProxyRoutingPlanMismatch {
            ingress_digest,
            receiver_digest,
        });
    }
    Ok(resolved_plan)
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn effective_proxy_signed_query_routing_decision(
    resolved_route: RoutingDecision,
    ingress_hint: RoutingDecision,
) -> RoutingDecision {
    if resolved_route != ingress_hint {
        iroha_logger::warn!(
            resolved_lane = resolved_route.lane_id.as_u32(),
            resolved_dataspace = resolved_route.dataspace_id.as_u64(),
            ingress_lane = ingress_hint.lane_id.as_u32(),
            ingress_dataspace = ingress_hint.dataspace_id.as_u64(),
            "Torii proxy signed-query receiver recomputed a different route than the ingress hint"
        );
    }
    resolved_route
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
#[derive(Debug)]
struct HostedHttpProxyCandidatePeers {
    peers: Vec<PeerId>,
    loop_prevention_drops: usize,
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn hosted_http_proxy_candidate_peer_ids(
    app: &AppState,
    local_peer_id: &PeerId,
    authoritative_peer_ids: &[PeerId],
    visited_peer_ids: &[PeerId],
) -> HostedHttpProxyCandidatePeers {
    let exclusion_set: BTreeSet<_> = visited_peer_ids.iter().cloned().collect();
    let mut loop_prevention_drops = 0usize;
    let online_peer_ids = app
        .online_peers
        .get()
        .into_iter()
        .map(|peer| peer.id().clone())
        .collect::<BTreeSet<_>>();
    let mut peers = authoritative_peer_ids
        .iter()
        .filter(|peer_id| *peer_id != local_peer_id)
        .filter(|peer_id| online_peer_ids.contains(*peer_id))
        .filter(|peer_id| {
            if exclusion_set.contains(peer_id) {
                loop_prevention_drops = loop_prevention_drops.saturating_add(1);
                false
            } else {
                true
            }
        })
        .cloned()
        .collect::<Vec<_>>();
    peers.sort_by_key(ToString::to_string);
    peers.dedup();
    HostedHttpProxyCandidatePeers {
        peers,
        loop_prevention_drops,
    }
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn torii_proxy_candidate_peer_ids(
    app: &AppState,
    local_peer_id: &PeerId,
    routing_decision: RoutingDecision,
    immediate_sender_peer_id: Option<&PeerId>,
    visited_peer_ids: &[PeerId],
) -> ToriiProxyCandidatePeers {
    let mut loop_prevention_seen = BTreeSet::new();
    let mut loop_prevention_drops = 0usize;
    let exclusion_set: BTreeSet<_> = immediate_sender_peer_id
        .into_iter()
        .cloned()
        .chain(visited_peer_ids.iter().cloned())
        .collect();
    let authoritative_peers = authoritative_lane_peers(app, routing_decision);
    let authoritative_total_count = authoritative_peers.authoritative.len();
    let offline_authoritative_count = authoritative_peers.offline.len();
    let reachable_authoritative_count = authoritative_peers.online.len().saturating_add(
        authoritative_peers
            .offline
            .iter()
            .filter(|status| status.torii_url.is_some())
            .count(),
    );
    let mut authoritative = Vec::new();
    for peer_id in authoritative_peers.online {
        if &peer_id == local_peer_id {
            continue;
        }
        if exclusion_set.contains(&peer_id) {
            if loop_prevention_seen.insert(peer_id.clone()) {
                loop_prevention_drops = loop_prevention_drops.saturating_add(1);
            }
            continue;
        }
        authoritative.push(ToriiProxyCandidate::P2p(peer_id));
    }
    let mut bridge_authoritative_count = 0usize;
    for status in authoritative_peers.offline {
        let peer_id = status.peer_id;
        if &peer_id == local_peer_id {
            continue;
        }
        if exclusion_set.contains(&peer_id) {
            if loop_prevention_seen.insert(peer_id.clone()) {
                loop_prevention_drops = loop_prevention_drops.saturating_add(1);
            }
            continue;
        }
        let Some(torii_url) = status.torii_url else {
            continue;
        };
        bridge_authoritative_count = bridge_authoritative_count.saturating_add(1);
        authoritative.push(ToriiProxyCandidate::HttpBridge { peer_id, torii_url });
    }
    let authoritative_count = authoritative.len();
    let unavailable_reason = if authoritative_count > 0 {
        None
    } else if authoritative_total_count == 0 {
        Some(ToriiProxyUnavailableReason::MissingAuthoritativeBinding)
    } else if reachable_authoritative_count == 0 {
        Some(ToriiProxyUnavailableReason::AuthoritativePeersOffline)
    } else {
        Some(ToriiProxyUnavailableReason::LoopPreventionExhausted)
    };
    ToriiProxyCandidatePeers {
        peers: authoritative,
        authoritative_count,
        authoritative_total_count,
        offline_authoritative_count,
        bridge_authoritative_count,
        loop_prevention_drops,
        unavailable_reason,
    }
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn queue_plan_synced_bound_authorities(
    request: &ToriiProxyRequestV5,
) -> Result<Option<(&[PeerId], u64)>, &'static str> {
    match &request.request {
        ToriiProxyRequestKindV4::SubmitTransaction {
            admission: ToriiProxyTransactionAdmissionV2::QueuePlanSynced,
            admission_binding: Some(binding),
            ..
        } => {
            let coordinator = binding
                .admission_context
                .route_incarnations
                .first()
                .ok_or("QueuePlanSynced binding has no coordinator route")?;
            Ok(Some((
                coordinator.validator_set.as_slice(),
                binding.admission_context.proposal_height,
            )))
        }
        ToriiProxyRequestKindV4::SubmitTransaction {
            admission: ToriiProxyTransactionAdmissionV2::QueuePlanSynced,
            ..
        } => Err("QueuePlanSynced request is missing its exact admission binding"),
        _ => Ok(None),
    }
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn queue_plan_synced_proxy_candidate_peer_ids(
    app: &AppState,
    local_peer_id: &PeerId,
    routing_decision: RoutingDecision,
    authoritative_peer_ids: &[PeerId],
    proposal_height: u64,
    immediate_sender_peer_id: Option<&PeerId>,
    visited_peer_ids: &[PeerId],
    include_local: bool,
) -> ToriiProxyCandidatePeers {
    let exclusion_set = immediate_sender_peer_id
        .into_iter()
        .chain(visited_peer_ids)
        .cloned()
        .collect::<BTreeSet<_>>();
    let online_peer_ids = app
        .online_peers
        .get()
        .into_iter()
        .map(|peer| peer.id().clone())
        .collect::<BTreeSet<_>>();
    let bridge_urls =
        authoritative_lane_peer_statuses_at_height(app, routing_decision, proposal_height)
            .into_iter()
            .filter_map(|status| status.torii_url.map(|url| (status.peer_id, url)))
            .collect::<BTreeMap<_, _>>();

    let mut peers = Vec::with_capacity(authoritative_peer_ids.len());
    let mut offline_authoritative_count = 0_usize;
    let mut bridge_authoritative_count = 0_usize;
    let mut loop_prevention_drops = 0_usize;
    for peer_id in authoritative_peer_ids {
        if peer_id == local_peer_id {
            if include_local {
                peers.push(ToriiProxyCandidate::Local(peer_id.clone()));
            }
            continue;
        }
        if exclusion_set.contains(peer_id) {
            loop_prevention_drops = loop_prevention_drops.saturating_add(1);
            continue;
        }
        if online_peer_ids.contains(peer_id) {
            peers.push(ToriiProxyCandidate::P2p(peer_id.clone()));
            continue;
        }

        offline_authoritative_count = offline_authoritative_count.saturating_add(1);
        if let Some(torii_url) = bridge_urls.get(peer_id) {
            bridge_authoritative_count = bridge_authoritative_count.saturating_add(1);
            peers.push(ToriiProxyCandidate::HttpBridge {
                peer_id: peer_id.clone(),
                torii_url: torii_url.clone(),
            });
        }
    }

    let authoritative_total_count = authoritative_peer_ids.len();
    let authoritative_count = peers.len();
    let unavailable_reason = if authoritative_count > 0 {
        None
    } else if authoritative_total_count == 0 {
        Some(ToriiProxyUnavailableReason::MissingAuthoritativeBinding)
    } else if loop_prevention_drops > 0 {
        Some(ToriiProxyUnavailableReason::LoopPreventionExhausted)
    } else {
        Some(ToriiProxyUnavailableReason::AuthoritativePeersOffline)
    };
    ToriiProxyCandidatePeers {
        peers,
        authoritative_count,
        authoritative_total_count,
        offline_authoritative_count,
        bridge_authoritative_count,
        loop_prevention_drops,
        unavailable_reason,
    }
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn torii_proxy_candidate_peer_ids_for_request(
    app: &AppState,
    local_peer_id: &PeerId,
    routing_decision: RoutingDecision,
    immediate_sender_peer_id: Option<&PeerId>,
    visited_peer_ids: &[PeerId],
    request: &ToriiProxyRequestV5,
    include_local_queue_plan_authority: bool,
) -> Result<ToriiProxyCandidatePeers, &'static str> {
    if let Some((authoritative_peer_ids, proposal_height)) =
        queue_plan_synced_bound_authorities(request)?
    {
        return Ok(queue_plan_synced_proxy_candidate_peer_ids(
            app,
            local_peer_id,
            routing_decision,
            authoritative_peer_ids,
            proposal_height,
            immediate_sender_peer_id,
            visited_peer_ids,
            include_local_queue_plan_authority,
        ));
    }
    Ok(torii_proxy_candidate_peer_ids(
        app,
        local_peer_id,
        routing_decision,
        immediate_sender_peer_id,
        visited_peer_ids,
    ))
}

#[cfg(any(feature = "app_api", feature = "p2p_ws", feature = "connect"))]
fn is_local_authoritative_for_peers(app: &AppState, authoritative_peers: &[PeerId]) -> bool {
    let Some(local_peer_id) = app.local_peer_id.as_ref() else {
        return false;
    };
    authoritative_peers
        .iter()
        .any(|peer_id| peer_id == local_peer_id)
}

#[cfg(any(feature = "app_api", feature = "p2p_ws", feature = "connect"))]
fn is_local_authoritative_for_route(app: &AppState, routing_decision: RoutingDecision) -> bool {
    let authoritative_peers = app
        .state
        .authoritative_lane_peer_ids(routing_decision.lane_id);
    is_local_authoritative_for_peers(app, &authoritative_peers)
}

#[cfg(any(feature = "app_api", feature = "p2p_ws", feature = "connect"))]
fn should_execute_route_locally(app: &AppState, routing_decision: RoutingDecision) -> bool {
    let authoritative_peers = app
        .state
        .authoritative_lane_peer_ids(routing_decision.lane_id);
    if is_local_authoritative_for_peers(app, &authoritative_peers) {
        return true;
    }

    routing_decision.lane_id == LaneId::SINGLE
        && routing_decision.dataspace_id == DataSpaceId::UNIVERSAL
        && authoritative_peers.is_empty()
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn should_execute_route_locally_cached(
    app: &AppState,
    routing_decision: RoutingDecision,
    cache: &mut Vec<(RoutingDecision, bool)>,
) -> bool {
    if let Some((_, result)) = cache
        .iter()
        .find(|(cached_route, _)| *cached_route == routing_decision)
    {
        return *result;
    }

    let result = should_execute_route_locally(app, routing_decision);
    cache.push((routing_decision, result));
    result
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn should_execute_incoming_torii_proxy_request_locally(
    app: &AppState,
    request_kind: &ToriiProxyRequestKindV4,
    routing_decision: RoutingDecision,
) -> bool {
    match request_kind {
        // Read-only requests should execute on the first ingress-selected peer. Re-running the
        // authoritative-peer selection on every receiver can create multi-hop proxy cascades when
        // lane-roster views are briefly inconsistent, which turns healthy reads into 60s+ timeouts
        // and late responses.
        ToriiProxyRequestKindV4::SignedQueryRouteScan { .. }
        | ToriiProxyRequestKindV4::SignedQueryFanout { .. }
        | ToriiProxyRequestKindV4::Read(_)
        | ToriiProxyRequestKindV4::ReadFanout(_) => true,
        ToriiProxyRequestKindV4::SubmitTransaction { .. }
        | ToriiProxyRequestKindV4::SignedQuery { .. }
        | ToriiProxyRequestKindV4::HostedHttp(_) => {
            should_execute_route_locally(app, routing_decision)
        }
    }
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn validate_incoming_read_proxy_route(
    app: &AppState,
    routing_decision: RoutingDecision,
    request_kind: &'static str,
) -> Result<RoutingDecision, Response> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let resolved = iroha_core::queue::resolve_routing_decision(
        routing_decision,
        &nexus.lane_catalog,
        &nexus.dataspace_catalog,
    )
    .map_err(|error| {
        iroha_logger::warn!(
            request_kind,
            lane = routing_decision.lane_id.as_u32(),
            dataspace = routing_decision.dataspace_id.as_u64(),
            %error,
            "Torii proxy read route no longer resolves against receiver Nexus state"
        );
        let mut response = torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!(
                "proxied {request_kind} route lane {} dataspace {} no longer resolves against receiver Nexus state: {error}",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
        );
        insert_routing_headers(&mut response, routing_decision, "proxy");
        response.headers_mut().insert(
            HeaderName::from_static("x-iroha-route-unavailable-reason"),
            HeaderValue::from_static("stale_route"),
        );
        response
    })?;
    if !torii_lane_active_for_routing(app, nexus, resolved.lane_id) {
        iroha_logger::warn!(
            request_kind,
            lane = routing_decision.lane_id.as_u32(),
            dataspace = routing_decision.dataspace_id.as_u64(),
            "Torii proxy read route is inactive at receiver authority height"
        );
        let mut response = torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!(
                "proxied {request_kind} route lane {} dataspace {} is inactive at receiver authority height",
                routing_decision.lane_id.as_u32(),
                routing_decision.dataspace_id.as_u64()
            ),
        );
        insert_routing_headers(&mut response, routing_decision, "proxy");
        response.headers_mut().insert(
            HeaderName::from_static("x-iroha-route-unavailable-reason"),
            HeaderValue::from_static("stale_route"),
        );
        return Err(response);
    }
    Ok(resolved)
}

#[cfg(feature = "app_api")]
fn torii_route_for_lane_id(
    app: &AppState,
    lane_id: iroha_data_model::nexus::LaneId,
) -> Result<RoutingDecision, Error> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let Some(lane) = nexus
        .lane_catalog
        .lanes()
        .iter()
        .find(|lane| lane.id == lane_id)
    else {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        )));
    };
    if !torii_lane_active_for_routing(app, nexus, lane_id) {
        return Err(Error::PushIntoQueue {
            source: Box::new(queue::Error::UnresolvedRoute {
                reason: format!(
                    "lane {} is inactive at the current authority height",
                    lane_id.as_u32()
                ),
            }),
            backpressure: current_torii_backpressure(app),
        });
    }

    iroha_core::queue::resolve_routing_decision(
        RoutingDecision::new(lane_id, lane.dataspace_id),
        &nexus.lane_catalog,
        &nexus.dataspace_catalog,
    )
    .map_err(|error| Error::PushIntoQueue {
        source: Box::new(queue::Error::UnresolvedRoute {
            reason: error.to_string(),
        }),
        backpressure: current_torii_backpressure(app),
    })
}

#[cfg(feature = "app_api")]
fn torii_route_for_dataspace_id(
    app: &AppState,
    dataspace_id: iroha_data_model::nexus::DataSpaceId,
) -> Result<RoutingDecision, Error> {
    resolve_torii_route_for_dataspace_id(app, dataspace_id).map_err(|error| Error::PushIntoQueue {
        source: Box::new(queue::Error::UnresolvedRoute {
            reason: error.to_string(),
        }),
        backpressure: current_torii_backpressure(app),
    })
}

#[cfg(feature = "app_api")]
fn torii_restricted_routes(app: &AppState) -> Vec<RoutingDecision> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let mut seen_dataspaces = BTreeSet::new();
    let mut routes = Vec::new();
    for lane in nexus.lane_catalog.lanes() {
        if !torii_lane_active_for_routing(app, nexus, lane.id) {
            continue;
        }
        if lane.visibility != iroha_data_model::nexus::LaneVisibility::Restricted {
            continue;
        }
        if !seen_dataspaces.insert(lane.dataspace_id) {
            continue;
        }
        let Ok(route) = iroha_core::queue::resolve_routing_decision(
            RoutingDecision::new(lane.id, lane.dataspace_id),
            &nexus.lane_catalog,
            &nexus.dataspace_catalog,
        ) else {
            continue;
        };
        routes.push(route);
    }
    routes.sort_by_key(|route| (route.dataspace_id.as_u64(), route.lane_id.as_u32()));
    routes
}

#[cfg(feature = "app_api")]
fn torii_local_restricted_routes(app: &AppState) -> Vec<RoutingDecision> {
    torii_restricted_routes(app)
        .into_iter()
        .filter(|route| is_local_authoritative_for_route(app, *route))
        .collect()
}

#[cfg(feature = "app_api")]
fn torii_preferred_private_ingress_routes(app: &AppState) -> Vec<RoutingDecision> {
    let local_restricted_routes = torii_local_restricted_routes(app);
    if !local_restricted_routes.is_empty() {
        return local_restricted_routes;
    }

    let restricted_routes = torii_restricted_routes(app);
    if restricted_routes.len() == 1 {
        return restricted_routes;
    }

    Vec::new()
}

#[cfg(feature = "app_api")]
#[derive(Debug)]
enum ToriiAccountReadVisibility {
    Signed(AccountId),
    PublicExact,
    None,
}

#[cfg(feature = "app_api")]
impl ToriiAccountReadVisibility {
    fn caller(&self) -> Option<&AccountId> {
        match self {
            Self::Signed(account_id) => Some(account_id),
            Self::PublicExact | Self::None => None,
        }
    }

    fn is_signed(&self) -> bool {
        matches!(self, Self::Signed(_))
    }
}

#[cfg(feature = "app_api")]
fn torii_signed_visibility_headers_present(headers: &HeaderMap) -> bool {
    headers.get(HEADER_SIGNATURE).is_some()
        || headers.get(HEADER_TIMESTAMP_MS).is_some()
        || headers.get(HEADER_NONCE).is_some()
        || headers.get(HEADER_WITNESS).is_some()
}

#[cfg(feature = "app_api")]
fn torii_visibility_account_from_headers(
    app: &SharedAppState,
    headers: &HeaderMap,
    method: &Method,
    uri: &Uri,
    body: &[u8],
    _endpoint: &'static str,
) -> Result<ToriiAccountReadVisibility, Error> {
    if torii_signed_visibility_headers_present(headers) {
        return crate::app_auth::verify_canonical_request(
            &app.state, headers, method, uri, body, None,
        )
        .map(|verified| {
            verified.map_or(ToriiAccountReadVisibility::None, |request| {
                ToriiAccountReadVisibility::Signed(request.account)
            })
        });
    }

    if headers.get(HEADER_ACCOUNT).is_some() {
        return Err(Error::AppUnauthorized {
            code: "alias_auth_invalid",
            message: "X-Iroha-Account requires a complete canonical request signature header set"
                .to_owned(),
        });
    }

    Ok(ToriiAccountReadVisibility::None)
}

fn torii_visible_account_read_routes(
    app: &AppState,
    caller: Option<&AccountId>,
) -> Vec<RoutingDecision> {
    let state_view = app.state.view();
    let world = state_view.world();
    let mut visible_dataspaces = torii_public_dataspace_ids(app);

    if let Some(caller) = caller
        && let Ok(account) = world.account(caller)
        && let Some(uaid) = account.value().uaid().copied()
        && let Some(bindings) = world.uaid_dataspaces().get(&uaid)
    {
        visible_dataspaces.extend(bindings.iter().map(|(dataspace_id, _)| *dataspace_id));
    }

    if let Some(caller) = caller {
        visible_dataspaces.extend(
            torii_all_dataspace_routes(app)
                .into_iter()
                .filter(|route| {
                    let permission: Permission = CanReadRestrictedDataspace {
                        dataspace: route.dataspace_id,
                    }
                    .into();
                    torii_account_has_permission(world, caller, &permission)
                })
                .map(|route| route.dataspace_id),
        );
    }

    torii_all_dataspace_routes(app)
        .into_iter()
        .filter(|route| visible_dataspaces.contains(&route.dataspace_id))
        .collect()
}

fn torii_public_dataspace_ids(app: &AppState) -> BTreeSet<DataSpaceId> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let mut dataspaces = BTreeSet::new();

    for lane in nexus.lane_catalog.lanes() {
        if lane.visibility == iroha_data_model::nexus::LaneVisibility::Public
            && torii_lane_active_for_routing(app, nexus, lane.id)
        {
            dataspaces.insert(lane.dataspace_id);
        }
    }

    dataspaces
}

#[cfg(feature = "app_api")]
fn torii_partition_routes_by_visibility(
    app: &SharedAppState,
    routes: Vec<RoutingDecision>,
    visibility: &ToriiAccountReadVisibility,
) -> (Vec<RoutingDecision>, usize) {
    let visible_dataspaces = torii_visible_account_read_routes(app.as_ref(), visibility.caller())
        .into_iter()
        .map(|route| route.dataspace_id)
        .collect::<BTreeSet<_>>();
    let mut allowed_routes = Vec::new();
    let mut denied_routes = 0usize;

    for route in routes {
        if visible_dataspaces.contains(&route.dataspace_id) {
            allowed_routes.push(route);
        } else {
            denied_routes = denied_routes.saturating_add(1);
        }
    }

    (allowed_routes, denied_routes)
}

#[cfg(feature = "app_api")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ToriiAliasLookupRouteAccess {
    route: RoutingDecision,
    filter_by_permission: bool,
}

fn torii_account_has_permission(
    world: &impl WorldReadOnly,
    authority: &AccountId,
    target: &Permission,
) -> bool {
    match world.account_permissions_iter(authority) {
        Ok(permissions) => {
            if permissions
                .into_iter()
                .any(|permission| permission == target)
            {
                return true;
            }
        }
        Err(error) => {
            iroha_logger::warn!(
                authority = %authority,
                target_name = %target.name(),
                target_payload = %target.payload().get(),
                ?error,
                "Torii alias lookup permission check could not load authority permissions"
            );
        }
    }

    world.account_roles_iter(authority).any(|role_id| {
        world
            .roles()
            .get(role_id)
            .is_some_and(|role| role.permissions().any(|permission| permission == target))
    })
}

fn torii_global_signed_query_read_routes(
    app: &AppState,
    authority: &AccountId,
) -> Vec<RoutingDecision> {
    let public_dataspaces = torii_public_dataspace_ids(app);
    let state_view = app.state.view();
    let world = state_view.world();

    torii_all_dataspace_routes(app)
        .into_iter()
        .filter(|route| {
            public_dataspaces.contains(&route.dataspace_id)
                || torii_account_has_permission(
                    world,
                    authority,
                    &CanReadRestrictedDataspace {
                        dataspace: route.dataspace_id,
                    }
                    .into(),
                )
        })
        .collect()
}

fn torii_same_account_read_identity(
    app: &AppState,
    authority: &AccountId,
    target: &AccountId,
) -> bool {
    if authority == target {
        return true;
    }
    let state_view = app.state.view();
    let world = state_view.world();
    let authority_uaid = world
        .account(authority)
        .ok()
        .and_then(|account| account.value().uaid().copied());
    let target_uaid = world
        .account(target)
        .ok()
        .and_then(|account| account.value().uaid().copied());
    authority_uaid.is_some() && authority_uaid == target_uaid
}

fn torii_authority_can_resolve_account_alias(
    world: &impl WorldReadOnly,
    authority: &AccountId,
    alias: &AccountAlias,
) -> bool {
    if let Ok(literal) = alias.to_literal(world.dataspace_catalog())
        && let Ok(canonical_name) = literal.parse()
    {
        let exact_permission: Permission = CanResolveAccountAlias {
            scope: AccountAliasPermissionScope::Alias(
                iroha_data_model::alias_setup::ResolvedAccountAliasV1::new(
                    canonical_name,
                    alias.dataspace,
                ),
            ),
        }
        .into();
        if torii_account_has_permission(world, authority, &exact_permission) {
            return true;
        }
    }

    match alias.domain_id(world.dataspace_catalog()) {
        Ok(Some(domain_id)) => {
            let domain_permission: Permission = CanResolveAccountAlias {
                scope: AccountAliasPermissionScope::Domain(domain_id),
            }
            .into();
            torii_account_has_permission(world, authority, &domain_permission)
        }
        Ok(None) => {
            let dataspace_permission: Permission = CanResolveAccountAlias {
                scope: AccountAliasPermissionScope::Dataspace(alias.dataspace),
            }
            .into();
            torii_account_has_permission(world, authority, &dataspace_permission)
        }
        Err(error) => {
            iroha_logger::warn!(
                authority = %authority,
                alias = ?alias,
                ?error,
                "Torii alias lookup permission check rejected malformed alias scope"
            );
            false
        }
    }
}

fn torii_authority_can_resolve_resolved_account_alias(
    world: &impl WorldReadOnly,
    authority: &AccountId,
    alias: &iroha_data_model::alias_setup::ResolvedAccountAliasV1,
) -> bool {
    let exact_permission: Permission = CanResolveAccountAlias {
        scope: AccountAliasPermissionScope::Alias(alias.clone()),
    }
    .into();
    if torii_account_has_permission(world, authority, &exact_permission) {
        return true;
    }

    let scope = alias
        .canonical_name
        .domain_id()
        .map(AccountAliasPermissionScope::Domain)
        .unwrap_or(AccountAliasPermissionScope::Dataspace(alias.dataspace_id));
    torii_account_has_permission(
        world,
        authority,
        &Permission::from(CanResolveAccountAlias { scope }),
    )
}

#[cfg(feature = "app_api")]
fn torii_alias_lookup_permission_probe_alias(
    app: &AppState,
    dataspace_id: DataSpaceId,
    request: &routing::AliasLookupByAccountRequestDto,
) -> Option<iroha_data_model::alias_setup::ResolvedAccountAliasV1> {
    let state_view = app.state.view();
    let dataspace = iroha_core::sns::resolve_active_dataspace_alias_by_id(
        state_view.world(),
        &state_view.nexus().dataspace_catalog,
        dataspace_id,
        routing::asset_alias_observation_time_ms(&app.state),
    )
    .ok()?;
    let domain = request
        .domain
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::parse::<Name>)
        .transpose()
        .ok()?;
    let canonical_name = iroha_data_model::alias_setup::AccountAliasName::try_new(
        "lookup",
        domain.as_ref().map(|name| name.as_ref()),
        dataspace,
    )
    .ok()?;
    Some(iroha_data_model::alias_setup::ResolvedAccountAliasV1::new(
        canonical_name,
        dataspace_id,
    ))
}

#[cfg(feature = "app_api")]
fn torii_alias_lookup_dataspace_allowed_by_permission(
    app: &AppState,
    dataspace_id: DataSpaceId,
    caller: Option<&AccountId>,
    request: &routing::AliasLookupByAccountRequestDto,
) -> bool {
    let Some(caller) = caller else {
        return false;
    };
    let world_view = app.state.view();
    let world = world_view.world();
    let exact_alias_in_route = |permission: &Permission| {
        CanResolveAccountAlias::try_from(permission).is_ok_and(|permission| {
            let AccountAliasPermissionScope::Alias(alias) = permission.scope else {
                return false;
            };
            if alias.dataspace_id != dataspace_id {
                return false;
            }
            request.domain.as_deref().is_none_or(|domain| {
                alias
                    .canonical_name
                    .domain
                    .as_ref()
                    .is_some_and(|candidate| candidate.as_ref() == domain)
            })
        })
    };
    if world
        .account_permissions_iter(caller)
        .is_ok_and(|permissions| permissions.into_iter().any(exact_alias_in_route))
        || world.account_roles_iter(caller).any(|role_id| {
            world
                .roles()
                .get(role_id)
                .is_some_and(|role| role.permissions().any(exact_alias_in_route))
        })
    {
        return true;
    }
    let Some(alias) = torii_alias_lookup_permission_probe_alias(app, dataspace_id, request) else {
        return false;
    };
    torii_authority_can_resolve_resolved_account_alias(world, caller, &alias)
}

#[cfg(feature = "app_api")]
fn torii_partition_alias_lookup_routes(
    app: &SharedAppState,
    routes: Vec<RoutingDecision>,
    visibility: &ToriiAccountReadVisibility,
    request: &routing::AliasLookupByAccountRequestDto,
) -> (Vec<ToriiAliasLookupRouteAccess>, usize) {
    let public_dataspaces = torii_public_dataspace_ids(app.as_ref());
    let mut allowed_routes = Vec::new();
    let mut denied_routes = 0usize;

    for route in routes {
        if public_dataspaces.contains(&route.dataspace_id) {
            allowed_routes.push(ToriiAliasLookupRouteAccess {
                route,
                filter_by_permission: false,
            });
        } else if torii_alias_lookup_dataspace_allowed_by_permission(
            app.as_ref(),
            route.dataspace_id,
            visibility.caller(),
            request,
        ) {
            allowed_routes.push(ToriiAliasLookupRouteAccess {
                route,
                // A dataspace grant only opens the route. Each returned domain-qualified alias
                // still needs its exact domain grant before it may be disclosed.
                filter_by_permission: true,
            });
        } else if visibility.is_signed() {
            denied_routes = denied_routes.saturating_add(1);
        }
    }

    (allowed_routes, denied_routes)
}

#[cfg(feature = "app_api")]
fn torii_partition_alias_index_routes_by_permission(
    app: &SharedAppState,
    routes: Vec<RoutingDecision>,
    caller: Option<&AccountId>,
    index: u64,
) -> Result<(Vec<RoutingDecision>, usize), Error> {
    let public_dataspaces = torii_public_dataspace_ids(app.as_ref());
    let mut allowed_routes = Vec::new();
    let mut denied_routes = 0usize;

    for route in routes {
        if public_dataspaces.contains(&route.dataspace_id) {
            allowed_routes.push(route);
            continue;
        }
        let Some(caller) = caller else {
            continue;
        };
        let allowed = match resolve_alias_index_on_route(app, route, index) {
            Ok(Some((alias_literal, _))) => {
                let alias = parse_exact_account_alias_label_with_live_state(app, &alias_literal)?;
                torii_authority_can_resolve_resolved_account_alias(
                    app.state.view().world(),
                    caller,
                    &alias.resolved,
                )
            }
            Ok(None) => {
                let dataspace = {
                    let state_view = app.state.view();
                    iroha_core::sns::resolve_active_dataspace_alias_by_id(
                        state_view.world(),
                        &state_view.nexus().dataspace_catalog,
                        route.dataspace_id,
                        routing::asset_alias_observation_time_ms(&app.state),
                    )
                }
                .map_err(live_dataspace_resolution_error)?;
                let canonical_name = iroha_data_model::alias_setup::AccountAliasName::try_new(
                    "lookup",
                    Option::<&str>::None,
                    dataspace,
                )
                .expect("resolved dataspace produces a canonical probe alias");
                let resolved = iroha_data_model::alias_setup::ResolvedAccountAliasV1::new(
                    canonical_name,
                    route.dataspace_id,
                );
                torii_authority_can_resolve_resolved_account_alias(
                    app.state.view().world(),
                    caller,
                    &resolved,
                )
            }
            Err(error) => return Err(error),
        };
        if allowed {
            allowed_routes.push(route);
        } else {
            denied_routes = denied_routes.saturating_add(1);
        }
    }

    Ok((allowed_routes, denied_routes))
}

#[cfg(feature = "app_api")]
fn torii_account_read_routes(
    app: &AppState,
    target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> Result<Vec<RoutingDecision>, Response> {
    if use_target_account_routes {
        torii_target_account_routes(app, target_account)
    } else {
        Ok(torii_visible_account_read_routes(app, caller))
    }
}

#[cfg(feature = "app_api")]
fn torii_account_assets_read_routes(app: &AppState) -> Vec<RoutingDecision> {
    torii_all_dataspace_routes(app)
}

#[cfg(feature = "app_api")]
fn torii_account_permissions_read_routes(
    app: &AppState,
    _target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> Result<Vec<RoutingDecision>, Response> {
    if use_target_account_routes {
        Ok(torii_all_dataspace_routes(app))
    } else {
        Ok(torii_visible_account_read_routes(app, caller))
    }
}

#[cfg(feature = "app_api")]
fn torii_account_permissions_route_scope(
    _target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> ToriiFanoutRouteScopeV1 {
    if use_target_account_routes {
        ToriiFanoutRouteScopeV1::AllDataspaces
    } else {
        ToriiFanoutRouteScopeV1::VisibleAccount {
            caller_account_id: caller.map(ToString::to_string),
        }
    }
}

fn torii_nexus_route(app: &AppState) -> Result<RoutingDecision, Response> {
    resolve_torii_route_for_dataspace_id(app, DataSpaceId::UNIVERSAL).map_err(|error| {
        torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!("failed to resolve Nexus fanout route: {error}"),
        )
    })
}

fn parse_internal_fanout_account_id(
    account_id: &str,
    context: &'static str,
) -> Result<AccountId, Response> {
    AccountId::parse_encoded(account_id.trim())
        .map(iroha_data_model::account::ParsedAccountId::into_account_id)
        .map_err(|error| {
            torii_proxy_error_response(
                StatusCode::BAD_REQUEST,
                "invalid_proxy_request",
                format!("invalid {context} account id `{account_id}`: {error}"),
            )
        })
}

#[cfg(feature = "app_api")]
fn torii_fanout_scope_routes(
    app: &AppState,
    scope: &ToriiFanoutRouteScopeV1,
) -> Result<Vec<RoutingDecision>, Response> {
    match scope {
        ToriiFanoutRouteScopeV1::AllDataspaces => Ok(torii_all_dataspace_routes(app)),
        ToriiFanoutRouteScopeV1::TargetAccount { account_id } => {
            let account_id = parse_internal_fanout_account_id(account_id, "target")?;
            torii_target_account_routes(app, &account_id)
        }
        ToriiFanoutRouteScopeV1::VisibleAccount { caller_account_id } => {
            let caller = match caller_account_id {
                Some(account_id) => Some(parse_internal_fanout_account_id(account_id, "caller")?),
                None => None,
            };
            Ok(torii_visible_account_read_routes(app, caller.as_ref()))
        }
    }
}

#[cfg(feature = "app_api")]
fn torii_account_read_route_scope(
    target_account: &AccountId,
    caller: Option<&AccountId>,
    use_target_account_routes: bool,
) -> ToriiFanoutRouteScopeV1 {
    if use_target_account_routes {
        ToriiFanoutRouteScopeV1::TargetAccount {
            account_id: target_account.to_string(),
        }
    } else {
        ToriiFanoutRouteScopeV1::VisibleAccount {
            caller_account_id: caller.map(ToString::to_string),
        }
    }
}

fn torii_all_dataspace_routes(app: &AppState) -> Vec<RoutingDecision> {
    let state_view = app.state.view();
    let nexus = state_view.nexus();
    let mut routes =
        BTreeMap::<iroha_data_model::nexus::DataSpaceId, iroha_data_model::nexus::LaneId>::new();
    for lane in nexus.lane_catalog.lanes() {
        if !torii_lane_active_for_routing(app, nexus, lane.id) {
            continue;
        }
        routes
            .entry(lane.dataspace_id)
            .and_modify(|current| {
                if lane.id < *current {
                    *current = lane.id;
                }
            })
            .or_insert(lane.id);
    }
    routes
        .into_iter()
        .map(|(dataspace_id, lane_id)| RoutingDecision::new(lane_id, dataspace_id))
        .collect()
}

#[cfg(any(feature = "app_api", feature = "p2p_ws", feature = "connect"))]
fn torii_proxy_response_format(format: ResponseFormat) -> ToriiProxyResponseFormatV1 {
    match format {
        ResponseFormat::Norito => ToriiProxyResponseFormatV1::Norito,
        ResponseFormat::Json => ToriiProxyResponseFormatV1::Json,
    }
}

#[cfg(any(feature = "app_api", feature = "p2p_ws", feature = "connect"))]
fn response_format_from_torii_proxy(format: ToriiProxyResponseFormatV1) -> ResponseFormat {
    match format {
        ToriiProxyResponseFormatV1::Norito => ResponseFormat::Norito,
        ToriiProxyResponseFormatV1::Json => ResponseFormat::Json,
    }
}

fn current_torii_queue_pressure(app: &AppState) -> queue::QueuePressureSnapshot {
    let block_time = app.state.sumeragi_block_cadence();
    app.queue
        .refresh_pressure_budget_from_block_time(block_time)
}

fn current_torii_backpressure(app: &AppState) -> queue::BackpressureState {
    current_torii_queue_pressure(app).into_backpressure()
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn new_torii_proxy_session_id() -> Hash {
    let mut nonce = [0_u8; Hash::LENGTH];
    rand::rand_core::TryRngCore::try_fill_bytes(&mut rand::rngs::OsRng, &mut nonce)
        .unwrap_or_else(|error| panic!("Torii proxy process-session OS RNG failed: {error}"));
    Hash::new(nonce)
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn torii_proxy_request_id_for_session_sequence(
    process_session_id: &Hash,
    local_peer_id: &PeerId,
    sequence: u64,
    request: &ToriiProxyRequestKindV4,
) -> Hash {
    Hash::new(
        norito::to_bytes(&(
            "torii:proxy:v5",
            process_session_id.clone(),
            local_peer_id.clone(),
            sequence,
            request.clone(),
        ))
        .expect("Torii proxy request id encoding should be infallible"),
    )
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn next_torii_proxy_request_id(
    app: &AppState,
    local_peer_id: &PeerId,
    request: &ToriiProxyRequestKindV4,
) -> Result<Hash, &'static str> {
    let sequence = app
        .torii_proxy_sequence
        .fetch_update(
            std::sync::atomic::Ordering::Relaxed,
            std::sync::atomic::Ordering::Relaxed,
            |sequence| sequence.checked_add(1),
        )
        .map_err(|_| "Torii proxy request sequence is exhausted")?;
    Ok(torii_proxy_request_id_for_session_sequence(
        &app.torii_proxy_session_id,
        local_peer_id,
        sequence,
        request,
    ))
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn queue_plan_synced_proxy_request_id(
    app: &AppState,
    request: &ToriiProxyRequestKindV4,
) -> Option<Hash> {
    let ToriiProxyRequestKindV4::SubmitTransaction {
        transaction,
        admission: ToriiProxyTransactionAdmissionV2::QueuePlanSynced,
        ..
    } = request
    else {
        return None;
    };
    Some(queue_plan_synced_proxy_request_id_for_entrypoint(
        app,
        transaction.hash(),
    ))
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn queue_plan_synced_proxy_request_id_for_entrypoint(
    app: &AppState,
    entrypoint_hash: HashOf<TransactionEntrypoint>,
) -> Hash {
    iroha_core::torii_proxy::queue_plan_synced_request_id(app.chain_id.as_ref(), entrypoint_hash)
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn torii_proxy_hedge_delay(app: &AppState) -> Duration {
    app.state
        .sumeragi_block_cadence()
        .checked_div(2)
        .unwrap_or(Duration::ZERO)
        .clamp(Duration::from_millis(50), Duration::from_millis(250))
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn torii_proxy_candidate_launch_delay(
    queue_plan_synced: bool,
    hedge_delay: Duration,
    candidate_index: usize,
) -> Duration {
    if queue_plan_synced || candidate_index == 0 {
        return Duration::ZERO;
    }
    hedge_delay.saturating_mul(u32::try_from(candidate_index).unwrap_or(u32::MAX))
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
async fn prune_completed_torii_proxy_requests(app: &SharedAppState) {
    let now = Instant::now();
    let mut completed = app.torii_proxy_completed.lock().await;
    completed.prune(now);
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
async fn mark_torii_proxy_request_completed(app: &SharedAppState, request_id: Hash) {
    {
        let mut pending = app.torii_proxy_pending.lock().await;
        pending.retain(|(pending_request_id, _), _| *pending_request_id != request_id);
    }
    let mut completed = app.torii_proxy_completed.lock().await;
    completed.record(request_id, Instant::now());
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn new_torii_proxy_request(
    app: &AppState,
    request: ToriiProxyRequestKindV4,
) -> Result<ToriiProxyRequestV5, Response> {
    let Some(local_peer_id) = app.local_peer_id.as_ref() else {
        return Err(torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            "Torii ingress routing requires a configured local peer id",
        ));
    };

    let request_id = match queue_plan_synced_proxy_request_id(app, &request) {
        Some(request_id) => request_id,
        None => next_torii_proxy_request_id(app, local_peer_id, &request).map_err(|error| {
            torii_proxy_error_response(StatusCode::SERVICE_UNAVAILABLE, "route_unavailable", error)
        })?,
    };
    if let ToriiProxyRequestKindV4::SubmitTransaction {
        admission: ToriiProxyTransactionAdmissionV2::QueuePlanSynced,
        admission_binding: Some(binding),
        ..
    } = &request
        && binding.request_id != request_id
    {
        return Err(torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            "QueuePlanSynced binding request ID differs from its deterministic proxy identity",
        ));
    }
    Ok(ToriiProxyRequestV5 {
        schema_version: TORII_PROXY_REQUEST_VERSION_V5,
        request_id,
        hop_count: 1,
        max_hops: TORII_PROXY_DEFAULT_MAX_HOPS,
        visited_peer_ids: vec![local_peer_id.clone()],
        request,
    })
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn forwarded_torii_proxy_request(
    request: &ToriiProxyRequestV5,
    local_peer_id: &PeerId,
) -> ToriiProxyRequestV5 {
    let mut visited_peer_ids = request.visited_peer_ids.clone();
    if !visited_peer_ids
        .iter()
        .any(|peer_id| peer_id == local_peer_id)
    {
        visited_peer_ids.push(local_peer_id.clone());
    }

    ToriiProxyRequestV5 {
        schema_version: TORII_PROXY_REQUEST_VERSION_V5,
        request_id: request.request_id.clone(),
        hop_count: request.hop_count.saturating_add(1),
        max_hops: request.max_hops,
        visited_peer_ids,
        request: request.request.clone(),
    }
}

fn insert_routed_by_header(response: &mut Response, routed_by: &'static str) {
    response.headers_mut().insert(
        HeaderName::from_static("x-iroha-routed-by"),
        HeaderValue::from_static(routed_by),
    );
}

fn insert_usize_header(response: &mut Response, name: &'static str, value: usize) {
    if let Ok(header) = HeaderValue::from_str(&value.to_string()) {
        response
            .headers_mut()
            .insert(HeaderName::from_static(name), header);
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum SignedQueryScope {
    PublicControlPlane,
    LocalReplicated,
    AuthorityRouted,
    CrossDataspaceFanout,
    TargetAccount(AccountId),
    TargetAlias(iroha_data_model::account::AccountAlias),
    TargetDomain(iroha_data_model::domain::DomainId),
}

fn torii_signed_query_permission_denied_response(
    authority: &AccountId,
    denied_routes: usize,
) -> Response {
    torii_proxy_error_response(
        StatusCode::FORBIDDEN,
        "permission_denied",
        format!(
            "signed query authority {authority} cannot read {denied_routes} requested restricted dataspace route(s)"
        ),
    )
}

fn torii_intersect_signed_query_routes(
    routes: Vec<RoutingDecision>,
    allowed_routes: Vec<RoutingDecision>,
) -> (Vec<RoutingDecision>, usize) {
    let allowed_dataspaces = allowed_routes
        .into_iter()
        .map(|route| route.dataspace_id)
        .collect::<BTreeSet<_>>();
    let mut allowed = Vec::new();
    let mut denied = 0usize;
    for route in routes {
        if allowed_dataspaces.contains(&route.dataspace_id) {
            allowed.push(route);
        } else {
            denied = denied.saturating_add(1);
        }
    }
    (allowed, denied)
}

fn torii_authorize_signed_query_routes(
    app: &AppState,
    request: &impl SignedQueryScopeInput,
    scope: &SignedQueryScope,
    routes: Vec<RoutingDecision>,
) -> Result<Vec<RoutingDecision>, Response> {
    let authority = &request.request_with_authority().authority;
    match scope {
        SignedQueryScope::PublicControlPlane => Ok(Vec::new()),
        SignedQueryScope::LocalReplicated => Ok(routes),
        SignedQueryScope::CrossDataspaceFanout => {
            let (allowed, denied) = torii_intersect_signed_query_routes(
                routes,
                torii_global_signed_query_read_routes(app, authority),
            );
            if denied == 0 {
                Ok(allowed)
            } else {
                Err(torii_signed_query_permission_denied_response(
                    authority, denied,
                ))
            }
        }
        SignedQueryScope::AuthorityRouted => {
            let (allowed, denied) = torii_intersect_signed_query_routes(
                routes,
                torii_global_signed_query_read_routes(app, authority),
            );
            if denied == 0 {
                Ok(allowed)
            } else {
                Err(torii_signed_query_permission_denied_response(
                    authority, denied,
                ))
            }
        }
        SignedQueryScope::TargetAccount(target) => {
            let readable_routes = if torii_same_account_read_identity(app, authority, target) {
                torii_visible_account_read_routes(app, Some(authority))
            } else {
                torii_global_signed_query_read_routes(app, authority)
            };
            let (allowed, denied) = torii_intersect_signed_query_routes(routes, readable_routes);
            if denied == 0 {
                Ok(allowed)
            } else {
                Err(torii_signed_query_permission_denied_response(
                    authority, denied,
                ))
            }
        }
        SignedQueryScope::TargetAlias(alias) => {
            let state_view = app.state.view();
            if torii_authority_can_resolve_account_alias(state_view.world(), authority, alias) {
                Ok(routes)
            } else {
                Err(torii_signed_query_permission_denied_response(
                    authority,
                    routes.len().max(1),
                ))
            }
        }
        SignedQueryScope::TargetDomain(_) => {
            let (allowed, denied) = torii_intersect_signed_query_routes(
                routes,
                torii_global_signed_query_read_routes(app, authority),
            );
            if denied == 0 {
                Ok(allowed)
            } else {
                Err(torii_signed_query_permission_denied_response(
                    authority, denied,
                ))
            }
        }
    }
}

fn payload_matches_query<Query>(payload: &[u8]) -> bool
where
    Query: norito::codec::Decode + norito::codec::Encode,
{
    let mut cursor = payload;
    let Ok(query) = <Query as norito::codec::Decode>::decode(&mut cursor) else {
        return false;
    };
    cursor.is_empty() && norito::codec::Encode::encode(&query) == payload
}

fn is_trigger_inventory_query(query: &iroha_data_model::query::QueryWithParams) -> bool {
    use iroha_data_model::{
        query::{
            QueryItemKind, iter_query_inner,
            trigger::prelude::{FindActiveTriggerIds, FindTriggers},
        },
        trigger::{Trigger, TriggerId},
    };

    if let Some(query_box) = query.query_box() {
        if let Some(erased) = iter_query_inner::<Trigger>(query_box) {
            return payload_matches_query::<FindTriggers>(erased.payload());
        }
        if let Some(erased) = iter_query_inner::<TriggerId>(query_box) {
            return payload_matches_query::<FindActiveTriggerIds>(erased.payload());
        }
        return false;
    }

    query
        .fast_dsl_parts()
        .is_some_and(|(item_kind, _, _, payload)| match item_kind {
            QueryItemKind::Trigger => payload_matches_query::<FindTriggers>(payload),
            QueryItemKind::TriggerId => payload_matches_query::<FindActiveTriggerIds>(payload),
            _ => false,
        })
}

fn is_public_control_plane_query(query: &iroha_data_model::query::QueryWithParams) -> bool {
    use iroha_data_model::{
        peer::PeerId,
        query::{QueryItemKind, iter_query_inner, peer::prelude::FindPeers},
    };

    if let Some(query_box) = query.query_box() {
        return iter_query_inner::<PeerId>(query_box)
            .is_some_and(|erased| payload_matches_query::<FindPeers>(erased.payload()));
    }

    query
        .fast_dsl_parts()
        .is_some_and(|(item_kind, _, _, payload)| {
            item_kind == QueryItemKind::PeerId && payload_matches_query::<FindPeers>(payload)
        })
}

fn decode_query_payload<Query>(payload: &[u8]) -> Option<Query>
where
    Query: norito::codec::Decode + norito::codec::Encode,
{
    let mut cursor = payload;
    let query = <Query as norito::codec::Decode>::decode(&mut cursor).ok()?;
    (cursor.is_empty() && norito::codec::Encode::encode(&query) == payload).then_some(query)
}

fn target_scope_singular_query(
    query: &iroha_data_model::query::SingularQueryBox,
) -> Option<SignedQueryScope> {
    use iroha_data_model::query::SingularQueryBox;

    match query {
        SingularQueryBox::FindAssetById(query) => {
            Some(SignedQueryScope::TargetAccount(query.id.account().clone()))
        }
        SingularQueryBox::FindAssetDefinitionById(query) => {
            target_asset_definition_scope(&query.id)
        }
        SingularQueryBox::FindAccountById(query) => {
            Some(SignedQueryScope::TargetAccount(query.account_id().clone()))
        }
        SingularQueryBox::FindAliasesByAccountId(query) => {
            Some(SignedQueryScope::TargetAccount(query.account_id().clone()))
        }
        SingularQueryBox::FindAccountByAlias(query) => {
            Some(SignedQueryScope::TargetAlias(query.alias().clone()))
        }
        SingularQueryBox::FindAccountRecoveryPolicyByAlias(query) => {
            Some(SignedQueryScope::TargetAlias(query.alias().clone()))
        }
        SingularQueryBox::FindAccountRecoveryRequestByAlias(query) => {
            Some(SignedQueryScope::TargetAlias(query.alias().clone()))
        }
        SingularQueryBox::FindDomainById(query) => {
            Some(SignedQueryScope::TargetDomain(query.domain_id().clone()))
        }
        SingularQueryBox::FindNftById(query) => Some(SignedQueryScope::TargetDomain(
            query.nft_id().domain().clone(),
        )),
        _ => None,
    }
}

fn target_asset_definition_scope(
    _asset_definition_id: &iroha_data_model::asset::AssetDefinitionId,
) -> Option<SignedQueryScope> {
    None
}

fn resolve_asset_definition_scope(
    app: &AppState,
    asset_definition_id: &iroha_data_model::asset::AssetDefinitionId,
) -> Option<SignedQueryScope> {
    app.state
        .world_view()
        .asset_definition_domains()
        .get(asset_definition_id)
        .cloned()
        .map(SignedQueryScope::TargetDomain)
}

#[cfg(feature = "app_api")]
fn asset_definition_domain_snapshot(
    app: &AppState,
) -> BTreeMap<iroha_data_model::asset::AssetDefinitionId, iroha_data_model::domain::DomainId> {
    app.state
        .world_view()
        .asset_definition_domains()
        .iter()
        .map(|(definition_id, domain_id)| (definition_id.clone(), domain_id.clone()))
        .collect()
}

fn target_account_iterable_query(
    query: &iroha_data_model::query::QueryWithParams,
) -> Option<AccountId> {
    use iroha_data_model::{
        prelude::{
            FindAssetsByAccountId, FindDomainsByAccountId, FindNftsByAccountId,
            FindPermissionsByAccountId, FindRolesByAccountId,
        },
        query::{QueryItemKind, iter_query_inner},
        role::RoleId,
    };

    if let Some(query_box) = query.query_box() {
        if let Some(erased) = iter_query_inner::<iroha_data_model::domain::Domain>(query_box)
            && let Some(query) = decode_query_payload::<FindDomainsByAccountId>(erased.payload())
        {
            return Some(query.account_id().clone());
        }
        if let Some(erased) = iter_query_inner::<iroha_data_model::asset::value::Asset>(query_box)
            && let Some(query) = decode_query_payload::<FindAssetsByAccountId>(erased.payload())
        {
            return Some(query.account_id().clone());
        }
        if let Some(erased) = iter_query_inner::<iroha_data_model::nft::Nft>(query_box)
            && let Some(query) = decode_query_payload::<FindNftsByAccountId>(erased.payload())
        {
            return Some(query.account_id().clone());
        }
        if let Some(erased) = iter_query_inner::<Permission>(query_box)
            && let Some(query) =
                decode_query_payload::<FindPermissionsByAccountId>(erased.payload())
        {
            return Some(query.account_id().clone());
        }
        if let Some(erased) = iter_query_inner::<RoleId>(query_box)
            && let Some(query) = decode_query_payload::<FindRolesByAccountId>(erased.payload())
        {
            return Some(query.account_id().clone());
        }
        return None;
    }

    query
        .fast_dsl_parts()
        .and_then(|(item_kind, _, _, payload)| match item_kind {
            QueryItemKind::Domain => decode_query_payload::<FindDomainsByAccountId>(payload)
                .map(|query| query.account_id().clone()),
            QueryItemKind::Asset => decode_query_payload::<FindAssetsByAccountId>(payload)
                .map(|query| query.account_id().clone()),
            QueryItemKind::Nft => decode_query_payload::<FindNftsByAccountId>(payload)
                .map(|query| query.account_id().clone()),
            QueryItemKind::Permission => {
                decode_query_payload::<FindPermissionsByAccountId>(payload)
                    .map(|query| query.account_id().clone())
            }
            QueryItemKind::RoleId => decode_query_payload::<FindRolesByAccountId>(payload)
                .map(|query| query.account_id().clone()),
            _ => None,
        })
}

fn target_domain_iterable_query(
    _query: &iroha_data_model::query::QueryWithParams,
) -> Option<iroha_data_model::domain::DomainId> {
    None
}

fn target_scope_singular_query_for_app(
    app: &AppState,
    query: &iroha_data_model::query::SingularQueryBox,
) -> Option<SignedQueryScope> {
    use iroha_data_model::query::SingularQueryBox;

    match query {
        SingularQueryBox::FindAssetById(query) => {
            Some(SignedQueryScope::TargetAccount(query.id.account().clone()))
        }
        SingularQueryBox::FindAssetDefinitionById(query) => {
            resolve_asset_definition_scope(app, &query.id)
        }
        _ => target_scope_singular_query(query),
    }
}

fn target_domain_iterable_query_for_app(
    app: &AppState,
    query: &iroha_data_model::query::QueryWithParams,
) -> Option<iroha_data_model::domain::DomainId> {
    use iroha_data_model::{
        account::Account, prelude::FindAccountsWithAsset, query::iter_query_inner,
    };

    if let Some(query_box) = query.query_box() {
        if let Some(erased) = iter_query_inner::<Account>(query_box)
            && let Some(query) = decode_query_payload::<FindAccountsWithAsset>(erased.payload())
        {
            return resolve_asset_definition_scope(app, query.asset_definition_id()).and_then(
                |scope| match scope {
                    SignedQueryScope::TargetDomain(domain_id) => Some(domain_id),
                    _ => None,
                },
            );
        }
        return None;
    }

    query
        .fast_dsl_parts()
        .and_then(|(item_kind, _, _, payload)| {
            (item_kind == iroha_data_model::query::QueryItemKind::Account)
                .then(|| decode_query_payload::<FindAccountsWithAsset>(payload))
                .flatten()
                .and_then(|query| {
                    resolve_asset_definition_scope(app, query.asset_definition_id()).and_then(
                        |scope| {
                            let SignedQueryScope::TargetDomain(domain_id) = scope else {
                                return None;
                            };
                            Some(domain_id)
                        },
                    )
                })
        })
}

fn is_authority_routed_iterable_query(query: &iroha_data_model::query::QueryWithParams) -> bool {
    use iroha_data_model::query::{
        QueryItemKind, iter_query_inner, transaction::prelude::FindTransactions,
    };

    if let Some(query_box) = query.query_box() {
        if let Some(erased) =
            iter_query_inner::<iroha_data_model::query::CommittedTransaction>(query_box)
        {
            return payload_matches_query::<FindTransactions>(erased.payload());
        }
        return false;
    }

    query
        .fast_dsl_parts()
        .is_some_and(|(item_kind, _, _, payload)| match item_kind {
            QueryItemKind::CommittedTransaction => {
                payload_matches_query::<FindTransactions>(payload)
            }
            _ => false,
        })
}

trait SignedQueryScopeInput {
    fn request_with_authority(&self) -> &iroha_data_model::query::QueryRequestWithAuthority;
}

impl SignedQueryScopeInput for iroha_data_model::query::QueryRequestWithAuthority {
    fn request_with_authority(&self) -> &iroha_data_model::query::QueryRequestWithAuthority {
        self
    }
}

impl SignedQueryScopeInput for iroha_data_model::query::SignedQuery {
    fn request_with_authority(&self) -> &iroha_data_model::query::QueryRequestWithAuthority {
        &self.payload
    }
}

fn signed_query_scope(request: &impl SignedQueryScopeInput) -> SignedQueryScope {
    match request.request_with_authority().request() {
        iroha_data_model::query::QueryRequest::Continue(_) => SignedQueryScope::AuthorityRouted,
        iroha_data_model::query::QueryRequest::Singular(query) => {
            target_scope_singular_query(query).unwrap_or(SignedQueryScope::CrossDataspaceFanout)
        }
        iroha_data_model::query::QueryRequest::Start(query)
            if is_public_control_plane_query(query) =>
        {
            SignedQueryScope::PublicControlPlane
        }
        iroha_data_model::query::QueryRequest::Start(query)
            if is_trigger_inventory_query(query) =>
        {
            SignedQueryScope::LocalReplicated
        }
        iroha_data_model::query::QueryRequest::Start(query) => target_domain_iterable_query(query)
            .map(SignedQueryScope::TargetDomain)
            .or_else(|| target_account_iterable_query(query).map(SignedQueryScope::TargetAccount))
            .unwrap_or_else(|| {
                if is_authority_routed_iterable_query(query) {
                    SignedQueryScope::AuthorityRouted
                } else {
                    SignedQueryScope::CrossDataspaceFanout
                }
            }),
    }
}

fn signed_query_scope_for_app(
    app: &AppState,
    request: &impl SignedQueryScopeInput,
) -> SignedQueryScope {
    match request.request_with_authority().request() {
        iroha_data_model::query::QueryRequest::Continue(_) => SignedQueryScope::AuthorityRouted,
        iroha_data_model::query::QueryRequest::Singular(query) => {
            target_scope_singular_query_for_app(app, query)
                .unwrap_or(SignedQueryScope::CrossDataspaceFanout)
        }
        iroha_data_model::query::QueryRequest::Start(query)
            if is_public_control_plane_query(query) =>
        {
            SignedQueryScope::PublicControlPlane
        }
        iroha_data_model::query::QueryRequest::Start(query)
            if is_trigger_inventory_query(query) =>
        {
            SignedQueryScope::LocalReplicated
        }
        iroha_data_model::query::QueryRequest::Start(query) => {
            target_domain_iterable_query_for_app(app, query)
                .map(SignedQueryScope::TargetDomain)
                .or_else(|| {
                    target_account_iterable_query(query).map(SignedQueryScope::TargetAccount)
                })
                .unwrap_or_else(|| {
                    if is_authority_routed_iterable_query(query) {
                        SignedQueryScope::AuthorityRouted
                    } else {
                        SignedQueryScope::CrossDataspaceFanout
                    }
                })
        }
    }
}

fn torii_authorized_signed_query_routes(
    app: &AppState,
    request: &impl SignedQueryScopeInput,
    scope: &SignedQueryScope,
) -> Result<Vec<RoutingDecision>, Response> {
    if matches!(scope, SignedQueryScope::PublicControlPlane) {
        return Ok(Vec::new());
    }
    if matches!(scope, SignedQueryScope::LocalReplicated) {
        torii_authorize_signed_query_routes(
            app,
            request,
            &SignedQueryScope::AuthorityRouted,
            torii_all_dataspace_routes(app),
        )?;
        return Ok(Vec::new());
    }
    if matches!(scope, SignedQueryScope::AuthorityRouted) {
        torii_authorize_signed_query_routes(app, request, scope, torii_all_dataspace_routes(app))?;
        let authority = &request.request_with_authority().authority;
        return Ok(vec![
            resolve_signed_query_authority_routing(app, authority).map_err(|error| {
                torii_proxy_error_response(
                    StatusCode::SERVICE_UNAVAILABLE,
                    "route_unavailable",
                    format!("failed to resolve signed-query authority route: {error}"),
                )
            })?,
        ]);
    }

    let routes = match scope {
        SignedQueryScope::PublicControlPlane => Vec::new(),
        SignedQueryScope::LocalReplicated => Vec::new(),
        SignedQueryScope::AuthorityRouted => unreachable!("handled above"),
        SignedQueryScope::CrossDataspaceFanout => torii_all_dataspace_routes(app),
        SignedQueryScope::TargetAccount(account_id) => {
            torii_target_account_routes(app, account_id)?
        }
        SignedQueryScope::TargetAlias(alias) => torii_target_alias_routes(app, alias)?,
        SignedQueryScope::TargetDomain(domain_id) => torii_target_domain_routes(app, domain_id)?,
    };
    torii_authorize_signed_query_routes(app, request, scope, routes)
}

fn clone_verified_query_request(
    request: &iroha_data_model::query::QueryRequestWithAuthority,
) -> iroha_data_model::query::QueryRequestWithAuthority {
    let bytes = norito::to_bytes(request)
        .expect("verified routed query requests should encode deterministically");
    norito::decode_from_bytes(&bytes)
        .expect("verified routed query requests should decode deterministically")
}

fn fanout_route_scan_query_request(
    request: &iroha_data_model::query::QueryRequestWithAuthority,
) -> iroha_data_model::query::QueryRequestWithAuthority {
    let mut request = clone_verified_query_request(request);
    if let iroha_data_model::query::QueryRequest::Start(start) = &mut request.request {
        let signed_pagination = start.params.pagination.clone();
        let scan_limit = signed_pagination.limit.map(|limit| {
            std::num::NonZeroU64::new(signed_pagination.offset.saturating_add(limit.get()))
                .expect("a non-zero signed limit produces a non-zero route-scan bound")
        });
        start.params.pagination =
            iroha_data_model::query::parameters::Pagination::new(scan_limit, 0);
        let fetch_size_cap = crate::routing::app_query_limits().max_fetch_size.max(1);
        let fetch_size = scan_limit
            .map(|limit| limit.get().min(fetch_size_cap))
            .unwrap_or(fetch_size_cap);
        start.params.fetch_size = iroha_data_model::query::parameters::FetchSize::new(
            std::num::NonZeroU64::new(fetch_size),
        );
    }
    request
}

fn unsupported_routed_query_response(message: impl Into<String>) -> Response {
    torii_proxy_error_response(StatusCode::CONFLICT, "query_unsupported", message)
}

fn should_skip_iterable_routed_query_route_error(response: &Response) -> bool {
    response.status() == StatusCode::NOT_FOUND
        || torii_response_has_reject_code(response, "route_unavailable")
}

fn torii_response_has_reject_code(response: &Response, code: &str) -> bool {
    response
        .headers()
        .get("x-iroha-reject-code")
        .and_then(|value| value.to_str().ok())
        == Some(code)
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct ToriiFanoutDiagnostics {
    attempted_routes: usize,
    succeeded_routes: usize,
    denied_routes: usize,
    not_found_routes: usize,
    unavailable_routes: usize,
    first_failure_class: Option<&'static str>,
}

impl ToriiFanoutDiagnostics {
    fn record_attempt(&mut self) {
        self.attempted_routes = self.attempted_routes.saturating_add(1);
    }

    fn record_success(&mut self) {
        self.succeeded_routes = self.succeeded_routes.saturating_add(1);
    }

    fn record_denied(&mut self) {
        self.attempted_routes = self.attempted_routes.saturating_add(1);
        self.denied_routes = self.denied_routes.saturating_add(1);
        self.record_failure_class("permission_denied");
    }

    fn record_failure_class(&mut self, class: &'static str) {
        if self.first_failure_class.is_none() {
            self.first_failure_class = Some(class);
        }
    }

    fn record_skipped_response(&mut self, response: &Response) {
        if torii_response_has_reject_code(response, "route_unavailable") {
            self.unavailable_routes = self.unavailable_routes.saturating_add(1);
            self.record_failure_class("route_unavailable");
        } else if response.status() == StatusCode::NOT_FOUND {
            self.not_found_routes = self.not_found_routes.saturating_add(1);
            self.record_failure_class("not_found");
        } else {
            self.record_failure_class("error");
        }
    }

    fn failed_routes(self) -> usize {
        self.attempted_routes.saturating_sub(self.succeeded_routes)
    }
}

#[cfg(feature = "app_api")]
#[derive(Debug)]
struct ToriiFanoutJsonPayloads {
    payloads: Vec<Value>,
    diagnostics: ToriiFanoutDiagnostics,
}

#[cfg(feature = "app_api")]
#[derive(Debug)]
struct ToriiFanoutRoutedJsonPayloads {
    payloads: Vec<(RoutingDecision, Value)>,
    diagnostics: ToriiFanoutDiagnostics,
}

fn torii_alias_routes_denied_warning_header() -> HeaderValue {
    HeaderValue::from_static(r#"199 - "one or more alias routes were denied""#)
}

fn insert_torii_fanout_headers(response: &mut Response, diagnostics: ToriiFanoutDiagnostics) {
    insert_usize_header(
        response,
        "x-iroha-fanout-routes-attempted",
        diagnostics.attempted_routes,
    );
    insert_usize_header(
        response,
        "x-iroha-fanout-routes-succeeded",
        diagnostics.succeeded_routes,
    );
    insert_usize_header(
        response,
        "x-iroha-fanout-routes-failed",
        diagnostics.failed_routes(),
    );
    insert_usize_header(
        response,
        "x-iroha-fanout-routes-denied",
        diagnostics.denied_routes,
    );
    insert_usize_header(
        response,
        "x-iroha-fanout-routes-unavailable",
        diagnostics.unavailable_routes,
    );
    insert_usize_header(
        response,
        "x-iroha-fanout-routes-not-found",
        diagnostics.not_found_routes,
    );
    if let Some(class) = diagnostics.first_failure_class {
        response.headers_mut().insert(
            HeaderName::from_static("x-iroha-fanout-first-failure"),
            HeaderValue::from_static(class),
        );
    }
}

fn with_torii_fanout_headers(
    mut response: Response,
    diagnostics: ToriiFanoutDiagnostics,
) -> Response {
    if diagnostics.denied_routes > 0 && response.status().is_success() {
        response.headers_mut().append(
            axum::http::header::WARNING,
            torii_alias_routes_denied_warning_header(),
        );
    }
    insert_torii_fanout_headers(&mut response, diagnostics);
    response
}

fn should_skip_singleton_routed_query_route_error(response: &Response) -> bool {
    response.status() == StatusCode::NOT_FOUND
        || torii_response_has_reject_code(response, "route_unavailable")
}

fn collect_routed_singular_query_outputs<T>(
    results: impl IntoIterator<Item = Result<T, Response>>,
) -> Result<Vec<T>, Response> {
    let mut outputs = Vec::new();
    let mut last_not_found = None;
    let mut last_route_unavailable = None;

    for result in results {
        match result {
            Ok(output) => outputs.push(output),
            Err(response) if should_skip_singleton_routed_query_route_error(&response) => {
                if torii_response_has_reject_code(&response, "route_unavailable") {
                    last_route_unavailable = Some(response);
                } else {
                    last_not_found = Some(response);
                }
            }
            Err(response) => return Err(response),
        }
    }

    if outputs.is_empty() {
        return Err(last_not_found.unwrap_or_else(|| {
            last_route_unavailable.unwrap_or_else(|| {
                torii_proxy_error_response(
                    StatusCode::NOT_FOUND,
                    "not_found",
                    "query result was not found in any dataspace",
                )
            })
        }));
    }

    Ok(outputs)
}

#[cfg(feature = "app_api")]
async fn collect_torii_singleton_json_payloads<F, Fut>(
    routes: &[RoutingDecision],
    mut fetch: F,
) -> Result<ToriiFanoutJsonPayloads, Response>
where
    F: FnMut(RoutingDecision) -> Fut,
    Fut: std::future::Future<Output = Response>,
{
    let mut payloads = Vec::with_capacity(routes.len());
    let mut diagnostics = ToriiFanoutDiagnostics::default();
    let mut last_not_found = None;
    let mut last_route_unavailable = None;

    for _ in routes {
        diagnostics.record_attempt();
    }
    let responses = futures_util::future::join_all(routes.iter().map(|route| fetch(*route))).await;

    for response in responses {
        if response.status() == StatusCode::NOT_FOUND {
            diagnostics.record_skipped_response(&response);
            last_not_found = Some(response);
            continue;
        }
        if torii_response_has_reject_code(&response, "route_unavailable") {
            diagnostics.record_skipped_response(&response);
            last_route_unavailable = Some(response);
            continue;
        }
        match torii_json_body_value(response).await {
            Ok(payload) => {
                diagnostics.record_success();
                payloads.push(payload);
            }
            Err(response) => {
                diagnostics.record_skipped_response(&response);
                return Err(with_torii_fanout_headers(response, diagnostics));
            }
        }
    }

    if payloads.is_empty() {
        let response = last_not_found.unwrap_or_else(|| {
            last_route_unavailable.unwrap_or_else(|| {
                torii_proxy_error_response(
                    StatusCode::NOT_FOUND,
                    "not_found",
                    "no dataspace returned a matching result",
                )
            })
        });
        return Err(with_torii_fanout_headers(response, diagnostics));
    }

    Ok(ToriiFanoutJsonPayloads {
        payloads,
        diagnostics,
    })
}

