#[cfg(feature = "app_api")]
async fn execute_torii_single_route_read_with_format(
    app: &SharedAppState,
    route: RoutingDecision,
    endpoint: ToriiReadEndpointV1,
    path_args: Vec<String>,
    query_string: Option<String>,
    body: Vec<u8>,
    response_format: ToriiProxyResponseFormatV1,
) -> Response {
    let request_body = body.clone();
    let mut request = torii_read_request(endpoint, route, path_args, query_string, body);
    request.response_format = response_format;
    let response = execute_torii_read_for_route(app, route, request).await;
    sanitize_exact_alias_route_response(app, route, endpoint, &request_body, response).await
}

#[cfg(feature = "app_api")]
async fn sanitize_exact_alias_route_response(
    app: &SharedAppState,
    route: RoutingDecision,
    endpoint: ToriiReadEndpointV1,
    request_body: &[u8],
    response: Response,
) -> Response {
    if !response.status().is_success()
        || !matches!(
            endpoint,
            ToriiReadEndpointV1::AliasResolve
                | ToriiReadEndpointV1::AliasResolveIndex
                | ToriiReadEndpointV1::ContractAliasResolve
                | ToriiReadEndpointV1::ContractDeploymentState
        )
    {
        return response;
    }

    let (mut parts, body) = response.into_parts();
    let body = match axum::body::to_bytes(body, EXACT_ALIAS_READ_MAX_BODY_BYTES).await {
        Ok(body) => body,
        Err(error) => {
            let mut response = torii_proxy_error_response(
                StatusCode::BAD_GATEWAY,
                "invalid_proxy_response",
                format!("routed alias response is invalid or too large: {error}"),
            );
            insert_routing_headers(&mut response, route, "validated");
            return response;
        }
    };

    let invalid = |message: String| {
        let mut response =
            torii_proxy_error_response(StatusCode::BAD_GATEWAY, "invalid_proxy_response", message);
        insert_routing_headers(&mut response, route, "validated");
        response
    };

    let sanitized = match endpoint {
        ToriiReadEndpointV1::AliasResolve => {
            let request: routing::AliasResolveRequestDto =
                match norito::json::from_slice(request_body) {
                    Ok(request) => request,
                    Err(error) => {
                        return invalid(format!("invalid routed alias request: {error}"));
                    }
                };
            let dto: routing::AliasResolveResponseDto = match norito::json::from_slice(&body) {
                Ok(dto) => dto,
                Err(error) => {
                    return invalid(format!("invalid routed alias response schema: {error}"));
                }
            };
            let expected = match resolve_alias_on_route(app, route, &request.alias) {
                Ok(Some(expected)) => expected,
                Ok(None) => {
                    return invalid(
                        "routed alias response has no matching strictly active local binding"
                            .to_owned(),
                    );
                }
                Err(error) => return invalid(format!("failed to verify routed alias: {error}")),
            };
            let (canonical_account, canonical_account_literal) =
                match parse_exact_account_id_literal(&dto.account_id) {
                    Ok(parsed) => parsed,
                    Err(error) => {
                        return invalid(format!(
                            "routed alias response contains a non-canonical account id: {error}"
                        ));
                    }
                };
            if dto.alias != expected.0
                || canonical_account != expected.1
                || canonical_account_literal != dto.account_id
                || dto.index.is_some()
                || dto.source.as_deref() != Some("active_sns")
            {
                return invalid(
                    "routed alias response disagrees with the authoritative active binding"
                        .to_owned(),
                );
            }
            norito::json::to_vec(&routing::AliasResolveResponseDto {
                alias: expected.0,
                account_id: expected.1.to_string(),
                index: None,
                source: Some("active_sns".to_owned()),
            })
        }
        ToriiReadEndpointV1::AliasResolveIndex => {
            let request: routing::AliasResolveIndexRequestDto =
                match norito::json::from_slice(request_body) {
                    Ok(request) => request,
                    Err(error) => {
                        return invalid(format!("invalid routed alias-index request: {error}"));
                    }
                };
            let dto: routing::AliasResolveIndexResponseDto = match norito::json::from_slice(&body) {
                Ok(dto) => dto,
                Err(error) => {
                    return invalid(format!(
                        "invalid routed alias-index response schema: {error}"
                    ));
                }
            };
            let expected = match resolve_alias_index_on_route(app, route, request.index) {
                Ok(Some(expected)) => expected,
                Ok(None) => {
                    return invalid(
                        "routed alias-index response has no matching strictly active local binding"
                            .to_owned(),
                    );
                }
                Err(error) => {
                    return invalid(format!("failed to verify routed alias index: {error}"));
                }
            };
            let (canonical_account, canonical_account_literal) =
                match parse_exact_account_id_literal(&dto.account_id) {
                    Ok(parsed) => parsed,
                    Err(error) => {
                        return invalid(format!(
                            "routed alias-index response contains a non-canonical account id: {error}"
                        ));
                    }
                };
            if dto.index != request.index
                || dto.alias != expected.0
                || canonical_account != expected.1
                || canonical_account_literal != dto.account_id
                || dto.source.as_deref() != Some("active_sns")
            {
                return invalid(
                    "routed alias-index response disagrees with the authoritative active binding"
                        .to_owned(),
                );
            }
            norito::json::to_vec(&routing::AliasResolveIndexResponseDto {
                index: request.index,
                alias: expected.0,
                account_id: expected.1.to_string(),
                source: Some("active_sns".to_owned()),
            })
        }
        ToriiReadEndpointV1::ContractAliasResolve => {
            let request: routing::ContractAliasResolveRequestDto =
                match norito::json::from_slice(request_body) {
                    Ok(request) => request,
                    Err(error) => {
                        return invalid(format!("invalid routed contract alias request: {error}"));
                    }
                };
            let dto: routing::ContractAliasResolveResponseDto =
                match norito::json::from_slice(&body) {
                    Ok(dto) => dto,
                    Err(error) => {
                        return invalid(format!(
                            "invalid routed contract alias response schema: {error}"
                        ));
                    }
                };
            let (contract_alias, contract_address, contract_subject, binding, dataspace) =
                match resolve_contract_alias_on_chain(app, &request.contract_alias) {
                    Ok(Some(expected)) => expected,
                    Ok(None) => {
                        return invalid(
                            "routed contract alias response has no matching active local binding"
                                .to_owned(),
                        );
                    }
                    Err(error) => {
                        return invalid(format!("failed to verify routed contract alias: {error}"));
                    }
                };
            let now_ms = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis() as u64;
            let expected_binding = routing::contract_alias_binding_dto(&binding, now_ms);
            if dto.contract_alias != contract_alias.as_ref()
                || dto.contract_address != contract_address.as_ref()
                || dto.contract_subject_account != contract_subject.to_string()
                || dto.dataspace != dataspace
                || dto.source != "world_state"
                || dto.contract_alias_binding.alias != expected_binding.alias
                || dto.contract_alias_binding.status != expected_binding.status
                || dto.contract_alias_binding.lease_expiry_ms != expected_binding.lease_expiry_ms
                || dto.contract_alias_binding.grace_until_ms != expected_binding.grace_until_ms
                || dto.contract_alias_binding.bound_at_ms != expected_binding.bound_at_ms
            {
                return invalid(
                    "routed contract alias response disagrees with the authoritative active binding"
                        .to_owned(),
                );
            }
            norito::json::to_vec(&routing::ContractAliasResolveResponseDto {
                contract_alias: contract_alias.to_string(),
                contract_address: contract_address.to_string(),
                contract_subject_account: contract_subject.to_string(),
                dataspace,
                contract_alias_binding: expected_binding,
                source: "world_state".to_owned(),
            })
        }
        ToriiReadEndpointV1::ContractDeploymentState => {
            deployment_state::sanitize_routed_contract_deployment_state(route, request_body, &body)
                .map_err(norito::json::Error::Message)
        }
        _ => unreachable!("non-sanitized endpoints returned before body collection"),
    };

    let sanitized = match sanitized {
        Ok(sanitized) => sanitized,
        Err(error) => {
            return invalid(format!(
                "failed to encode sanitized alias response: {error}"
            ));
        }
    };
    parts.headers.remove(axum::http::header::CONTENT_LENGTH);
    parts.headers.insert(
        axum::http::header::CONTENT_TYPE,
        HeaderValue::from_static("application/json"),
    );
    Response::from_parts(parts, Body::from(sanitized))
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
async fn forward_incoming_torii_proxy_request_from_sender(
    app: &SharedAppState,
    immediate_sender_peer_id: Option<&PeerId>,
    routing_decision: RoutingDecision,
    request: &ToriiProxyRequestV5,
) -> Response {
    let Some(sender_peer_id) = immediate_sender_peer_id else {
        return torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            "Torii proxy request is missing an upstream sender peer id for re-forwarding",
        );
    };
    forward_incoming_torii_proxy_request(app, sender_peer_id, routing_decision, request).await
}

#[cfg(all(not(feature = "app_api"), any(feature = "p2p_ws", feature = "connect")))]
fn app_api_required_torii_proxy_response(action: &'static str) -> Response {
    torii_proxy_error_response(
        StatusCode::SERVICE_UNAVAILABLE,
        "route_unavailable",
        format!("{action} requires the `app_api` feature"),
    )
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
async fn execute_incoming_torii_proxy_request(
    app: &SharedAppState,
    proxy_request: ToriiProxyRequestV5,
    immediate_sender_peer_id: Option<PeerId>,
) -> Response {
    if proxy_request.schema_version != TORII_PROXY_REQUEST_VERSION_V5 {
        return torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            format!(
                "unsupported Torii proxy request schema_version `{}`",
                proxy_request.schema_version
            ),
        );
    }
    let hop_count = usize::from(proxy_request.hop_count);
    if proxy_request.hop_count == 0
        || proxy_request.max_hops == 0
        || proxy_request.max_hops > TORII_PROXY_DEFAULT_MAX_HOPS
        || proxy_request.hop_count > proxy_request.max_hops
        || proxy_request.visited_peer_ids.len() != hop_count
    {
        return torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            format!(
                "invalid Torii proxy hop_count `{}` / max_hops `{}` / visited peer count `{}`",
                proxy_request.hop_count,
                proxy_request.max_hops,
                proxy_request.visited_peer_ids.len()
            ),
        );
    }
    if proxy_request
        .visited_peer_ids
        .iter()
        .collect::<BTreeSet<_>>()
        .len()
        != proxy_request.visited_peer_ids.len()
    {
        return torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            "Torii proxy hop history contains duplicate peers",
        );
    }
    if let Some(immediate_sender_peer_id) = immediate_sender_peer_id.as_ref()
        && proxy_request.visited_peer_ids.last() != Some(immediate_sender_peer_id)
    {
        return torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            "Torii proxy hop history is not bound to the authenticated immediate sender",
        );
    }
    if let Some(local_peer_id) = app.local_peer_id.as_ref()
        && proxy_request
            .visited_peer_ids
            .iter()
            .any(|visited_peer_id| visited_peer_id == local_peer_id)
        && !(proxy_request.hop_count == 1
            && proxy_request.visited_peer_ids.len() == 1
            && proxy_request.visited_peer_ids.first() == Some(local_peer_id)
            && immediate_sender_peer_id.as_ref() == Some(local_peer_id))
    {
        return torii_proxy_error_response(
            StatusCode::BAD_REQUEST,
            "invalid_proxy_request",
            "Torii proxy request attempted to revisit the receiving peer",
        );
    }

    let proxy_request_context = proxy_request.clone();
    match proxy_request.request.clone() {
        ToriiProxyRequestKindV4::SubmitTransaction {
            transaction,
            expected_plan,
            admission: ToriiProxyTransactionAdmissionV2::QueuePlanSynced,
            admission_binding,
        } => {
            let ingress_plan = match validate_proxy_routing_plan_hint(expected_plan) {
                Ok(plan) => plan,
                Err(error) => {
                    return torii_proxy_error_response(
                        StatusCode::BAD_REQUEST,
                        "invalid_proxy_request",
                        format!("invalid routing plan hint: {error}"),
                    );
                }
            };
            match routing::accept_transaction_for_ingress(
                app.chain_id.clone(),
                app.state.clone(),
                transaction,
                &app.telemetry,
            ) {
                Ok(accepted_tx) => match app
                    .queue
                    .route_plan_with_state(&accepted_tx, app.state.as_ref())
                {
                    Ok(routing_plan) => match validate_proxy_routing_plan(
                        "submit_transaction",
                        routing_plan,
                        ingress_plan,
                    ) {
                        Ok(routing_plan) => {
                            let routing_decision = routing_plan.coordinator_route();
                            let (expected_admission_binding, execute_locally) = {
                                let Some(admission_binding) = admission_binding else {
                                    return torii_proxy_error_response(
                                        StatusCode::BAD_REQUEST,
                                        "invalid_proxy_request",
                                        "QueuePlanSynced proxy admission requires an exact admission binding",
                                    );
                                };
                                if admission_binding.request_id != proxy_request_context.request_id
                                {
                                    return torii_proxy_error_response(
                                        StatusCode::BAD_REQUEST,
                                        "invalid_proxy_request",
                                        "QueuePlanSynced binding request ID differs from its proxy envelope",
                                    );
                                }
                                let canonical_request_id =
                                    queue_plan_synced_proxy_request_id_for_entrypoint(
                                        app.as_ref(),
                                        accepted_tx.entrypoint().hash(),
                                    );
                                if admission_binding.request_id != canonical_request_id {
                                    return torii_proxy_error_response(
                                        StatusCode::BAD_REQUEST,
                                        "invalid_proxy_request",
                                        "QueuePlanSynced request ID is not the deterministic chain/entrypoint identity",
                                    );
                                }
                                if let Err(error) = admission_binding.validate_for_request(
                                    app.chain_id.as_ref(),
                                    accepted_tx.entrypoint(),
                                    &routing_plan,
                                ) {
                                    return torii_proxy_error_response(
                                        StatusCode::BAD_REQUEST,
                                        "invalid_proxy_request",
                                        error,
                                    );
                                }
                                match app.queue.plan_admission_context_with_state(
                                    app.state.as_ref(),
                                    &routing_plan,
                                ) {
                                    Ok(current_context)
                                        if current_context
                                            == admission_binding.admission_context =>
                                    {
                                        let coordinator = admission_binding
                                            .admission_context
                                            .route_incarnations
                                            .first()
                                            .expect("validated binding has a coordinator");
                                        let execute_locally = app
                                            .local_peer_id
                                            .as_ref()
                                            .is_some_and(|local_peer_id| {
                                                coordinator.validator_set.contains(local_peer_id)
                                            });
                                        (Some(admission_binding), execute_locally)
                                    }
                                    Ok(_)
                                        if app
                                            .queue
                                            .has_revalidatable_durable_plan_claim_with_state(
                                                &accepted_tx,
                                                app.state.as_ref(),
                                                &routing_plan,
                                                &admission_binding.admission_context,
                                            ) =>
                                    {
                                        let coordinator = admission_binding
                                            .admission_context
                                            .route_incarnations
                                            .first()
                                            .expect("validated binding has a coordinator");
                                        let execute_locally = app
                                            .local_peer_id
                                            .as_ref()
                                            .is_some_and(|local_peer_id| {
                                                coordinator.validator_set.contains(local_peer_id)
                                            });
                                        (Some(admission_binding), execute_locally)
                                    }
                                    Ok(_) => {
                                        return torii_proxy_error_response(
                                            StatusCode::CONFLICT,
                                            "queue_plan_admission_context_mismatch",
                                            "QueuePlanSynced admission context no longer matches the active lane/authority generation and has no revalidatable local durable claim",
                                        );
                                    }
                                    Err(_)
                                        if app
                                            .queue
                                            .has_revalidatable_durable_plan_claim_with_state(
                                                &accepted_tx,
                                                app.state.as_ref(),
                                                &routing_plan,
                                                &admission_binding.admission_context,
                                            ) =>
                                    {
                                        let coordinator = admission_binding
                                            .admission_context
                                            .route_incarnations
                                            .first()
                                            .expect("validated binding has a coordinator");
                                        let execute_locally = app
                                            .local_peer_id
                                            .as_ref()
                                            .is_some_and(|local_peer_id| {
                                                coordinator.validator_set.contains(local_peer_id)
                                            });
                                        (Some(admission_binding), execute_locally)
                                    }
                                    Err(error) => {
                                        return torii_proxy_error_response(
                                            StatusCode::SERVICE_UNAVAILABLE,
                                            "route_unavailable",
                                            format!(
                                                "failed to revalidate QueuePlanSynced admission context: {error}"
                                            ),
                                        );
                                    }
                                }
                            };
                            if !execute_locally {
                                forward_incoming_torii_proxy_request_from_sender(
                                    app,
                                    immediate_sender_peer_id.as_ref(),
                                    routing_decision,
                                    &proxy_request_context,
                                )
                                .await
                            } else {
                                let push_result = {
                                    let receipt_signer = PeerId::new(
                                        app.torii_proxy_bridge_signer.public_key().clone(),
                                    );
                                    if app.local_peer_id.as_ref() != Some(&receipt_signer) {
                                        return torii_proxy_error_response(
                                            StatusCode::INTERNAL_SERVER_ERROR,
                                            "queue_plan_synced_signer_mismatch",
                                            format!(
                                                "configured local peer does not match the QueuePlanSynced receipt signer `{receipt_signer}`"
                                            ),
                                        );
                                    }
                                    routing::push_accepted_transaction_for_ingress_with_routing_plan_strict_durable_claim(
                                            app.queue.clone(),
                                            app.state.clone(),
                                            accepted_tx,
                                            routing_plan,
                                            expected_admission_binding.as_ref().expect(
                                                "strict proxy admission validated an exact binding",
                                            ),
                                        )
                                            .map(Some)
                                };
                                match push_result {
                                    Ok(durable_claim) => {
                                        let durable_claim = durable_claim.expect(
                                            "strict durable ingress result must contain a claim",
                                        );
                                        let expected_binding = expected_admission_binding
                                            .expect("strict admission retained its binding");
                                        let durable_binding =
                                            QueuePlanAdmissionBindingV2::try_from_durable_admission(
                                                &durable_claim,
                                            );
                                        if durable_binding.as_ref() != Ok(&expected_binding) {
                                            return queue_plan_outcome_unknown_response(
                                                durable_claim.entrypoint_hash.clone(),
                                                "exact QueuePlan binding changed across strict durable admission",
                                            );
                                        }
                                        queue_plan_synced_admission_response(
                                            app.as_ref(),
                                            routing_decision,
                                            expected_binding,
                                            durable_claim,
                                        )
                                    }
                                    Err(error) => error.into_response(),
                                }
                            }
                        }
                        Err(error) => torii_proxy_error_response(
                            StatusCode::CONFLICT,
                            "routing_plan_mismatch",
                            format!(
                                "routing plan mismatch: ingress digest {}, receiver digest {}",
                                error.ingress_digest, error.receiver_digest
                            ),
                        ),
                    },
                    Err(error) => routing_resolve_error_to_torii_error(app, error).into_response(),
                },
                Err(error) => error.into_response(),
            }
        }
        ToriiProxyRequestKindV4::SignedQuery {
            query_bytes,
            expected_route,
            response_format,
        } => match decode_verified_proxy_signed_query(&query_bytes, "proxied") {
            Ok(verified_query) => {
                let scope = signed_query_scope_for_app(app.as_ref(), &verified_query);
                match torii_authorized_signed_query_routes(app.as_ref(), &verified_query, &scope) {
                    Ok(routes) if routes.len() == 1 => {
                        let routing_decision = routes[0];
                        let routing_decision = effective_proxy_signed_query_routing_decision(
                            routing_decision,
                            expected_route.into(),
                        );
                        if !should_execute_incoming_torii_proxy_request_locally(
                            app,
                            &proxy_request_context.request,
                            routing_decision,
                        ) {
                            forward_incoming_torii_proxy_request_from_sender(
                                app,
                                immediate_sender_peer_id.as_ref(),
                                routing_decision,
                                &proxy_request_context,
                            )
                            .await
                        } else {
                            let format = response_format_from_torii_proxy(response_format);
                            match execute_torii_verified_query_locally(app, verified_query).await {
                                Ok(query_response) => {
                                    let mut response =
                                        crate::utils::respond_with_format(query_response, format);
                                    insert_routing_headers(
                                        &mut response,
                                        routing_decision,
                                        "proxy",
                                    );
                                    response
                                }
                                Err(error) => error.into_response(),
                            }
                        }
                    }
                    Ok(routes) => torii_proxy_error_response(
                        StatusCode::CONFLICT,
                        "query_unsupported",
                        format!(
                            "proxied signed query resolved to {} authorized routes; exactly one is required",
                            routes.len()
                        ),
                    ),
                    Err(response) => response,
                }
            }
            Err(response) => response,
        },
        ToriiProxyRequestKindV4::SignedQueryRouteScan {
            query_bytes,
            expected_route,
            response_format,
        } => match decode_verified_proxy_signed_query(&query_bytes, "proxied route-scan") {
            Ok(request) => {
                if let Err(response) =
                    reject_proxy_client_continuation(&request, "signed route scan")
                {
                    return response;
                }
                let routing_decision: RoutingDecision = expected_route.into();
                let scope = signed_query_scope_for_app(app.as_ref(), &request);
                let authorized_routes =
                    match torii_authorized_signed_query_routes(app.as_ref(), &request, &scope) {
                        Ok(routes) => routes,
                        Err(response) => return response,
                    };
                if let Err(response) = validate_proxy_signed_query_route(
                    &request.authority,
                    &authorized_routes,
                    routing_decision,
                ) {
                    return response;
                }
                let routing_decision = match validate_incoming_read_proxy_route(
                    app,
                    routing_decision,
                    "signed_query_route_scan",
                ) {
                    Ok(route) => route,
                    Err(response) => return response,
                };
                let route_request = fanout_route_scan_query_request(&request);
                let format = response_format_from_torii_proxy(response_format);
                match execute_torii_verified_query_exhaustive_locally(app, route_request).await {
                    Ok(query_response) => {
                        let mut response =
                            crate::utils::respond_with_format(query_response, format);
                        insert_routing_headers(&mut response, routing_decision, "proxy");
                        response
                    }
                    Err(response) => response,
                }
            }
            Err(response) => response,
        },
        ToriiProxyRequestKindV4::SignedQueryFanout {
            query_bytes,
            response_format,
        } => match torii_nexus_route(app.as_ref()) {
            Ok(nexus_route) => {
                if !should_execute_incoming_torii_proxy_request_locally(
                    app,
                    &proxy_request_context.request,
                    nexus_route,
                ) {
                    forward_incoming_torii_proxy_request_from_sender(
                        app,
                        immediate_sender_peer_id.as_ref(),
                        nexus_route,
                        &proxy_request_context,
                    )
                    .await
                } else {
                    execute_torii_signed_query_fanout_proxy_request(
                        app,
                        query_bytes,
                        response_format,
                    )
                    .await
                }
            }
            Err(response) => response,
        },
        #[cfg(feature = "app_api")]
        ToriiProxyRequestKindV4::Read(read_request) => {
            let routing_decision: RoutingDecision = read_request.expected_route.into();
            let routing_decision =
                match validate_incoming_read_proxy_route(app, routing_decision, "read") {
                    Ok(route) => route,
                    Err(response) => return response,
                };
            if !should_execute_incoming_torii_proxy_request_locally(
                app,
                &proxy_request_context.request,
                routing_decision,
            ) {
                forward_incoming_torii_proxy_request_from_sender(
                    app,
                    immediate_sender_peer_id.as_ref(),
                    routing_decision,
                    &proxy_request_context,
                )
                .await
            } else {
                execute_torii_read_request_locally(app, read_request, routing_decision, "proxy")
                    .await
            }
        }
        #[cfg(feature = "app_api")]
        ToriiProxyRequestKindV4::ReadFanout(read_request) => {
            match torii_nexus_route(app.as_ref()) {
                Ok(nexus_route) => {
                    if !should_execute_incoming_torii_proxy_request_locally(
                        app,
                        &proxy_request_context.request,
                        nexus_route,
                    ) {
                        forward_incoming_torii_proxy_request_from_sender(
                            app,
                            immediate_sender_peer_id.as_ref(),
                            nexus_route,
                            &proxy_request_context,
                        )
                        .await
                    } else {
                        execute_torii_read_fanout_proxy_request(app, read_request).await
                    }
                }
                Err(response) => response,
            }
        }
        #[cfg(feature = "app_api")]
        ToriiProxyRequestKindV4::HostedHttp(hosted_request) => {
            let uri = match hosted_request.query_string.as_deref() {
                Some(query) => format!("{}?{query}", hosted_request.request_path),
                None => hosted_request.request_path.clone(),
            };
            match (
                uri.parse::<axum::http::Uri>(),
                axum::http::Method::from_bytes(hosted_request.method.as_bytes()),
                hosted_request
                    .remote_ip
                    .as_deref()
                    .map(str::parse::<IpAddr>)
                    .transpose(),
            ) {
                (Err(error), _, _) => torii_proxy_error_response(
                    StatusCode::BAD_REQUEST,
                    "invalid_proxy_request",
                    format!("failed to decode proxied hosted HTTP URI: {error}"),
                ),
                (_, Err(error), _) => torii_proxy_error_response(
                    StatusCode::BAD_REQUEST,
                    "invalid_proxy_request",
                    format!("failed to decode proxied hosted HTTP method: {error}"),
                ),
                (_, _, Err(error)) => torii_proxy_error_response(
                    StatusCode::BAD_REQUEST,
                    "invalid_proxy_request",
                    format!("failed to decode proxied hosted HTTP remote IP: {error}"),
                ),
                (Ok(uri), Ok(method), Ok(_remote_ip)) => {
                    match resolve_exact_hosted_http_runtime_target(
                        app,
                        &hosted_request.service_name,
                        &hosted_request.service_version,
                        hosted_request.replica_slot,
                    ) {
                        Ok(target) => {
                            let route_match = soracloud::HostedHttpRouteMatch {
                                service_name: hosted_request.service_name,
                                service_version: hosted_request.service_version,
                                request_path: hosted_request.request_path,
                            };
                            match target.local_listen_base_url.as_deref() {
                                Some(listen_base_url) => {
                                    match proxy_soracloud_public_hosted_http_locally(
                                        &method,
                                        &uri,
                                        &torii_proxy_headers_to_header_map(&hosted_request.headers),
                                        Bytes::from(hosted_request.body),
                                        &route_match,
                                        listen_base_url,
                                    )
                                    .await
                                    {
                                        Ok(response) => response,
                                        Err(error) => soracloud_local_read_error_response(error),
                                    }
                                }
                                None => torii_proxy_error_response(
                                    StatusCode::SERVICE_UNAVAILABLE,
                                    "route_unavailable",
                                    format!(
                                        "hosted Soracloud service `{}` revision `{}` replica {} has no active local loopback listener",
                                        route_match.service_name,
                                        route_match.service_version,
                                        target.replica_slot
                                    ),
                                ),
                            }
                        }
                        Err(error) => soracloud_local_read_error_response(error),
                    }
                }
            }
        }
        #[cfg(not(feature = "app_api"))]
        ToriiProxyRequestKindV4::Read(_) => {
            app_api_required_torii_proxy_response("Torii read proxying")
        }
        #[cfg(not(feature = "app_api"))]
        ToriiProxyRequestKindV4::ReadFanout(_) => {
            app_api_required_torii_proxy_response("Torii read fanout proxying")
        }
        #[cfg(not(feature = "app_api"))]
        ToriiProxyRequestKindV4::HostedHttp(_) => {
            app_api_required_torii_proxy_response("Torii hosted HTTP proxying")
        }
    }
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
async fn process_incoming_torii_proxy_request(
    app: SharedAppState,
    network: iroha_core::IrohaNetwork,
    peer: Peer,
    proxy_request: ToriiProxyRequestV5,
) {
    let request_id = proxy_request.request_id.clone();
    let sender_peer_id = peer.id().clone();
    let response_body_limit = torii_proxy_response_body_limit(app.as_ref(), &proxy_request.request);
    iroha_logger::debug!(
        request_id = %request_id,
        peer_id = %sender_peer_id,
        hop_count = proxy_request.hop_count,
        max_hops = proxy_request.max_hops,
        visited_peer_count = proxy_request.visited_peer_ids.len(),
        "received Torii proxy request"
    );
    let response =
        execute_incoming_torii_proxy_request(&app, proxy_request, Some(sender_peer_id)).await;

    network.post(iroha_p2p::Post {
        peer_id: peer.id().clone(),
        priority: iroha_p2p::Priority::High,
        data: iroha_core::NetworkMessage::ToriiProxyResponse(Box::new(ToriiProxyResponseV1 {
            schema_version: TORII_PROXY_RESPONSE_VERSION_V1,
            request_id,
            response: response_to_torii_proxy_snapshot(response, response_body_limit).await,
        })),
    });
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
async fn process_incoming_torii_proxy_response(
    app: &SharedAppState,
    responder_peer_id: PeerId,
    proxy_response: ToriiProxyResponseV1,
) {
    let pending_key = (proxy_response.request_id, responder_peer_id.clone());
    let (pending, has_other_pending) = {
        let mut pending_requests = app.torii_proxy_pending.lock().await;
        let pending = pending_requests.remove(&pending_key);
        let has_other_pending = pending_requests
            .keys()
            .any(|(request_id, _)| *request_id == pending_key.0);
        (pending, has_other_pending)
    };

    let Some(pending) = pending else {
        let mut completed = app.torii_proxy_completed.lock().await;
        if let Some(entry) = completed.entries.get_mut(&pending_key.0) {
            if !entry.late_response_logged {
                entry.late_response_logged = true;
                iroha_logger::debug!(
                    peer_id = %responder_peer_id,
                    request_id = %pending_key.0,
                    "ignoring late Torii proxy response after request completion"
                );
            }
            return;
        }
        drop(completed);

        if has_other_pending {
            iroha_logger::warn!(
                peer_id = %responder_peer_id,
                request_id = %pending_key.0,
                "ignoring Torii proxy response from an unexpected peer"
            );
        } else {
            iroha_logger::warn!(
                peer_id = %responder_peer_id,
                request_id = %pending_key.0,
                "ignoring Torii proxy response without a pending request"
            );
        }
        return;
    };

    if proxy_response.response.body.len() > pending.max_body_bytes {
        iroha_logger::warn!(
            peer_id = %responder_peer_id,
            request_id = %proxy_response.request_id,
            response_body_bytes = proxy_response.response.body.len(),
            max_body_bytes = pending.max_body_bytes,
            "dropping oversized Torii proxy response from authenticated peer"
        );
        return;
    }
    if pending.strict_queue_plan_synced
        && let Err(error) = validate_queue_plan_synced_snapshot_bounds(&proxy_response.response)
    {
        iroha_logger::warn!(
            peer_id = %responder_peer_id,
            request_id = %proxy_response.request_id,
            %error,
            "dropping Torii proxy response that violates QueuePlanSynced bounds"
        );
        return;
    }

    if proxy_response.schema_version != TORII_PROXY_RESPONSE_VERSION_V1 {
        let _ = pending.sender.send(ToriiProxyHttpResponseV1 {
            status_code: StatusCode::BAD_GATEWAY.as_u16(),
            headers: Vec::new(),
            body: format!(
                "Torii proxy response for request `{}` from peer `{}` used unsupported schema_version `{}`",
                proxy_response.request_id, responder_peer_id, proxy_response.schema_version
            )
            .into_bytes(),
        });
        return;
    }

    let _ = pending.sender.send(proxy_response.response);
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
async fn handle_torii_proxy_network_message(
    app: SharedAppState,
    network: iroha_core::IrohaNetwork,
    peer: Peer,
    payload: iroha_core::NetworkMessage,
) {
    debug_assert!(
        payload.is_torii_proxy_control_message(),
        "Torii proxy dispatcher should only receive Torii/Soracloud proxy control messages"
    );

    match payload {
        iroha_core::NetworkMessage::ToriiProxyRequest(request) => {
            process_incoming_torii_proxy_request(app, network, peer, *request).await;
        }
        iroha_core::NetworkMessage::ToriiProxyResponse(response) => {
            process_incoming_torii_proxy_response(&app, peer.id().clone(), *response).await;
        }
        #[cfg(feature = "app_api")]
        iroha_core::NetworkMessage::SoracloudLocalReadProxyRequest(request) => {
            process_incoming_soracloud_proxy_request(app, network, peer, *request).await;
        }
        #[cfg(feature = "app_api")]
        iroha_core::NetworkMessage::SoracloudLocalReadProxyResponse(response) => {
            process_incoming_soracloud_proxy_response(&app, peer.id().clone(), *response).await;
        }
        _ => {}
    }
}

#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn attach_torii_proxy_network(app: SharedAppState, network: iroha_core::IrohaNetwork) {
    tokio::spawn(async move {
        use iroha_p2p::network::{
            SubscriberFilter,
            message::{SubscriberRoute, Topic},
        };

        let (tx, mut rx) = tokio::sync::mpsc::channel(network.subscriber_queue_cap().get());
        let filter =
            SubscriberFilter::topics_for_route([Topic::Control], SubscriberRoute::ToriiProxy);
        let mut tx = tx;
        loop {
            match network.subscribe_to_peers_messages_with_filter(tx, filter.clone()) {
                Ok(()) => break,
                Err(returned) => {
                    iroha_logger::warn!(
                        "retrying Torii control-plane proxy subscription to the P2P bus"
                    );
                    tx = returned;
                    tokio::time::sleep(Duration::from_millis(50)).await;
                }
            }
        }

        while let Some(msg) = rx.recv().await {
            if msg.payload.is_torii_proxy_control_message() {
                handle_torii_proxy_network_message(
                    app.clone(),
                    network.clone(),
                    msg.peer,
                    msg.payload,
                )
                .await;
            }
        }
    });
}

#[cfg(feature = "app_api")]
fn soracloud_local_read_response(
    response: iroha_core::soracloud_runtime::SoracloudLocalReadResponse,
) -> Response {
    let mut builder = Response::builder().status(StatusCode::OK);
    if let Some(content_type) = response.content_type.as_deref() {
        builder = builder.header(axum::http::header::CONTENT_TYPE, content_type);
    }
    if let Some(content_encoding) = response.content_encoding.as_deref() {
        builder = builder.header(axum::http::header::CONTENT_ENCODING, content_encoding);
    }
    if let Some(cache_control) = response.cache_control.as_deref() {
        builder = builder.header(axum::http::header::CACHE_CONTROL, cache_control);
    }
    builder = builder
        .header(
            "x-iroha-soracloud-certified-by",
            match response.certified_by {
                iroha_data_model::soracloud::SoraCertifiedResponsePolicyV1::None => "none",
                iroha_data_model::soracloud::SoraCertifiedResponsePolicyV1::StateCommitment => {
                    "state_commitment"
                }
                iroha_data_model::soracloud::SoraCertifiedResponsePolicyV1::AuditReceipt => {
                    "audit_receipt"
                }
            },
        )
        .header(
            "x-iroha-soracloud-result-commitment",
            response.result_commitment.to_string(),
        );

    if let Ok(bindings_json) = norito::json::to_json(&response.bindings) {
        let encoded = base64::engine::general_purpose::STANDARD.encode(bindings_json);
        builder = builder.header("x-iroha-soracloud-bindings", encoded);
    }
    if let Some(receipt) = response.runtime_receipt.as_ref() {
        builder = builder.header(
            "x-iroha-soracloud-receipt-id",
            receipt.receipt_id.to_string(),
        );
        if let Ok(receipt_json) = norito::json::to_json(receipt) {
            let encoded = base64::engine::general_purpose::STANDARD.encode(receipt_json);
            builder = builder.header("x-iroha-soracloud-receipt", encoded);
        }
    }

    builder
        .body(Body::from(response.response_bytes))
        .unwrap_or_else(|error| {
            iroha_logger::error!(?error, "failed to build Soracloud local-read response");
            Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .body(Body::from("failed to build Soracloud local-read response"))
                .expect("static response build succeeds")
        })
}

#[cfg(feature = "app_api")]
fn soracloud_ordered_mailbox_response(
    response: iroha_core::soracloud_runtime::SoracloudOrderedMailboxExecutionResult,
) -> Response {
    let mut builder = Response::builder().status(StatusCode::OK);
    if let Some(content_type) = response.content_type.as_deref() {
        builder = builder.header(axum::http::header::CONTENT_TYPE, content_type);
    }
    builder = builder
        .header(axum::http::header::CACHE_CONTROL, "no-store")
        .header("x-iroha-soracloud-certified-by", "none")
        .header(
            "x-iroha-soracloud-result-commitment",
            response.runtime_receipt.result_commitment.to_string(),
        )
        .header(
            "x-iroha-soracloud-receipt-id",
            response.runtime_receipt.receipt_id.to_string(),
        );
    if let Ok(receipt_json) = norito::json::to_json(&response.runtime_receipt) {
        let encoded = base64::engine::general_purpose::STANDARD.encode(receipt_json);
        builder = builder.header("x-iroha-soracloud-receipt", encoded);
    }
    builder
        .body(Body::from(response.response_bytes))
        .unwrap_or_else(|error| {
            iroha_logger::error!(?error, "failed to build Soracloud ordered-mailbox response");
            Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .body(Body::from(
                    "failed to build Soracloud ordered-mailbox response",
                ))
                .expect("static response build succeeds")
        })
}

#[cfg(feature = "app_api")]
fn soracloud_local_read_error_response(
    error: iroha_core::soracloud_runtime::SoracloudRuntimeExecutionError,
) -> Response {
    let status = match error.kind {
        SoracloudRuntimeExecutionErrorKind::Unavailable => StatusCode::SERVICE_UNAVAILABLE,
        SoracloudRuntimeExecutionErrorKind::InvalidRequest => StatusCode::BAD_REQUEST,
        SoracloudRuntimeExecutionErrorKind::Internal => StatusCode::INTERNAL_SERVER_ERROR,
    };
    Response::builder()
        .status(status)
        .body(Body::from(error.message))
        .unwrap_or_else(|build_error| {
            iroha_logger::error!(
                ?build_error,
                "failed to build Soracloud local-read error response"
            );
            StatusCode::INTERNAL_SERVER_ERROR.into_response()
        })
}

#[cfg(feature = "app_api")]
fn soracloud_public_runtime_unavailable(message: impl Into<String>) -> Response {
    Response::builder()
        .status(StatusCode::SERVICE_UNAVAILABLE)
        .body(Body::from(message.into()))
        .unwrap_or_else(|_| StatusCode::SERVICE_UNAVAILABLE.into_response())
}

#[cfg(feature = "app_api")]
fn hosted_http_request_hash(
    scope: &str,
    service_name: &str,
    service_version: Option<&str>,
    remote_ip: Option<IpAddr>,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
) -> [u8; 32] {
    let payload = norito::to_bytes(&(
        scope,
        service_name,
        service_version,
        remote_ip.map(|ip| ip.to_string()),
        method.as_str(),
        uri.path(),
        uri.query(),
    ))
    .expect("hosted-http request hash payload should encode");
    *blake3_hash(&payload).as_bytes()
}

#[cfg(feature = "app_api")]
fn hosted_http_rollout_bucket(
    service_name: &str,
    remote_ip: Option<IpAddr>,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
) -> u8 {
    let digest = hosted_http_request_hash(
        "soracloud:hosted-http-rollout:v1",
        service_name,
        None,
        remote_ip,
        method,
        uri,
    );
    (u16::from_le_bytes([digest[0], digest[1]]) % 100) as u8
}

#[cfg(feature = "app_api")]
fn select_authoritative_hosted_http_replica(
    world: &impl WorldReadOnly,
    service_name: &str,
    service_version: &str,
    placements: &[iroha_data_model::soracloud::SoraInrouReplicaPlacementV1],
    remote_ip: Option<IpAddr>,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
) -> Option<(
    iroha_data_model::soracloud::SoraInrouReplicaPlacementV1,
    iroha_data_model::soracloud::SoraInrouReplicaRuntimeStateV1,
)> {
    let healthy_replicas = placements
        .iter()
        .filter_map(|placement| {
            let runtime_state = world.soracloud_inrou_replica_runtime().get(&(
                service_name.to_owned(),
                service_version.to_owned(),
                placement.replica_slot.to_string(),
            ))?;
            (runtime_state.validator_account_id == placement.validator_account_id
                && runtime_state.peer_id == placement.peer_id
                && runtime_state.selected_backend == placement.selected_backend
                && runtime_state.selected_guest_isa == placement.selected_guest_isa
                && runtime_state.health_status
                    == iroha_data_model::soracloud::SoraServiceHealthStatusV1::Healthy)
                .then(|| (placement.clone(), runtime_state.clone()))
        })
        .collect::<Vec<_>>();
    if healthy_replicas.is_empty() {
        return None;
    }
    if healthy_replicas.len() == 1 {
        return healthy_replicas.into_iter().next();
    }

    let digest = hosted_http_request_hash(
        "soracloud:hosted-http-replica:v1",
        service_name,
        Some(service_version),
        remote_ip,
        method,
        uri,
    );
    let index = usize::from(u16::from_le_bytes([digest[0], digest[1]])) % healthy_replicas.len();
    healthy_replicas.into_iter().nth(index)
}

#[cfg(feature = "app_api")]
fn authoritative_weighted_hosted_http_versions(
    app: &SharedAppState,
    service_name: &str,
) -> Result<Vec<(String, u8)>, SoracloudRuntimeExecutionError> {
    let current_sequence = soracloud::authoritative_soracloud_sequence(app);
    let deployment_name: Name = service_name.parse().map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "hosted Soracloud service name `{service_name}` is invalid in authoritative state: {error}"
            ),
        )
    })?;
    let state_view = app.state.view();
    let world = state_view.world();
    let Some(deployment) = world.soracloud_service_deployments().get(&deployment_name) else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!("hosted Soracloud deployment for service `{service_name}` is unavailable"),
        ));
    };
    let lease_status = deployment
        .hosted_service_lease_status_at(current_sequence)
        .map_err(|error| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Internal,
                format!(
                    "hosted Soracloud lease status for service `{service_name}` could not be calculated: {error}"
                ),
            )
        })?
        .ok_or_else(|| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!("hosted Soracloud lease for service `{service_name}` is unavailable"),
            )
        })?;
    if lease_status != iroha_data_model::soracloud::SoraServiceLeaseStatusV1::Active {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "hosted Soracloud lease for service `{service_name}` is not active ({lease_status:?})"
            ),
        ));
    }

    let mut versions = Vec::with_capacity(2);
    if let Some(rollout) = deployment.active_rollout.as_ref() {
        let canary_weight = rollout.traffic_percent.min(100);
        let baseline_weight = 100u8.saturating_sub(canary_weight);
        if canary_weight > 0 && rollout.candidate_version != deployment.current_service_version {
            versions.push((rollout.candidate_version.clone(), canary_weight));
        }
        if baseline_weight > 0 {
            versions.push((deployment.current_service_version.clone(), baseline_weight));
        }
    } else {
        versions.push((deployment.current_service_version.clone(), 100));
    }
    Ok(versions)
}

#[cfg(feature = "app_api")]
#[derive(Clone, Debug)]
struct ResolvedHostedHttpTarget {
    route_match: soracloud::HostedHttpRouteMatch,
    replica_slot: u16,
    assigned_peer_id: PeerId,
    local_listen_base_url: Option<String>,
}

#[cfg(feature = "app_api")]
struct HyperTokioTcpStream(tokio::net::TcpStream);

#[cfg(feature = "app_api")]
impl hyper::rt::Read for HyperTokioTcpStream {
    fn poll_read(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        mut buf: hyper::rt::ReadBufCursor<'_>,
    ) -> std::task::Poll<Result<(), std::io::Error>> {
        let mut scratch = [0u8; 8192];
        let read_len = scratch.len().min(buf.remaining());
        let mut tokio_buf = tokio::io::ReadBuf::new(&mut scratch[..read_len]);
        match tokio::io::AsyncRead::poll_read(std::pin::Pin::new(&mut self.0), cx, &mut tokio_buf) {
            std::task::Poll::Ready(Ok(())) => buf.put_slice(tokio_buf.filled()),
            other => return other,
        }
        std::task::Poll::Ready(Ok(()))
    }
}

#[cfg(feature = "app_api")]
impl hyper::rt::Write for HyperTokioTcpStream {
    fn poll_write(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &[u8],
    ) -> std::task::Poll<Result<usize, std::io::Error>> {
        tokio::io::AsyncWrite::poll_write(std::pin::Pin::new(&mut self.0), cx, buf)
    }

    fn poll_flush(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Result<(), std::io::Error>> {
        tokio::io::AsyncWrite::poll_flush(std::pin::Pin::new(&mut self.0), cx)
    }

    fn poll_shutdown(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Result<(), std::io::Error>> {
        tokio::io::AsyncWrite::poll_shutdown(std::pin::Pin::new(&mut self.0), cx)
    }

    fn is_write_vectored(&self) -> bool {
        tokio::io::AsyncWrite::is_write_vectored(&self.0)
    }

    fn poll_write_vectored(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        bufs: &[std::io::IoSlice<'_>],
    ) -> std::task::Poll<Result<usize, std::io::Error>> {
        tokio::io::AsyncWrite::poll_write_vectored(std::pin::Pin::new(&mut self.0), cx, bufs)
    }
}

#[cfg(feature = "app_api")]
#[cfg(any(feature = "p2p_ws", feature = "connect"))]
fn ensure_local_hosted_http_snapshot_origin(
    app: &AppState,
    snapshot: &iroha_core::soracloud_runtime::SoracloudRuntimeSnapshot,
) -> Result<(), SoracloudRuntimeExecutionError> {
    let Some(snapshot_peer_id) = snapshot.local_peer_id.as_deref() else {
        return Ok(());
    };
    let Some(local_peer_id) = app.local_peer_id.as_ref() else {
        return Ok(());
    };
    if snapshot_peer_id == local_peer_id.to_string() {
        return Ok(());
    }
    Err(SoracloudRuntimeExecutionError::new(
        SoracloudRuntimeExecutionErrorKind::Unavailable,
        format!(
            "hosted Soracloud runtime snapshot belongs to peer `{snapshot_peer_id}`, not local ingress peer `{local_peer_id}`"
        ),
    ))
}

#[cfg(feature = "app_api")]
#[cfg(not(any(feature = "p2p_ws", feature = "connect")))]
fn ensure_local_hosted_http_snapshot_origin(
    _app: &AppState,
    _snapshot: &iroha_core::soracloud_runtime::SoracloudRuntimeSnapshot,
) -> Result<(), SoracloudRuntimeExecutionError> {
    Ok(())
}

#[cfg(feature = "app_api")]
fn resolve_local_hosted_http_replica_listener(
    app: &SharedAppState,
    service_name: &str,
    service_version: &str,
    replica_slot: u16,
) -> Result<Option<String>, SoracloudRuntimeExecutionError> {
    let Some(runtime) = app.soracloud_runtime.as_ref() else {
        return Ok(None);
    };
    let snapshot = runtime.snapshot();
    ensure_local_hosted_http_snapshot_origin(app.as_ref(), &snapshot)?;
    Ok(snapshot
        .services
        .get(service_name)
        .and_then(|versions| versions.get(service_version))
        .and_then(|plan| {
            plan.local_replicas
                .iter()
                .find(|replica| {
                    replica.replica_slot == replica_slot
                        && replica.health_status
                            == iroha_data_model::soracloud::SoraServiceHealthStatusV1::Healthy
                })
                .and_then(|replica| replica.listen_base_url.clone())
        }))
}

#[cfg(feature = "app_api")]
fn local_healthy_hosted_http_placement(
    app: &SharedAppState,
    service_name: &str,
    service_version: &str,
    placements: &[iroha_data_model::soracloud::SoraInrouReplicaPlacementV1],
) -> Result<
    Option<iroha_data_model::soracloud::SoraInrouReplicaPlacementV1>,
    SoracloudRuntimeExecutionError,
> {
    let Some(local_peer_id) = app.local_peer_id.as_ref() else {
        return Ok(None);
    };
    let local_peer_id = local_peer_id.to_string();
    for placement in placements {
        if placement.peer_id != local_peer_id {
            continue;
        }
        if resolve_local_hosted_http_replica_listener(
            app,
            service_name,
            service_version,
            placement.replica_slot,
        )?
        .is_some()
        {
            return Ok(Some(placement.clone()));
        }
    }
    Ok(None)
}

#[cfg(feature = "app_api")]
fn resolve_hosted_http_runtime_target(
    app: &SharedAppState,
    route_match: &soracloud::HostedHttpRouteMatch,
    remote_ip: Option<IpAddr>,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
) -> Result<ResolvedHostedHttpTarget, SoracloudRuntimeExecutionError> {
    struct HealthyTarget {
        route_match: soracloud::HostedHttpRouteMatch,
        replica_slot: u16,
        peer_id: String,
        weight: u8,
    }

    let service_name = route_match.service_name.clone();
    let weighted_versions = authoritative_weighted_hosted_http_versions(app, &service_name)?;

    let mut healthy_targets = Vec::with_capacity(weighted_versions.len());
    let state_view = app.state.view();
    let world = state_view.world();
    for (service_version, weight) in &weighted_versions {
        if *weight == 0 {
            continue;
        }
        let Some(placement_record) = world
            .soracloud_inrou_service_placements()
            .get(&(service_name.clone(), service_version.clone()))
        else {
            continue;
        };
        let placement = if let Some((placement, _runtime_state)) =
            select_authoritative_hosted_http_replica(
                world,
                &service_name,
                service_version,
                &placement_record.placements,
                remote_ip,
                method,
                uri,
            ) {
            placement
        } else if let Some(placement) = local_healthy_hosted_http_placement(
            app,
            &service_name,
            service_version,
            &placement_record.placements,
        )? {
            placement
        } else {
            continue;
        };
        healthy_targets.push(HealthyTarget {
            route_match: soracloud::HostedHttpRouteMatch {
                service_name: service_name.clone(),
                service_version: service_version.clone(),
                request_path: route_match.request_path.clone(),
            },
            replica_slot: placement.replica_slot,
            peer_id: placement.peer_id,
            weight: *weight,
        });
    }
    drop(state_view);

    if healthy_targets.is_empty() {
        let requested_versions = weighted_versions
            .into_iter()
            .map(|(version, weight)| format!("{version} ({weight}%)"))
            .collect::<Vec<_>>()
            .join(", ");
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "no healthy hosted Soracloud revision is available for service `{service_name}` across [{requested_versions}]"
            ),
        ));
    }

    if healthy_targets.len() == 1 {
        let selected = healthy_targets.remove(0);
        let assigned_peer_id = selected.peer_id.parse::<PeerId>().map_err(|error| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Internal,
                format!(
                    "authoritative hosted Soracloud peer id `{}` for service `{}` revision `{}` replica {} is invalid: {error}",
                    selected.peer_id,
                    selected.route_match.service_name,
                    selected.route_match.service_version,
                    selected.replica_slot
                ),
            )
        })?;
        let local_listen_base_url = app
            .local_peer_id
            .as_ref()
            .filter(|local_peer_id| local_peer_id.to_string() == selected.peer_id)
            .map(|_| {
                resolve_local_hosted_http_replica_listener(
                    app,
                    &selected.route_match.service_name,
                    &selected.route_match.service_version,
                    selected.replica_slot,
                )
            })
            .transpose()?
            .flatten();
        return Ok(ResolvedHostedHttpTarget {
            route_match: selected.route_match,
            replica_slot: selected.replica_slot,
            assigned_peer_id,
            local_listen_base_url,
        });
    }

    // Keep canary routing deterministic per client/request tuple so traffic stays stable while
    // still honoring the configured rollout percentage.
    let bucket = hosted_http_rollout_bucket(&service_name, remote_ip, method, uri);
    let mut cumulative = 0u8;
    let selected_index = healthy_targets
        .iter()
        .position(|target| {
            cumulative = cumulative.saturating_add(target.weight);
            bucket < cumulative
        })
        .unwrap_or(healthy_targets.len() - 1);
    let selected = healthy_targets.remove(selected_index);
    let assigned_peer_id = selected.peer_id.parse::<PeerId>().map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "authoritative hosted Soracloud peer id `{}` for service `{}` revision `{}` replica {} is invalid: {error}",
                selected.peer_id,
                selected.route_match.service_name,
                selected.route_match.service_version,
                selected.replica_slot
            ),
        )
    })?;
    let local_listen_base_url = app
        .local_peer_id
        .as_ref()
        .filter(|local_peer_id| local_peer_id.to_string() == selected.peer_id)
        .map(|_| {
            resolve_local_hosted_http_replica_listener(
                app,
                &selected.route_match.service_name,
                &selected.route_match.service_version,
                selected.replica_slot,
            )
        })
        .transpose()?
        .flatten();
    Ok(ResolvedHostedHttpTarget {
        route_match: selected.route_match,
        replica_slot: selected.replica_slot,
        assigned_peer_id,
        local_listen_base_url,
    })
}

#[cfg(feature = "app_api")]
fn resolve_exact_hosted_http_runtime_target(
    app: &SharedAppState,
    service_name: &str,
    service_version: &str,
    replica_slot: u16,
) -> Result<ResolvedHostedHttpTarget, SoracloudRuntimeExecutionError> {
    let active_versions = authoritative_weighted_hosted_http_versions(app, service_name)?;
    if !active_versions
        .iter()
        .any(|(version, weight)| *weight > 0 && version == service_version)
    {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "hosted Soracloud revision `{service_version}` is not active for service `{service_name}`"
            ),
        ));
    }
    let Some(local_peer_id) = app.local_peer_id.as_ref() else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            "local peer identity is unavailable for hosted Soracloud proxy execution",
        ));
    };
    let state_view = app.state.view();
    let world = state_view.world();
    let Some(placement_record) = world
        .soracloud_inrou_service_placements()
        .get(&(service_name.to_owned(), service_version.to_owned()))
    else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "authoritative hosted Soracloud placement for service `{service_name}` revision `{service_version}` is unavailable"
            ),
        ));
    };
    let Some(placement) = placement_record
        .placements
        .iter()
        .find(|placement| placement.replica_slot == replica_slot)
    else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "authoritative hosted Soracloud replica {} is unavailable for service `{service_name}` revision `{service_version}`",
                replica_slot
            ),
        ));
    };
    if placement.peer_id != local_peer_id.to_string() {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "hosted Soracloud replica {} for service `{service_name}` revision `{service_version}` is assigned to peer `{}`, not `{}`",
                replica_slot, placement.peer_id, local_peer_id
            ),
        ));
    }
    let runtime_state = world.soracloud_inrou_replica_runtime().get(&(
        service_name.to_owned(),
        service_version.to_owned(),
        replica_slot.to_string(),
    ));
    if !runtime_state.is_some_and(|runtime_state| {
        runtime_state.validator_account_id == placement.validator_account_id
            && runtime_state.peer_id == placement.peer_id
            && runtime_state.selected_backend == placement.selected_backend
            && runtime_state.selected_guest_isa == placement.selected_guest_isa
            && runtime_state.health_status
                == iroha_data_model::soracloud::SoraServiceHealthStatusV1::Healthy
    }) {
        let local_listener = resolve_local_hosted_http_replica_listener(
            app,
            service_name,
            service_version,
            replica_slot,
        )?;
        if local_listener.is_none() {
            return Err(SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!(
                    "hosted Soracloud replica {} for service `{service_name}` revision `{service_version}` is not healthy in authoritative state or local runtime snapshot",
                    replica_slot
                ),
            ));
        }
    }
    drop(state_view);
    let local_listen_base_url = resolve_local_hosted_http_replica_listener(
        app,
        service_name,
        service_version,
        replica_slot,
    )?;
    Ok(ResolvedHostedHttpTarget {
        route_match: soracloud::HostedHttpRouteMatch {
            service_name: service_name.to_owned(),
            service_version: service_version.to_owned(),
            request_path: String::new(),
        },
        replica_slot,
        assigned_peer_id: local_peer_id.clone(),
        local_listen_base_url,
    })
}

#[cfg(feature = "app_api")]
async fn proxy_soracloud_public_hosted_http_locally(
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    headers: &HeaderMap,
    body: Bytes,
    route_match: &soracloud::HostedHttpRouteMatch,
    listen_base_url: &str,
) -> Result<Response, SoracloudRuntimeExecutionError> {
    let reqwest_method =
        reqwest::Method::from_bytes(method.as_str().as_bytes()).map_err(|error| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::InvalidRequest,
                format!("unsupported request method: {error}"),
            )
        })?;
    let mut upstream_url = reqwest::Url::parse(listen_base_url).map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!("invalid hosted listener URL: {error}"),
        )
    })?;
    upstream_url.set_path(route_match.request_path.as_str());
    upstream_url.set_query(uri.query());

    if upstream_url.scheme() != "http" {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "hosted Soracloud service `{}` revision `{}` listener URL must use http for loopback proxying",
                route_match.service_name, route_match.service_version
            ),
        ));
    }
    let Some(host) = upstream_url.host_str() else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            "hosted listener URL is missing a host",
        ));
    };
    let Some(port) = upstream_url.port_or_known_default() else {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            "hosted listener URL is missing a port",
        ));
    };
    let stream = tokio::net::TcpStream::connect((host, port))
        .await
        .map_err(|error| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!(
                    "hosted Soracloud service `{}` revision `{}` proxy failed: {error}",
                    route_match.service_name, route_match.service_version
                ),
            )
        })?;
    let (mut sender, connection) =
        hyper::client::conn::http1::handshake(HyperTokioTcpStream(stream))
            .await
            .map_err(|error| {
                SoracloudRuntimeExecutionError::new(
                    SoracloudRuntimeExecutionErrorKind::Unavailable,
                    format!(
                        "hosted Soracloud service `{}` revision `{}` proxy failed: {error}",
                        route_match.service_name, route_match.service_version
                    ),
                )
            })?;
    tokio::spawn(async move {
        let _ = connection.await;
    });

    let mut path_and_query = upstream_url.path().to_owned();
    if path_and_query.is_empty() {
        path_and_query.push('/');
    }
    if let Some(query) = upstream_url.query() {
        path_and_query.push('?');
        path_and_query.push_str(query);
    }
    let mut builder = Request::builder()
        .method(reqwest_method.as_str())
        .uri(path_and_query);
    let display_host = if host.contains(':') {
        format!("[{host}]")
    } else {
        host.to_owned()
    };
    let host_header = if upstream_url.port().is_some() {
        format!("{display_host}:{port}")
    } else {
        display_host
    };
    builder = builder.header(axum::http::header::HOST, host_header);
    for (name, value) in headers {
        if name == &axum::http::header::HOST || name == &axum::http::header::CONTENT_LENGTH {
            continue;
        }
        builder = builder.header(name, value);
    }
    let upstream_request = builder
        .body(http_body_util::Full::new(body))
        .map_err(|error| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::InvalidRequest,
                format!("failed to build hosted HTTP proxy request: {error}"),
            )
        })?;
    let upstream_response = sender
        .send_request(upstream_request)
        .await
        .map_err(|error| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!(
                    "hosted Soracloud service `{}` revision `{}` proxy failed: {error}",
                    route_match.service_name, route_match.service_version
                ),
            )
        })?;

    let status = upstream_response.status();
    let response_headers = upstream_response.headers().clone();
    let response_body = Body::from_stream(http_body_util::BodyDataStream::new(
        upstream_response.into_body(),
    ));
    let mut builder = Response::builder().status(status);
    for (name, value) in &response_headers {
        if name == axum::http::header::CONTENT_LENGTH
            || name == axum::http::header::TRANSFER_ENCODING
            || name == axum::http::header::CONNECTION
        {
            continue;
        }
        builder = builder.header(name, value);
    }
    Ok(builder
        .body(response_body)
        .unwrap_or_else(|_| StatusCode::BAD_GATEWAY.into_response()))
}

#[cfg(all(feature = "app_api", any(feature = "p2p_ws", feature = "connect")))]
async fn execute_hosted_http_proxy_request_with_fallback(
    app: &SharedAppState,
    target: &ResolvedHostedHttpTarget,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    headers: &HeaderMap,
    body: Bytes,
    remote_ip: Option<IpAddr>,
) -> Option<Response> {
    let Some(local_peer_id) = app.local_peer_id.as_ref() else {
        return None;
    };
    let Some(_network) = app.p2p.as_ref() else {
        return None;
    };

    let request_kind = ToriiProxyRequestKindV4::HostedHttp(ToriiHostedHttpProxyRequestV1 {
        service_name: target.route_match.service_name.clone(),
        service_version: target.route_match.service_version.clone(),
        replica_slot: target.replica_slot,
        request_path: target.route_match.request_path.clone(),
        method: method.as_str().to_owned(),
        query_string: uri.query().map(ToOwned::to_owned),
        headers: header_map_to_torii_proxy_headers(headers),
        body: body.to_vec(),
        remote_ip: remote_ip.map(|ip| ip.to_string()),
    });
    let request = match new_torii_proxy_request(app.as_ref(), request_kind) {
        Ok(request) => request,
        Err(response) => return Some(response),
    };

    let candidates = hosted_http_proxy_candidate_peer_ids(
        app.as_ref(),
        local_peer_id,
        std::slice::from_ref(&target.assigned_peer_id),
        &request.visited_peer_ids,
    );
    iroha_logger::debug!(
        request_id = %request.request_id,
        service_name = %target.route_match.service_name,
        service_version = %target.route_match.service_version,
        replica_slot = target.replica_slot,
        proxy_candidate_count = candidates.peers.len(),
        loop_prevention_drops = candidates.loop_prevention_drops,
        "Soracloud hosted-HTTP proxy prepared peer candidates"
    );
    if candidates.peers.is_empty() {
        return Some(torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!(
                "no authoritative hosting peer is available for hosted Soracloud service `{}` revision `{}` replica {}",
                target.route_match.service_name,
                target.route_match.service_version,
                target.replica_slot
            ),
        ));
    }

    let request_id = request.request_id.clone();
    let mut last_retryable: Option<Response> = None;
    let mut inflight = FuturesUnordered::new();
    for (index, peer_id) in candidates.peers.into_iter().enumerate() {
        let launch_delay = if index == 0 {
            Duration::ZERO
        } else {
            torii_proxy_hedge_delay(app.as_ref())
                .saturating_mul(u32::try_from(index).unwrap_or(u32::MAX))
        };
        let request = request.clone();
        inflight.push(async move {
            if launch_delay > Duration::ZERO {
                tokio::time::sleep(launch_delay).await;
            }
            let response =
                execute_torii_proxy_request_via_peer(app, peer_id.clone(), request).await;
            (peer_id, response)
        });
    }

    while let Some((peer_id, outcome)) = inflight.next().await {
        match outcome {
            Ok(snapshot) => {
                let status =
                    StatusCode::from_u16(snapshot.status_code).unwrap_or(StatusCode::BAD_GATEWAY);
                let response = torii_proxy_snapshot_to_response(snapshot);
                if should_retry_torii_proxy_status(status) {
                    last_retryable = Some(response);
                    continue;
                }
                mark_torii_proxy_request_completed(app, request_id.clone()).await;
                return Some(response);
            }
            Err(error) => {
                iroha_logger::warn!(
                    peer_id = %peer_id,
                    service_name = %target.route_match.service_name,
                    service_version = %target.route_match.service_version,
                    replica_slot = target.replica_slot,
                    %error,
                    "Soracloud hosted-HTTP proxy attempt failed"
                );
            }
        }
    }

    mark_torii_proxy_request_completed(app, request_id).await;
    Some(last_retryable.unwrap_or_else(|| {
        torii_proxy_error_response(
            StatusCode::SERVICE_UNAVAILABLE,
            "route_unavailable",
            format!(
                "the authoritative hosting peer did not respond for hosted Soracloud service `{}` revision `{}` replica {}",
                target.route_match.service_name,
                target.route_match.service_version,
                target.replica_slot
            ),
        )
    }))
}

#[cfg(not(any(feature = "p2p_ws", feature = "connect")))]
async fn execute_hosted_http_proxy_request_with_fallback(
    _app: &SharedAppState,
    _target: &ResolvedHostedHttpTarget,
    _method: &axum::http::Method,
    _uri: &axum::http::Uri,
    _headers: &HeaderMap,
    _body: Bytes,
    _remote_ip: Option<IpAddr>,
) -> Option<Response> {
    None
}

#[cfg(feature = "app_api")]
async fn proxy_soracloud_public_hosted_http(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: HeaderMap,
    body: Bytes,
    route_match: soracloud::HostedHttpRouteMatch,
    remote_ip: Option<IpAddr>,
) -> Response {
    let target =
        match resolve_hosted_http_runtime_target(&app, &route_match, remote_ip, &method, &uri) {
            Ok(target) => target,
            Err(error) => return soracloud_local_read_error_response(error),
        };

    if let Some(listen_base_url) = target.local_listen_base_url.as_deref() {
        return match proxy_soracloud_public_hosted_http_locally(
            &method,
            &uri,
            &headers,
            body,
            &target.route_match,
            listen_base_url,
        )
        .await
        {
            Ok(response) => response,
            Err(error) => soracloud_local_read_error_response(error),
        };
    }

    let local_peer_id = app.local_peer_id.as_ref().map(ToString::to_string);
    let assigned_peer_id_string = target.assigned_peer_id.to_string();
    if local_peer_id.as_deref() == Some(assigned_peer_id_string.as_str()) {
        return soracloud_local_read_error_response(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "hosted Soracloud service `{}` revision `{}` replica {} has no active local loopback listener",
                target.route_match.service_name,
                target.route_match.service_version,
                target.replica_slot
            ),
        ));
    }

    match execute_hosted_http_proxy_request_with_fallback(
        &app, &target, &method, &uri, &headers, body, remote_ip,
    )
    .await
    {
        Some(response) => response,
        None => soracloud_local_read_error_response(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "authoritative hosting peer `{}` for hosted Soracloud service `{}` revision `{}` replica {} is unreachable from this ingress node",
                target.assigned_peer_id,
                target.route_match.service_name,
                target.route_match.service_version,
                target.replica_slot
            ),
        )),
    }
}

#[cfg(feature = "app_api")]
fn current_public_soradns_ledger_time_ms(app: &SharedAppState) -> u64 {
    let latest_block_ms = app.state.view().latest_block().map_or(0, |block| {
        u64::try_from(block.header().creation_time().as_millis()).unwrap_or(u64::MAX)
    });
    let wall_clock_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .ok()
        .and_then(|duration| u64::try_from(duration.as_millis()).ok())
        .unwrap_or(latest_block_ms);
    wall_clock_ms.max(latest_block_ms)
}

#[cfg(feature = "app_api")]
fn soradns_public_gateway_error(status: StatusCode, message: impl Into<String>) -> Response {
    (status, message.into()).into_response()
}

#[cfg(feature = "app_api")]
fn resolve_active_soradns_gateway_host(
    app: &SharedAppState,
    fqdn: &str,
) -> Result<String, Response> {
    let now_ms = current_public_soradns_ledger_time_ms(app);
    let state_view = app.state.view();
    let record = iroha_core::sns::get_name_record(
        state_view.world(),
        &state_view.nexus.dataspace_catalog,
        iroha_core::sns::SnsNamespace::Domain,
        fqdn,
        now_ms,
    )
    .map_err(|error| match error {
        iroha_core::sns::SnsError::BadRequest(message) => {
            soradns_public_gateway_error(StatusCode::BAD_REQUEST, message)
        }
        iroha_core::sns::SnsError::NotFound(message) => {
            soradns_public_gateway_error(StatusCode::NOT_FOUND, message)
        }
        iroha_core::sns::SnsError::Conflict(message) => {
            soradns_public_gateway_error(StatusCode::CONFLICT, message)
        }
        iroha_core::sns::SnsError::Internal(message) => {
            soradns_public_gateway_error(StatusCode::INTERNAL_SERVER_ERROR, message)
        }
    })?;
    let normalized_label = record.selector.normalized_label().to_owned();
    match record.status {
        iroha_data_model::sns::NameStatus::Active => Ok(normalized_label),
        other => Err(soradns_public_gateway_error(
            StatusCode::NOT_FOUND,
            format!("SoraDNS alias `{normalized_label}` is not active ({other:?})"),
        )),
    }
}

#[cfg(feature = "app_api")]
fn rewrite_soradns_public_runtime_uri(
    uri: &axum::http::Uri,
    request_path: &str,
) -> Result<axum::http::Uri, Response> {
    let path_and_query = if let Some(query) = uri.query() {
        format!("{request_path}?{query}")
    } else {
        request_path.to_owned()
    };
    let mut parts = uri.clone().into_parts();
    parts.path_and_query = Some(path_and_query.parse().map_err(|error| {
        soradns_public_gateway_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            format!("failed to rewrite Soracloud public runtime path: {error}"),
        )
    })?);
    axum::http::Uri::from_parts(parts).map_err(|error| {
        soradns_public_gateway_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            format!("failed to rebuild Soracloud public runtime URI: {error}"),
        )
    })
}

#[cfg(feature = "app_api")]
fn rewrite_soradns_public_runtime_headers(
    headers: &HeaderMap,
    host: &str,
) -> Result<HeaderMap, Response> {
    let host_value = HeaderValue::from_str(host).map_err(|error| {
        soradns_public_gateway_error(
            StatusCode::BAD_REQUEST,
            format!("invalid SoraDNS alias host `{host}`: {error}"),
        )
    })?;
    let mut rewritten = headers.clone();
    rewritten.insert(axum::http::header::HOST, host_value);
    Ok(rewritten)
}

#[cfg(feature = "app_api")]
fn host_header_without_port(host: &str) -> String {
    let trimmed = host.trim().trim_end_matches('.');
    if trimmed.starts_with('[') {
        return trimmed.to_ascii_lowercase();
    }
    trimmed
        .rsplit_once(':')
        .and_then(|(name, port)| port.chars().all(|ch| ch.is_ascii_digit()).then_some(name))
        .unwrap_or(trimmed)
        .to_ascii_lowercase()
}

#[cfg(feature = "app_api")]
fn soradns_alias_from_taira_mon_host(host: &str) -> Option<String> {
    let normalized_host = host_header_without_port(host);
    let suffix = taira_mon_pretty_gateway_suffix();
    let alias = normalized_host.strip_suffix(suffix)?.strip_suffix('.')?;
    (!alias.is_empty()).then(|| alias.to_owned())
}

#[cfg(feature = "app_api")]
fn rewrite_taira_mon_public_runtime_headers(
    app: &SharedAppState,
    headers: &HeaderMap,
) -> Result<HeaderMap, Response> {
    let Some(host) = headers
        .get(axum::http::header::HOST)
        .and_then(|value| value.to_str().ok())
    else {
        return Ok(headers.clone());
    };
    let Some(alias) = soradns_alias_from_taira_mon_host(host) else {
        return Ok(headers.clone());
    };
    let resolved = resolve_active_soradns_gateway_host(app, &alias)?;
    rewrite_soradns_public_runtime_headers(headers, &resolved)
}

#[cfg(feature = "app_api")]
async fn execute_soracloud_public_runtime_request(
    app: SharedAppState,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: HeaderMap,
    remote_ip: IpAddr,
    body: Bytes,
) -> Response {
    let headers = match rewrite_taira_mon_public_runtime_headers(&app, &headers) {
        Ok(headers) => headers,
        Err(response) => return response,
    };
    let rate_key = limits::key_from_headers(
        &headers,
        Some(remote_ip),
        Some("v1/soracloud/public-runtime"),
        false,
    );
    if !app.soracloud_public_rate_limiter.allow(&rate_key).await {
        return Response::builder()
            .status(StatusCode::TOO_MANY_REQUESTS)
            .header(axum::http::header::RETRY_AFTER, "1")
            .body(Body::from("Soracloud public runtime rate limit exceeded"))
            .unwrap_or_else(|_| StatusCode::TOO_MANY_REQUESTS.into_response());
    }
    let _public_runtime_permit = match app.soracloud_public_inflight.clone().try_acquire_owned() {
        Ok(permit) => permit,
        Err(_) => {
            return Response::builder()
                .status(StatusCode::SERVICE_UNAVAILABLE)
                .body(Body::from("Soracloud public runtime is busy"))
                .unwrap_or_else(|_| StatusCode::SERVICE_UNAVAILABLE.into_response());
        }
    };
    let host = headers
        .get(axum::http::header::HOST)
        .and_then(|value| value.to_str().ok())
        .unwrap_or_default();
    let Some(route_match) =
        soracloud::resolve_public_route(&app, host, method.as_str(), uri.path())
    else {
        return StatusCode::NOT_FOUND.into_response();
    };
    let route_match = match route_match {
        soracloud::PublicRouteMatch::HostedHttp(route_match) => {
            return proxy_soracloud_public_hosted_http(
                State(app),
                method,
                uri,
                headers,
                body,
                route_match,
                Some(remote_ip),
            )
            .await;
        }
        soracloud::PublicRouteMatch::LocalRead(route_match) => route_match,
        soracloud::PublicRouteMatch::OrderedMailbox(route_match) => {
            let (observed_height, observed_block_hash, runtime_state, authoritative_pending) = {
                let state_view = app.state.view();
                let pending = authoritative_pending_public_mailbox_messages(
                    state_view.world(),
                    &route_match.bundle.service.service_name,
                );
                (
                    u64::try_from(state_view.height()).unwrap_or(u64::MAX),
                    state_view.latest_block_hash().map(Hash::from),
                    state_view
                        .world()
                        .soracloud_service_runtime()
                        .get(&route_match.bundle.service.service_name)
                        .cloned(),
                    pending.saturating_add(1),
                )
            };
            let request_headers = canonicalize_soracloud_local_read_headers(&headers);
            let request_body = body.to_vec();
            let execution_sequence = observed_height.max(1);
            let request_commitment = soracloud_public_ordered_mailbox_request_commitment(
                observed_height,
                observed_block_hash,
                &route_match,
                method.as_str(),
                uri.path(),
                uri.query(),
                &request_headers,
                &request_body,
            );
            let message_id = Hash::new(
                norito::to_bytes(&(
                    "soracloud:public-mailbox:v1",
                    route_match.service_name.as_str(),
                    route_match.service_version.as_str(),
                    route_match.handler_name.as_str(),
                    request_commitment,
                ))
                .expect("public mailbox message id encoding should be infallible"),
            );
            let request = iroha_core::soracloud_runtime::SoracloudOrderedMailboxExecutionRequest {
                observed_height,
                observed_block_hash,
                execution_sequence,
                deployment: route_match.deployment.clone(),
                bundle: route_match.bundle.clone(),
                handler: Some(route_match.handler.clone()),
                mailbox_message: iroha_data_model::soracloud::SoraServiceMailboxMessageV1 {
                    schema_version:
                        iroha_data_model::soracloud::SORA_SERVICE_MAILBOX_MESSAGE_VERSION_V1,
                    message_id,
                    from_service: route_match.bundle.service.service_name.clone(),
                    from_handler: route_match.handler.handler_name.clone(),
                    to_service: route_match.bundle.service.service_name.clone(),
                    to_handler: route_match.handler.handler_name.clone(),
                    payload_bytes: request_body,
                    payload_commitment: request_commitment,
                    enqueue_sequence: execution_sequence,
                    available_after_sequence: execution_sequence,
                    expires_at_sequence: None,
                },
                runtime_state,
                authoritative_pending_mailbox_messages: authoritative_pending,
            };
            let execution = app
                .soracloud_runtime
                .as_ref()
                .ok_or_else(|| {
                    SoracloudRuntimeExecutionError::new(
                        SoracloudRuntimeExecutionErrorKind::Unavailable,
                        "Soracloud runtime is unavailable on this ingress node",
                    )
                })
                .and_then(|runtime| runtime.execute_ordered_mailbox(request));
            return match execution {
                Ok(response) => soracloud_ordered_mailbox_response(response),
                Err(error) => soracloud_local_read_error_response(error),
            };
        }
    };

    let (observed_height, observed_block_hash) = {
        let state_view = app.state.view();
        (
            u64::try_from(state_view.height()).unwrap_or(u64::MAX),
            state_view.latest_block_hash().map(Hash::from),
        )
    };
    let request_headers = canonicalize_soracloud_local_read_headers(&headers);
    let mut request = SoracloudLocalReadRequest {
        observed_height,
        observed_block_hash,
        service_name: route_match.service_name,
        service_version: route_match.service_version,
        handler_name: route_match.handler_name,
        handler_class: route_match.handler_class,
        request_method: method.as_str().to_owned(),
        request_path: uri.path().to_owned(),
        handler_path: route_match.handler_path,
        request_query: uri.query().map(ToOwned::to_owned),
        request_headers,
        request_body: body.to_vec(),
        request_commitment: Hash::new(b""),
    };
    request.request_commitment = soracloud_local_read_request_commitment(&request);

    let proxy_target = match resolve_soracloud_local_read_proxy_target(&app, &request) {
        Ok(target) => target,
        Err(error) => {
            maybe_request_soracloud_generated_hf_reconcile(&app, &request, &error);
            return soracloud_local_read_error_response(error);
        }
    };
    let execution = if let Some(primary_peer_id) = proxy_target {
        execute_soracloud_local_read_via_proxy(&app, primary_peer_id, request).await
    } else {
        app.soracloud_runtime
            .as_ref()
            .ok_or_else(|| {
                SoracloudRuntimeExecutionError::new(
                    SoracloudRuntimeExecutionErrorKind::Unavailable,
                    "Soracloud runtime is unavailable on this ingress node",
                )
            })
            .and_then(|runtime| runtime.execute_local_read(request))
    };

    match execution {
        Ok(response) => soracloud_local_read_response(response),
        Err(error) => soracloud_local_read_error_response(error),
    }
}

#[cfg(feature = "app_api")]
async fn forward_soradns_public_runtime_request(
    app: SharedAppState,
    fqdn: String,
    tail: Option<String>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: HeaderMap,
    remote_ip: IpAddr,
    body: Bytes,
) -> Response {
    let host = match resolve_active_soradns_gateway_host(&app, &fqdn) {
        Ok(host) => host,
        Err(response) => return response,
    };
    let request_path = match tail {
        Some(path) if !path.is_empty() => format!("/{path}"),
        _ => "/".to_owned(),
    };
    let uri = match rewrite_soradns_public_runtime_uri(&uri, &request_path) {
        Ok(uri) => uri,
        Err(response) => return response,
    };
    let headers = match rewrite_soradns_public_runtime_headers(&headers, &host) {
        Ok(headers) => headers,
        Err(response) => return response,
    };
    execute_soracloud_public_runtime_request(app, method, uri, headers, remote_ip, body).await
}

