async fn handler_iso_status(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    axum::extract::Path(msg_id): axum::extract::Path<String>,
) -> Result<(StatusCode, JsonBody<norito::json::native::Value>), Error> {
    let remote_ip = remote.ip();
    check_access(&app, &headers, Some(remote_ip), "v1/iso20022/messages").await?;
    let runtime = match &app.iso_bridge {
        Some(rt) => rt.clone(),
        None => {
            return Err(Error::Query(
                iroha_data_model::ValidationFail::NotPermitted("iso20022 bridge disabled".into()),
            ));
        }
    };

    let mut status = runtime.message_status(&msg_id).ok_or_else(|| {
        Error::Query(iroha_data_model::ValidationFail::NotPermitted(
            "unknown ISO 20022 message identifier".into(),
        ))
    })?;

    if status.derived_status() != Pacs002Status::Acsc {
        // Opportunistically mark the message as settled when the transaction hash
        // is already committed. This keeps the pacs.002 sequence progressing even
        // before a dedicated watcher threads `mark_settled` from the pipeline.
        if let Some(hash_str) = status.transaction_hash() {
            if let Ok(hash) = hash_str.parse::<HashOf<SignedTransaction>>() {
                if app.state.has_committed_transaction(hash) {
                    runtime.mark_settled(&msg_id, SystemTime::now());
                    if let Some(updated) = runtime.message_status(&msg_id) {
                        status = updated;
                    }
                }
            }
        }
    }

    let updated_ms = status
        .updated_at()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis().min(u128::from(u64::MAX)) as u64)
        .unwrap_or(0);

    let mut payload = norito::json::native::Map::new();
    payload.insert(
        "message_id".into(),
        norito::json::native::Value::from(status.message_id().to_string()),
    );
    payload.insert(
        "status".into(),
        norito::json::native::Value::from(status.status_label().to_string()),
    );
    payload.insert(
        "pacs002_code".into(),
        norito::json::native::Value::from(status.pacs002_code().to_string()),
    );
    payload.insert(
        "transaction_hash".into(),
        json_string_or_null(status.transaction_hash().map(str::to_string)),
    );
    payload.insert(
        "detail".into(),
        json_string_or_null(status.detail().map(str::to_string)),
    );
    payload.insert(
        "hold_reason_code".into(),
        json_string_or_null(status.hold_reason_code().map(str::to_string)),
    );
    let change_codes = status
        .change_reason_codes()
        .iter()
        .cloned()
        .map(norito::json::native::Value::from)
        .collect::<Vec<_>>();
    payload.insert(
        "change_reason_codes".into(),
        norito::json::native::Value::Array(change_codes),
    );
    payload.insert(
        "updated_at_ms".into(),
        norito::json::native::Value::from(updated_ms),
    );
    payload.insert(
        "ledger_id".into(),
        json_string_or_null(status.ledger_id().map(str::to_string)),
    );
    payload.insert(
        "source_account_id".into(),
        json_string_or_null(status.source_account_id().map(str::to_string)),
    );
    payload.insert(
        "source_account_address".into(),
        json_string_or_null(status.source_account_address().map(str::to_string)),
    );
    payload.insert(
        "target_account_id".into(),
        json_string_or_null(status.target_account_id().map(str::to_string)),
    );
    payload.insert(
        "target_account_address".into(),
        json_string_or_null(status.target_account_address().map(str::to_string)),
    );
    payload.insert(
        "asset_definition_id".into(),
        json_string_or_null(status.asset_definition_id().map(str::to_string)),
    );
    payload.insert(
        "asset_id".into(),
        json_string_or_null(status.asset_id().map(str::to_string)),
    );
    payload.insert(
        "settlement_amount".into(),
        json_string_or_null(status.settlement_amount().map(str::to_string)),
    );
    payload.insert(
        "settlement_currency".into(),
        json_string_or_null(status.settlement_currency().map(str::to_string)),
    );
    payload.insert(
        "settlement_date".into(),
        json_string_or_null(status.settlement_date().map(str::to_string)),
    );
    payload.insert(
        "settlement_quantity".into(),
        json_string_or_null(status.settlement_quantity().map(str::to_string)),
    );
    payload.insert(
        "settlement_movement_type".into(),
        json_string_or_null(status.settlement_movement_type().map(str::to_string)),
    );
    payload.insert(
        "settlement_payment_type".into(),
        json_string_or_null(status.settlement_payment_type().map(str::to_string)),
    );
    payload.insert(
        "security_instrument_id".into(),
        json_string_or_null(status.security_instrument_id().map(str::to_string)),
    );
    payload.insert(
        "collateral_obligation_id".into(),
        json_string_or_null(status.collateral_obligation_id().map(str::to_string)),
    );
    payload.insert(
        "collateral_original_amount".into(),
        json_string_or_null(status.collateral_original_amount().map(str::to_string)),
    );
    payload.insert(
        "collateral_original_currency".into(),
        json_string_or_null(status.collateral_original_currency().map(str::to_string)),
    );
    payload.insert(
        "collateral_original_instrument_id".into(),
        json_string_or_null(
            status
                .collateral_original_instrument_id()
                .map(str::to_string),
        ),
    );
    payload.insert(
        "collateral_substitute_amount".into(),
        json_string_or_null(status.collateral_substitute_amount().map(str::to_string)),
    );
    payload.insert(
        "collateral_substitute_currency".into(),
        json_string_or_null(status.collateral_substitute_currency().map(str::to_string)),
    );
    payload.insert(
        "collateral_substitute_instrument_id".into(),
        json_string_or_null(
            status
                .collateral_substitute_instrument_id()
                .map(str::to_string),
        ),
    );
    payload.insert(
        "collateral_effective_date".into(),
        json_string_or_null(status.collateral_effective_date().map(str::to_string)),
    );
    payload.insert(
        "collateral_substitution_type".into(),
        json_string_or_null(status.collateral_substitution_type().map(str::to_string)),
    );
    payload.insert(
        "collateral_haircut".into(),
        json_string_or_null(status.collateral_haircut().map(str::to_string)),
    );
    payload.insert(
        "collateral_reason_code".into(),
        json_string_or_null(status.collateral_reason_code().map(str::to_string)),
    );
    payload.insert(
        "plan_execution_order".into(),
        json_string_or_null(status.plan_execution_order().map(str::to_string)),
    );
    payload.insert(
        "plan_atomicity".into(),
        json_string_or_null(status.plan_atomicity().map(str::to_string)),
    );
    insert_iso_metadata_fields(&mut payload, &status);
    Ok((
        StatusCode::OK,
        JsonBody(norito::json::native::Value::Object(payload)),
    ))
}

