async fn handler_pipeline_recovery_fastpq_proofs(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    AxPath(height): AxPath<u64>,
    crate::NoritoStringQuery(query): crate::NoritoStringQuery<PipelineFastpqRecoveryQuery>,
) -> Result<Response, Error> {
    // The route's sealed middleware has already verified its canonical,
    // replay-resistant operator signature before extractors or this handler can
    // run. Charge the authenticated request before touching Kura or acquiring
    // compute capacity.
    check_access_with_rate_limiter(
        &app,
        &headers,
        Some(remote.ip()),
        "v1/pipeline/recovery/fastpq-proofs",
        &app.rate_limiter,
    )
    .await?;

    let page = PipelineFastpqRecoveryPage::parse(&query)?;
    let admission = acquire_query_admission(&app, true).await?;
    let kura = Arc::clone(&app.kura);
    let (result, _admission) = tokio::task::spawn_blocking(move || {
        // Keep both general-query and heavy-work permits in the physical worker.
        // Cancelling the HTTP future therefore cannot release capacity while
        // Kura reads, transcript reconstruction, or encoding still run.
        let result = build_pipeline_recovery_fastpq_response(&kura, height, page);
        (result, admission)
    })
    .await
    .map_err(|error| Error::AppServiceUnavailable {
        code: "pipeline_recovery_fastpq_worker_failed",
        message: error.to_string(),
    })?;
    let serialized = result?;
    Ok(axum::http::Response::builder()
        .status(axum::http::StatusCode::OK)
        .header(axum::http::header::CONTENT_TYPE, "application/json")
        .body(axum::body::Body::from(serialized))
        .expect("static FASTPQ recovery response is valid"))
}

const PIPELINE_FASTPQ_RECOVERY_DEFAULT_LIMIT: usize = 16;
const PIPELINE_FASTPQ_RECOVERY_MAX_LIMIT: usize = 64;
const PIPELINE_FASTPQ_RECOVERY_MAX_PROOF_BYTES: usize = 4 * 1024 * 1024;
const PIPELINE_FASTPQ_RECOVERY_MAX_BATCH_BYTES: usize = 8 * 1024 * 1024;
const PIPELINE_FASTPQ_RECOVERY_MAX_ARTIFACT_BYTES: usize = 16 * 1024 * 1024;
const PIPELINE_FASTPQ_RECOVERY_MAX_RESPONSE_BYTES: usize = 24 * 1024 * 1024;

#[derive(JsonDeserialize, crate::json_macros::JsonSerialize, Clone, Debug, Default)]
struct PipelineFastpqRecoveryQuery {
    #[norito(default)]
    offset: Option<u64>,
    #[norito(default)]
    limit: Option<u64>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PipelineFastpqRecoveryPage {
    offset: usize,
    limit: usize,
}

impl PipelineFastpqRecoveryPage {
    fn parse(query: &PipelineFastpqRecoveryQuery) -> Result<Self, Error> {
        let offset = usize::try_from(query.offset.unwrap_or_default())
            .map_err(|_| conversion_error("FASTPQ recovery offset exceeds this host".to_owned()))?;
        let raw_limit = query
            .limit
            .unwrap_or(PIPELINE_FASTPQ_RECOVERY_DEFAULT_LIMIT as u64);
        if raw_limit == 0 || raw_limit > PIPELINE_FASTPQ_RECOVERY_MAX_LIMIT as u64 {
            return Err(conversion_error(format!(
                "FASTPQ recovery limit must be between 1 and {PIPELINE_FASTPQ_RECOVERY_MAX_LIMIT}"
            )));
        }
        let limit = usize::try_from(raw_limit)
            .map_err(|_| conversion_error("FASTPQ recovery limit exceeds this host".to_owned()))?;
        Ok(Self { offset, limit })
    }
}

fn fastpq_recovery_capacity_error(message: impl Into<String>) -> Error {
    Error::AppServiceUnavailable {
        code: "pipeline_recovery_fastpq_artifact_too_large",
        message: message.into(),
    }
}

fn charge_fastpq_recovery_artifact_bytes(used: &mut usize, amount: usize) -> Result<(), Error> {
    let next = used.checked_add(amount).ok_or_else(|| {
        fastpq_recovery_capacity_error("FASTPQ recovery artifact size overflowed")
    })?;
    if next > PIPELINE_FASTPQ_RECOVERY_MAX_ARTIFACT_BYTES {
        return Err(fastpq_recovery_capacity_error(format!(
            "selected FASTPQ recovery artifacts exceed the {} byte response-source budget",
            PIPELINE_FASTPQ_RECOVERY_MAX_ARTIFACT_BYTES
        )));
    }
    *used = next;
    Ok(())
}

fn build_pipeline_recovery_fastpq_response(
    kura: &Kura,
    height: u64,
    page: PipelineFastpqRecoveryPage,
) -> Result<String, Error> {
    let Some(sidecar) = kura.read_pipeline_metadata(height) else {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::NotFound,
        )));
    };
    let total = sidecar.fastpq_proofs.len();
    let start = page.offset.min(total);
    let end = start.saturating_add(page.limit).min(total);
    let mut artifact_bytes = 0;
    let proofs = sidecar.fastpq_proofs[start..end]
        .iter()
        .map(|snapshot| {
            fastpq_proof_snapshot_recovery_json(kura, height, snapshot, &mut artifact_bytes)
        })
        .collect::<Result<Vec<_>, _>>()?;

    let mut root = norito::json::Map::new();
    root.insert(
        "height".to_owned(),
        norito::json::to_value(&sidecar.height).expect("serialize pipeline height"),
    );
    root.insert(
        "block_hash".to_owned(),
        norito::json::to_value(&sidecar.block_hash.to_string())
            .expect("serialize pipeline block hash"),
    );
    root.insert(
        "total_proofs".to_owned(),
        norito::json::to_value(&u64::try_from(total).unwrap_or(u64::MAX))
            .expect("serialize FASTPQ proof total"),
    );
    root.insert(
        "offset".to_owned(),
        norito::json::to_value(&u64::try_from(page.offset).unwrap_or(u64::MAX))
            .expect("serialize FASTPQ proof offset"),
    );
    root.insert(
        "limit".to_owned(),
        norito::json::to_value(&u64::try_from(page.limit).unwrap_or(u64::MAX))
            .expect("serialize FASTPQ proof limit"),
    );
    root.insert(
        "next_offset".to_owned(),
        norito::json::to_value(&(end < total).then(|| u64::try_from(end).unwrap_or(u64::MAX)))
            .expect("serialize FASTPQ proof continuation"),
    );
    root.insert("proofs".to_owned(), norito::json::Value::Array(proofs));
    let serialized =
        norito::json::to_json_pretty(&norito::json::Value::Object(root)).map_err(|source| {
            Error::SerializationFailure {
                context: "pipeline_recovery_fastpq_proofs",
                source: Box::new(source),
            }
        })?;
    if serialized.len() > PIPELINE_FASTPQ_RECOVERY_MAX_RESPONSE_BYTES {
        return Err(fastpq_recovery_capacity_error(format!(
            "encoded FASTPQ recovery page exceeds the {} byte response budget",
            PIPELINE_FASTPQ_RECOVERY_MAX_RESPONSE_BYTES
        )));
    }
    Ok(serialized)
}

fn fastpq_proof_snapshot_recovery_json(
    kura: &Kura,
    height: u64,
    snapshot: &iroha_core::kura::FastpqProofSnapshot,
    artifact_bytes: &mut usize,
) -> Result<norito::json::Value, Error> {
    if snapshot.proof.len() > PIPELINE_FASTPQ_RECOVERY_MAX_PROOF_BYTES {
        return Err(fastpq_recovery_capacity_error(format!(
            "FASTPQ proof exceeds the {} byte per-proof budget",
            PIPELINE_FASTPQ_RECOVERY_MAX_PROOF_BYTES
        )));
    }
    charge_fastpq_recovery_artifact_bytes(artifact_bytes, snapshot.proof.len())?;

    // Build the object field-by-field. `FastpqProofSnapshot::to_json_value`
    // eagerly encodes its batch, which would duplicate expensive work before
    // this endpoint can enforce its source-byte budget.
    let mut object = norito::json::Map::new();
    object.insert(
        "entry_hash".to_owned(),
        norito::json::to_value(&snapshot.entry_hash.to_string())
            .expect("serialize FASTPQ entry hash"),
    );
    object.insert(
        "batch_index".to_owned(),
        norito::json::to_value(&snapshot.batch_index).expect("serialize FASTPQ batch index"),
    );
    object.insert(
        "parameter".to_owned(),
        norito::json::to_value(&snapshot.parameter).expect("serialize FASTPQ parameter"),
    );
    object.insert(
        "transition_count".to_owned(),
        norito::json::to_value(&snapshot.transition_count)
            .expect("serialize FASTPQ transition count"),
    );
    object.insert(
        "trace_commitment".to_owned(),
        norito::json::to_value(&snapshot.trace_commitment.to_string())
            .expect("serialize FASTPQ trace commitment"),
    );
    object.insert(
        "proof_digest".to_owned(),
        norito::json::to_value(&snapshot.proof_digest.to_string())
            .expect("serialize FASTPQ proof digest"),
    );
    object.insert(
        "proof".to_owned(),
        norito::json::to_value(&base64::engine::general_purpose::STANDARD.encode(&snapshot.proof))
            .expect("serialize FASTPQ proof"),
    );

    match fastpq_committed_batch_base64(kura, height, snapshot, artifact_bytes)? {
        Some((batch, reconstructed)) => {
            object.insert(
                "batch".to_string(),
                norito::json::to_value(&batch).expect("serialize FASTPQ batch"),
            );
            object.insert(
                "batch_compact".to_string(),
                norito::json::to_value(&false).expect("serialize FASTPQ batch compact flag"),
            );
            object.insert(
                "batch_reconstructed_from_block".to_string(),
                norito::json::to_value(&reconstructed)
                    .expect("serialize FASTPQ batch reconstruction flag"),
            );
        }
        None => {
            object.insert(
                "batch_compact".to_string(),
                norito::json::to_value(&snapshot.batch.transitions.is_empty())
                    .expect("serialize FASTPQ batch compact flag"),
            );
            if snapshot.transition_count > 0 && snapshot.batch.transitions.is_empty() {
                object.insert(
                    "batch_reconstruction_error".to_string(),
                    norito::json::to_value(
                        "committed block transcripts were not available for this FASTPQ proof",
                    )
                    .expect("serialize FASTPQ batch reconstruction error"),
                );
            }
        }
    }

    Ok(norito::json::Value::Object(object))
}

fn fastpq_committed_batch_base64(
    kura: &Kura,
    height: u64,
    snapshot: &iroha_core::kura::FastpqProofSnapshot,
    artifact_bytes: &mut usize,
) -> Result<Option<(String, bool)>, Error> {
    if snapshot.transition_count == 0 {
        return Ok(None);
    }
    if !snapshot.batch.transitions.is_empty() {
        return encode_fastpq_recovery_batch(&snapshot.batch, false, artifact_bytes).map(Some);
    }

    let Some(height) = usize::try_from(height).ok().and_then(NonZeroUsize::new) else {
        iroha_logger::warn!(
            height,
            "cannot reconstruct FASTPQ batch for invalid block height"
        );
        return Ok(None);
    };
    let Some(block) = kura.get_block(height) else {
        iroha_logger::warn!(
            height = height.get(),
            entry_hash = %snapshot.entry_hash,
            "cannot reconstruct FASTPQ batch because committed block is unavailable"
        );
        return Ok(None);
    };
    let Some(transcripts) = block.fastpq_transcripts().get(&snapshot.entry_hash) else {
        iroha_logger::warn!(
            height = height.get(),
            entry_hash = %snapshot.entry_hash,
            "cannot reconstruct FASTPQ batch because committed block has no matching transcript"
        );
        return Ok(None);
    };
    match iroha_core::fastpq::batch_from_transcript_bundle(
        snapshot.parameter.clone(),
        snapshot.batch.public_inputs,
        snapshot.entry_hash,
        transcripts,
    ) {
        Ok(batch) => encode_fastpq_recovery_batch(&batch, true, artifact_bytes).map(Some),
        Err(err) => {
            iroha_logger::warn!(
                height = height.get(),
                entry_hash = %snapshot.entry_hash,
                ?err,
                "failed to reconstruct FASTPQ batch from committed transcripts"
            );
            Ok(None)
        }
    }
}

fn encode_fastpq_recovery_batch(
    batch: &fastpq_prover::TransitionBatch,
    reconstructed: bool,
    artifact_bytes: &mut usize,
) -> Result<(String, bool), Error> {
    let bytes = norito::to_bytes(batch).map_err(|source| Error::SerializationFailure {
        context: "pipeline_recovery_fastpq_batch",
        source: Box::new(source),
    })?;
    if bytes.len() > PIPELINE_FASTPQ_RECOVERY_MAX_BATCH_BYTES {
        return Err(fastpq_recovery_capacity_error(format!(
            "FASTPQ batch exceeds the {} byte per-batch budget",
            PIPELINE_FASTPQ_RECOVERY_MAX_BATCH_BYTES
        )));
    }
    charge_fastpq_recovery_artifact_bytes(artifact_bytes, bytes.len())?;
    Ok((
        base64::engine::general_purpose::STANDARD.encode(bytes),
        reconstructed,
    ))
}

#[derive(JsonDeserialize, crate::json_macros::JsonSerialize, Clone, Debug)]
struct PipelineStatusQuery {
    #[norito(default)]
    hash: Option<String>,
    #[norito(default)]
    scope: Option<String>,
}

#[derive(JsonDeserialize, crate::json_macros::JsonSerialize, Clone, Debug)]
struct TriggerCompletionQuery {
    #[norito(default)]
    id: Option<String>,
    #[norito(default)]
    entrypoint_hash: Option<String>,
    #[norito(default)]
    outcome: Option<String>,
    #[norito(default)]
    from_height: Option<u64>,
    #[norito(default)]
    to_height: Option<u64>,
    #[norito(default)]
    limit: Option<u64>,
    #[norito(default)]
    scan_limit_blocks: Option<u64>,
    #[norito(default)]
    include_reconstructed: Option<bool>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TriggerCompletionOutcomeFilter {
    All,
    Success,
    Failure,
}

impl TriggerCompletionOutcomeFilter {
    fn parse(raw: Option<&str>) -> Result<Self, Error> {
        let normalized = raw
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or("all")
            .to_ascii_lowercase();
        match normalized.as_str() {
            "all" | "*" => Ok(Self::All),
            "success" | "ok" => Ok(Self::Success),
            "failure" | "failed" | "error" => Ok(Self::Failure),
            _ => Err(conversion_error(format!(
                "invalid outcome query parameter \"{normalized}\" (expected all|success|failure)"
            ))),
        }
    }

    fn matches(self, outcome: &str) -> bool {
        match self {
            Self::All => true,
            Self::Success => matches!(outcome, "Success"),
            Self::Failure => matches!(outcome, "Failure"),
        }
    }
}

const TRIGGER_COMPLETION_DEFAULT_LIMIT: u64 = 100;
const TRIGGER_COMPLETION_MAX_LIMIT: u64 = 1_000;
const TRIGGER_COMPLETION_DEFAULT_SCAN_BLOCKS: u64 = 1_000;
const TRIGGER_COMPLETION_MAX_SCAN_BLOCKS: u64 = 10_000;

fn trigger_completion_outcome(outcome: &TriggerCompletedOutcome) -> (&'static str, Option<String>) {
    match outcome {
        TriggerCompletedOutcome::Success => ("Success", None),
        TriggerCompletedOutcome::Failure(message) => ("Failure", Some(message.clone())),
    }
}

fn trigger_completion_summary_from_event(
    event: &TriggerCompletedEvent,
) -> TriggerCompletionSummary {
    let (outcome, message) = trigger_completion_outcome(event.outcome());
    TriggerCompletionSummary {
        trigger_id: event.trigger_id().to_string(),
        trigger_execution_hash: event.trigger_execution_hash().to_string(),
        step_index: *event.step_index(),
        outcome: outcome.to_owned(),
        message,
    }
}

fn trigger_completion_record_from_event(
    block: &iroha_data_model::block::SignedBlock,
    block_height: u64,
    event: &TriggerCompletedEvent,
    source: &str,
) -> TriggerCompletionRecord {
    let entrypoint_index = block
        .entrypoint_hashes()
        .position(|hash| hash == *event.trigger_execution_hash())
        .and_then(|index| u64::try_from(index).ok());
    TriggerCompletionRecord {
        block_height,
        entrypoint_index,
        completion: trigger_completion_summary_from_event(event),
        source: source.to_owned(),
    }
}

fn trigger_completion_record_from_parts(
    block_height: u64,
    entrypoint_index: usize,
    trigger_id: String,
    trigger_execution_hash: String,
    step_index: u32,
    outcome: &str,
    message: Option<String>,
    source: &str,
) -> TriggerCompletionRecord {
    TriggerCompletionRecord {
        block_height,
        entrypoint_index: u64::try_from(entrypoint_index).ok(),
        completion: TriggerCompletionSummary {
            trigger_id,
            trigger_execution_hash,
            step_index,
            outcome: outcome.to_owned(),
            message,
        },
        source: source.to_owned(),
    }
}

fn reconstruct_trigger_completion_records(
    block: &iroha_data_model::block::SignedBlock,
    block_height: u64,
) -> Vec<TriggerCompletionRecord> {
    let mut records = Vec::new();
    for (entrypoint_index, entrypoint, result) in block.entrypoint_results() {
        let execution_hash = entrypoint.hash().to_string();
        if let TransactionEntrypoint::Time(time_entrypoint) = &entrypoint {
            match &result.0 {
                Ok(_) => records.push(trigger_completion_record_from_parts(
                    block_height,
                    entrypoint_index,
                    time_entrypoint.id.to_string(),
                    execution_hash.clone(),
                    0,
                    "Success",
                    None,
                    "reconstructed_result",
                )),
                Err(reason) => records.push(trigger_completion_record_from_parts(
                    block_height,
                    entrypoint_index,
                    time_entrypoint.id.to_string(),
                    execution_hash.clone(),
                    0,
                    "Failure",
                    Some(reason.to_string()),
                    "reconstructed_result",
                )),
            }
        }

        let Ok(sequence) = &result.0 else {
            continue;
        };
        let first_data_step = if matches!(entrypoint, TransactionEntrypoint::Time(_)) {
            1_u32
        } else {
            0_u32
        };
        for (offset, step) in sequence.iter().enumerate() {
            let step_index =
                first_data_step.saturating_add(u32::try_from(offset).unwrap_or(u32::MAX));
            records.push(trigger_completion_record_from_parts(
                block_height,
                entrypoint_index,
                step.id.to_string(),
                execution_hash.clone(),
                step_index,
                "Success",
                None,
                "reconstructed_result",
            ));
        }
    }
    records
}

fn trigger_completion_record_matches(
    record: &TriggerCompletionRecord,
    trigger_id: Option<&str>,
    entrypoint_hash: Option<&str>,
    outcome: TriggerCompletionOutcomeFilter,
) -> bool {
    if let Some(trigger_id) = trigger_id
        && record.completion.trigger_id != trigger_id
    {
        return false;
    }
    if let Some(entrypoint_hash) = entrypoint_hash
        && record.completion.trigger_execution_hash != entrypoint_hash
    {
        return false;
    }
    outcome.matches(&record.completion.outcome)
}

fn trigger_completion_records_for_block(
    block: &iroha_data_model::block::SignedBlock,
    block_height: u64,
    include_reconstructed: bool,
    entrypoint_hash: Option<&str>,
) -> Vec<TriggerCompletionRecord> {
    let persisted = block
        .trigger_completions()
        .unwrap_or_default()
        .iter()
        .map(|event| {
            trigger_completion_record_from_event(block, block_height, event, "block_result")
        })
        .collect::<Vec<_>>();
    if !include_reconstructed {
        return persisted;
    }
    if persisted.is_empty() {
        return reconstruct_trigger_completion_records(block, block_height);
    }
    if let Some(entrypoint_hash) = entrypoint_hash
        && !persisted
            .iter()
            .any(|record| record.completion.trigger_execution_hash == entrypoint_hash)
    {
        return reconstruct_trigger_completion_records(block, block_height);
    }
    persisted
}

fn trigger_completion_from_height(query: &TriggerCompletionQuery, requested_to: u64) -> u64 {
    query.from_height.map_or_else(
        || {
            let scan_limit = query
                .scan_limit_blocks
                .unwrap_or(TRIGGER_COMPLETION_DEFAULT_SCAN_BLOCKS)
                .clamp(1, TRIGGER_COMPLETION_MAX_SCAN_BLOCKS);
            requested_to
                .saturating_sub(scan_limit.saturating_sub(1))
                .max(1)
        },
        |from_height| from_height.max(1),
    )
}

fn trigger_completion_query_response(
    app: &SharedAppState,
    query: &TriggerCompletionQuery,
) -> Result<TriggerCompletionListResponse, Error> {
    let latest_height = u64::try_from(app.state.committed_height()).unwrap_or(u64::MAX);
    let limit = query
        .limit
        .unwrap_or(TRIGGER_COMPLETION_DEFAULT_LIMIT)
        .clamp(1, TRIGGER_COMPLETION_MAX_LIMIT);
    let include_reconstructed = query.include_reconstructed.unwrap_or(true);
    let outcome = TriggerCompletionOutcomeFilter::parse(query.outcome.as_deref())?;
    let requested_to = query.to_height.unwrap_or(latest_height).min(latest_height);

    if latest_height == 0 || requested_to == 0 {
        return Ok(TriggerCompletionListResponse {
            latest_height,
            from_height: 0,
            to_height: requested_to,
            scanned_blocks: 0,
            limit,
            completions: Vec::new(),
        });
    }

    let from_height = trigger_completion_from_height(query, requested_to);
    if from_height > requested_to {
        return Ok(TriggerCompletionListResponse {
            latest_height,
            from_height,
            to_height: requested_to,
            scanned_blocks: 0,
            limit,
            completions: Vec::new(),
        });
    }

    let mut completions = Vec::new();
    let mut scanned_blocks = 0_u64;
    for height in (from_height..=requested_to).rev() {
        scanned_blocks = scanned_blocks.saturating_add(1);
        let Some(height_usize) = usize::try_from(height).ok().and_then(NonZeroUsize::new) else {
            continue;
        };
        let Some(block) = app.kura.get_block(height_usize) else {
            continue;
        };
        for record in trigger_completion_records_for_block(
            block.as_ref(),
            height,
            include_reconstructed,
            query.entrypoint_hash.as_deref(),
        ) {
            if !trigger_completion_record_matches(
                &record,
                query.id.as_deref(),
                query.entrypoint_hash.as_deref(),
                outcome,
            ) {
                continue;
            }
            completions.push(record);
            if u64::try_from(completions.len()).unwrap_or(u64::MAX) >= limit {
                return Ok(TriggerCompletionListResponse {
                    latest_height,
                    from_height,
                    to_height: requested_to,
                    scanned_blocks,
                    limit,
                    completions,
                });
            }
        }
    }

    Ok(TriggerCompletionListResponse {
        latest_height,
        from_height,
        to_height: requested_to,
        scanned_blocks,
        limit,
        completions,
    })
}

fn trigger_completion_summaries_for_entrypoint_hash(
    app: &SharedAppState,
    block_height: u64,
    entrypoint_hash: &str,
) -> Vec<TriggerCompletionSummary> {
    let query = TriggerCompletionQuery {
        id: None,
        entrypoint_hash: Some(entrypoint_hash.to_owned()),
        outcome: None,
        from_height: Some(block_height),
        to_height: Some(block_height),
        limit: Some(TRIGGER_COMPLETION_MAX_LIMIT),
        scan_limit_blocks: Some(1),
        include_reconstructed: Some(true),
    };
    trigger_completion_query_response(app, &query)
        .map(|response| {
            response
                .completions
                .into_iter()
                .map(|record| record.completion)
                .collect()
        })
        .unwrap_or_default()
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PipelineStatusReadScope {
    Local,
    Global,
}

impl PipelineStatusReadScope {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Local => "local",
            Self::Global => "global",
        }
    }
}

fn parse_pipeline_status_scope(raw: Option<&str>) -> Result<PipelineStatusReadScope, Error> {
    let normalized = raw
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("global")
        .to_ascii_lowercase();
    match normalized.as_str() {
        "local" => Ok(PipelineStatusReadScope::Local),
        "global" | "auto" => Ok(PipelineStatusReadScope::Global),
        _ => Err(conversion_error(format!(
            "invalid scope query parameter \"{normalized}\" (expected local|global|auto)"
        ))),
    }
}

fn parse_signed_transaction_hash(raw: &str) -> Result<HashOf<SignedTransaction>, Error> {
    raw.trim()
        .parse::<HashOf<SignedTransaction>>()
        .map_err(|_| conversion_error("invalid signed transaction hash".to_owned()))
}

fn pipeline_status_response(
    app: &SharedAppState,
    hash: &HashOf<SignedTransaction>,
    entry: &PipelineStatusEntry,
    scope: PipelineStatusReadScope,
    resolved_from: &'static str,
) -> PipelineTransactionStatusResponse {
    let mut response = PipelineTransactionStatusResponse::new(
        hash.to_string(),
        PipelineTransactionStatus {
            kind: entry.kind.as_str().to_owned(),
            block_height: entry.block_height.map(NonZeroU64::get),
            rejection_reason: entry.rejection.clone(),
        },
        scope.as_str().to_owned(),
        resolved_from.to_owned(),
    );
    if let Some(block_height) = entry.block_height.map(NonZeroU64::get) {
        response.trigger_completions =
            trigger_completion_summaries_for_entrypoint_hash(app, block_height, &hash.to_string());
        if let Some(height) = usize::try_from(block_height)
            .ok()
            .and_then(NonZeroUsize::new)
            && let Some(block) = app.kura.get_block(height)
        {
            let entrypoint_hash =
                HashOf::<TransactionEntrypoint>::from_untyped_unchecked(Hash::from(hash.clone()));
            response.batch_transfer_outcomes =
                block.batch_transfer_outcomes_for(&entrypoint_hash).to_vec();
        }
    }
    response
}

fn pipeline_status_from_state(
    app: &AppState,
    hash: &HashOf<SignedTransaction>,
) -> Option<PipelineStatusEntry> {
    let height = app.state.committed_transaction_height(hash)?;
    let height_u64 = u64::try_from(height.get()).ok()?;
    let height_nz = NonZeroU64::new(height_u64)?;
    let block = app.kura.get_block(height)?;
    let block_ref = block.as_ref();
    for (index, entrypoint, result) in block_ref.entrypoint_results() {
        if index >= block_ref.external_entrypoint_count() {
            break;
        }
        let entrypoint_hash =
            HashOf::<SignedTransaction>::from_untyped_unchecked(Hash::from(entrypoint.hash()));
        if entrypoint_hash != *hash {
            continue;
        }
        let (kind, rejection) = match &result.0 {
            Ok(_) => (PipelineStatusKind::Applied, None),
            Err(reason) => (PipelineStatusKind::Rejected, Some(reason.clone())),
        };
        return Some(PipelineStatusEntry::fresh(kind, Some(height_nz), rejection));
    }
    None
}

fn pipeline_status_terminal_or_state_entry(
    app: &SharedAppState,
    hash: &HashOf<SignedTransaction>,
) -> Option<(PipelineStatusEntry, &'static str)> {
    app.pipeline_status_cache.refresh_pending_blocks(&app.kura);

    if let Some(entry) = pipeline_status_from_state(app.as_ref(), hash) {
        app.pipeline_status_cache
            .record_entry(hash.clone(), entry.clone());
        return Some((entry, "state"));
    }

    if let Some(entry) = app.pipeline_status_cache.lookup(hash) {
        if entry.kind.is_terminal() {
            return Some((entry, "cache"));
        }
    }

    None
}

fn pipeline_status_local_entry(
    app: &SharedAppState,
    hash: &HashOf<SignedTransaction>,
) -> Option<(PipelineStatusEntry, &'static str)> {
    if let Some(entry) = pipeline_status_terminal_or_state_entry(app, hash) {
        return Some(entry);
    }

    if let Some(entry) = app.pipeline_status_cache.lookup(hash) {
        if entry.kind == PipelineStatusKind::Queued
            && !app.queue.contains_pending_hash(hash.clone(), &app.state)
        {
            app.pipeline_status_cache.remove_entry_by_hash(hash);
            return None;
        }
        return Some((entry, "cache"));
    }

    if app.queue.contains_pending_hash(hash.clone(), &app.state) {
        let entry = PipelineStatusEntry::fresh(PipelineStatusKind::Queued, None, None);
        app.pipeline_status_cache
            .record_entry(hash.clone(), entry.clone());
        return Some((entry, "queue"));
    }

    None
}

fn pipeline_status_response_with_route(
    app: &SharedAppState,
    hash: &HashOf<SignedTransaction>,
    entry: &PipelineStatusEntry,
    scope: PipelineStatusReadScope,
    resolved_from: &'static str,
    format: ResponseFormat,
    route: Option<(RoutingDecision, &'static str)>,
) -> Response {
    let mut response = crate::utils::respond_with_format(
        pipeline_status_response(app, hash, entry, scope, resolved_from),
        format,
    );
    if let Some((routing_decision, routed_by)) = route {
        insert_routing_headers(&mut response, routing_decision, routed_by);
    }
    response
}

fn pipeline_status_not_found_error() -> Error {
    Error::Query(iroha_data_model::ValidationFail::QueryFailed(
        iroha_data_model::query::error::QueryExecutionFail::NotFound,
    ))
}

fn pipeline_status_proxy_query(
    hash: &HashOf<SignedTransaction>,
    scope: PipelineStatusReadScope,
) -> Result<Option<String>, Error> {
    encode_torii_proxy_query(&PipelineStatusQuery {
        hash: Some(hash.to_string()),
        scope: Some(scope.as_str().to_owned()),
    })
}

fn execute_pipeline_status_local_read(
    app: &SharedAppState,
    query: &PipelineStatusQuery,
    format: ResponseFormat,
    route: Option<(RoutingDecision, &'static str)>,
) -> Result<Response, Error> {
    let hash_raw = query
        .hash
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| conversion_error("missing hash query parameter".to_owned()))?;
    let read_scope = parse_pipeline_status_scope(query.scope.as_deref())?;
    let hash = parse_signed_transaction_hash(hash_raw)?;

    let local_entry = if matches!(read_scope, PipelineStatusReadScope::Local) {
        pipeline_status_local_entry(app, &hash)
    } else {
        pipeline_status_terminal_or_state_entry(app, &hash)
    };

    if let Some((entry, resolved_from)) = local_entry {
        return Ok(pipeline_status_response_with_route(
            app,
            &hash,
            &entry,
            read_scope,
            resolved_from,
            format,
            route,
        ));
    }

    Err(pipeline_status_not_found_error())
}

#[cfg(feature = "app_api")]
fn pipeline_status_payload_is_authoritative_hint(
    payload: &PipelineTransactionStatusResponse,
) -> bool {
    match payload.status.kind.as_str() {
        "Applied" => true,
        "Rejected" | "Expired" => payload.resolved_from == "state",
        _ => false,
    }
}

#[cfg(feature = "app_api")]
async fn pipeline_status_hinted_global_response(
    response: Response,
) -> Result<Option<Response>, Response> {
    if should_skip_singleton_routed_query_route_error(&response) {
        return Ok(None);
    }
    if !response.status().is_success() {
        return Ok(Some(response));
    }

    let (parts, body) = response.into_parts();
    let bytes = axum::body::to_bytes(body, usize::MAX)
        .await
        .map_err(|error| {
            torii_proxy_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                "invalid_proxy_response",
                format!("failed to read hinted pipeline status response: {error}"),
            )
        })?;
    let is_terminal = norito::json::from_slice::<PipelineTransactionStatusResponse>(&bytes)
        .map(|payload| pipeline_status_payload_is_authoritative_hint(&payload))
        .unwrap_or(false);
    let response = Response::from_parts(parts, Body::from(bytes));

    Ok(is_terminal.then_some(response))
}

async fn handler_pipeline_transaction_status(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    accept: Option<crate::utils::extractors::ExtractAccept>,
    crate::NoritoStringQuery(query): crate::NoritoStringQuery<PipelineStatusQuery>,
) -> Result<Response, Error> {
    let remote_ip = remote.ip();
    let format = match crate::utils::negotiate_response_format(accept.as_ref().map(|v| &v.0)) {
        Ok(format) => format,
        Err(resp) => return Ok(resp),
    };
    check_access_with_rate_limiter(
        &app,
        &headers,
        Some(remote_ip),
        "v1/pipeline/transactions/status",
        &app.pipeline_status_rate_limiter,
    )
    .await?;
    let read_scope = parse_pipeline_status_scope(query.scope.as_deref())?;
    let hash_raw = query
        .hash
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| conversion_error("missing hash query parameter".to_owned()))?;
    let hash = parse_signed_transaction_hash(hash_raw)?;

    if let Ok(response) = execute_pipeline_status_local_read(&app, &query, format, None) {
        return Ok(response);
    }

    if matches!(read_scope, PipelineStatusReadScope::Local) {
        return Err(pipeline_status_not_found_error());
    }

    #[cfg(feature = "app_api")]
    {
        let query_string = pipeline_status_proxy_query(&hash, read_scope)?;
        if let Some(route) = queue::routing_plan_hint(&hash).map(|plan| plan.coordinator_route()) {
            let hinted = execute_torii_single_route_read(
                &app,
                route,
                ToriiReadEndpointV1::PipelineTransactionStatusGet,
                Vec::new(),
                query_string.clone(),
                Vec::new(),
            )
            .await;
            match pipeline_status_hinted_global_response(hinted).await {
                Ok(Some(hinted)) => return Ok(hinted),
                Ok(None) => {}
                Err(response) => return Ok(response),
            }
        }

        Ok(execute_torii_fanout_singleton_read(
            &app,
            ToriiReadEndpointV1::PipelineTransactionStatusGet,
            Vec::new(),
            query_string,
            Vec::new(),
        )
        .await)
    }

    #[cfg(not(feature = "app_api"))]
    {
        let _ = headers;
        let _ = remote_ip;
        let _ = hash;
        Err(pipeline_status_not_found_error())
    }
}

async fn handler_trigger_completions(
    State(app): State<SharedAppState>,
    accept: Option<crate::utils::extractors::ExtractAccept>,
    AxQuery(query): AxQuery<TriggerCompletionQuery>,
) -> Result<Response, Error> {
    let format = match crate::utils::negotiate_response_format(accept.as_ref().map(|v| &v.0)) {
        Ok(format) => format,
        Err(resp) => return Ok(resp),
    };
    Ok(crate::utils::respond_with_format(
        trigger_completion_query_response(&app, &query)?,
        format,
    ))
}

async fn handler_policy(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
) -> Result<impl IntoResponse, Error> {
    #[allow(clippy::too_many_arguments, clippy::ref_option)]
    fn build_policy_body(
        require_token: bool,
        fee_policy: &FeePolicy,
        queue_len: u64,
        normal_th: usize,
        stream_th: usize,
        sub_th: usize,
        token_required: bool,
    ) -> axum::response::Response {
        let mut obj = norito::json::Map::new();
        obj.insert(
            "require_api_token".into(),
            norito::json::Value::from(require_token),
        );
        obj.insert(
            "token_required".into(),
            norito::json::Value::from(token_required),
        );
        match fee_policy.asset_id() {
            Some(asset) => obj.insert(
                "fee_asset_id".into(),
                norito::json::Value::from(asset.to_owned()),
            ),
            None => obj.insert("fee_asset_id".into(), norito::json::Value::Null),
        };
        match fee_policy.receiver() {
            Some(r) => obj.insert(
                "fee_receiver".into(),
                norito::json::Value::from(r.to_owned()),
            ),
            None => obj.insert("fee_receiver".into(), norito::json::Value::Null),
        };
        match fee_policy.amount() {
            Some(amount) => obj.insert(
                "fee_amount".into(),
                norito::json::Value::from(amount.to_string()),
            ),
            None => obj.insert("fee_amount".into(), norito::json::Value::Null),
        };
        obj.insert("queue_len".into(), norito::json::Value::from(queue_len));
        obj.insert(
            "rate_limit_threshold".into(),
            norito::json::Value::from(normal_th as u64),
        );
        obj.insert(
            "stream_rate_limit_threshold".into(),
            norito::json::Value::from(stream_th as u64),
        );
        obj.insert(
            "subscription_rate_limit_threshold".into(),
            norito::json::Value::from(sub_th as u64),
        );
        let fees_enabled = fee_policy.is_enabled();
        let enforced = true;
        let stream_shed = (queue_len as usize) >= stream_th;
        let sub_shed = (queue_len as usize) >= sub_th;
        obj.insert(
            "rate_limit_enforced".into(),
            norito::json::Value::from(enforced),
        );
        obj.insert(
            "stream_rate_limit_enforced".into(),
            norito::json::Value::from(true),
        );
        obj.insert(
            "subscription_rate_limit_enforced".into(),
            norito::json::Value::from(true),
        );
        obj.insert(
            "stream_admission_shed".into(),
            norito::json::Value::from(stream_shed),
        );
        obj.insert(
            "subscription_admission_shed".into(),
            norito::json::Value::from(sub_shed),
        );
        let explain = format!(
            "rate_limits_always_on=true, fees_enabled={}, queue_len={}, high_load_admission_shed_thresholds(normal={}, stream={}, subscription={})",
            fees_enabled, queue_len, normal_th, stream_th, sub_th
        );
        obj.insert("explain".into(), norito::json::Value::from(explain));
        let body = norito::json::to_json_pretty(&norito::json::Value::Object(obj))
            .unwrap_or_else(|_| "{}".into());
        let mut resp = axum::response::Response::new(axum::body::Body::from(body));
        resp.headers_mut().insert(
            axum::http::header::CONTENT_TYPE,
            axum::http::HeaderValue::from_static("application/json"),
        );
        resp
    }

    let queue_len = app.queue.active_len() as u64;
    let token_required = app.require_api_token;

    if limits::is_allowed_by_cidr(&headers, Some(remote.ip()), &app.api_rate_limit_bypass_nets) {
        return Ok(build_policy_body(
            app.require_api_token,
            &app.fee_policy,
            queue_len,
            app.high_load_tx_threshold,
            app.high_load_stream_tx_threshold,
            app.high_load_subscription_tx_threshold,
            token_required,
        ));
    }

    validate_api_token(app.as_ref(), &headers)?;
    let key = rate_limit_key(
        &headers,
        Some(remote.ip()),
        "v1/policy",
        app.api_token_enforced(),
    );
    if !app.rate_limiter.allow(&key).await {
        return Err(Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::CapacityLimit,
        )));
    }

    Ok(build_policy_body(
        app.require_api_token,
        &app.fee_policy,
        queue_len,
        app.high_load_tx_threshold,
        app.high_load_stream_tx_threshold,
        app.high_load_subscription_tx_threshold,
        token_required,
    ))
}

async fn handler_signed_query(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    accept: Option<crate::utils::extractors::ExtractAccept>,
    crate::NoritoQuery(query_options): crate::NoritoQuery<QueryOptions>,
    crate::utils::extractors::JsonOrNoritoVersioned(query_request): crate::utils::extractors::JsonOrNoritoVersioned<
        iroha_data_model::query::SignedQuery,
    >,
) -> Result<Response, Error> {
    let format = match crate::utils::negotiate_response_format(accept.as_ref().map(|v| &v.0)) {
        Ok(fmt) => fmt,
        Err(resp) => return Ok(resp),
    };

    if !limits::is_allowed_by_cidr(&headers, Some(remote.ip()), &app.api_rate_limit_bypass_nets) {
        admit_signed_query_preauth(app.as_ref(), &headers, Some(remote.ip())).await?;
    }

    let query_bytes = iroha_version::codec::EncodeVersioned::encode_versioned(&query_request);
    let verified_query = routing::verify_signed_query_request(query_request)?;
    let query_scope = signed_query_scope_for_app(app.as_ref(), &verified_query);
    let authorized_routes =
        match torii_authorized_signed_query_routes(app.as_ref(), &verified_query, &query_scope) {
            Ok(routes) => routes,
            Err(response) => return Ok(response),
        };

    #[cfg(any(feature = "p2p_ws", feature = "connect"))]
    let should_nexus_fanout = matches!(
        query_scope,
        SignedQueryScope::CrossDataspaceFanout
            | SignedQueryScope::TargetAccount(_)
            | SignedQueryScope::TargetAlias(_)
            | SignedQueryScope::TargetDomain(_)
    ) && authorized_routes.len() > 1;

    #[cfg(any(feature = "p2p_ws", feature = "connect"))]
    if should_nexus_fanout {
        return Ok(
            execute_torii_query_via_nexus_fanout(&app, query_bytes, verified_query, format).await,
        );
    }

    let routing_decision = authorized_routes.first().copied();

    #[cfg(any(feature = "p2p_ws", feature = "connect"))]
    if let Some(routing_decision) = routing_decision
        && !should_execute_route_locally(app.as_ref(), routing_decision)
    {
        return Ok(
            execute_torii_query_via_proxy(&app, query_bytes, routing_decision, format).await,
        );
    }

    let query_response =
        execute_admitted_signed_query_with_opts(&app, verified_query, query_options).await?;
    let mut response = crate::utils::respond_with_format(query_response, format);
    if let Some(routing_decision) = routing_decision {
        insert_routing_headers(&mut response, routing_decision, "local");
    }
    Ok(response)
}

#[cfg(feature = "connect")]
fn connect_remote_ip_from_headers(headers: &axum::http::HeaderMap) -> Result<IpAddr, &'static str> {
    headers
        .get(limits::REMOTE_ADDR_HEADER)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse().ok())
        .ok_or("connect: remote addr unavailable")
}

#[cfg(feature = "connect")]
async fn handle_connect_ws_logic(
    app: SharedAppState,
    headers: axum::http::HeaderMap,
    q: routing::ConnectWsQuery,
    ws: WebSocketUpgrade,
    preauth_guard: Option<Extension<PreAuthGuardHandoff>>,
) -> axum::response::Response {
    let bus = app.connect_bus.clone();
    let remote_ip = match connect_remote_ip_from_headers(&headers) {
        Ok(ip) => ip,
        Err(message) => return (StatusCode::BAD_REQUEST, message).into_response(),
    };
    let mut permit = match bus.pre_ws_handshake(remote_ip).await {
        Ok(permit) => permit,
        Err((code, msg)) => return (code, msg).into_response(),
    };
    let sid = match crate::connect::decode_sid(&q.sid) {
        Ok(sid) => sid,
        Err(_) => {
            permit.release().await;
            return (StatusCode::BAD_REQUEST, "connect: bad sid").into_response();
        }
    };
    let role = match q.role.as_str() {
        "app" => iroha_torii_shared::connect::Role::App,
        "wallet" => iroha_torii_shared::connect::Role::Wallet,
        other => {
            permit.release().await;
            return (
                StatusCode::BAD_REQUEST,
                format!("connect: bad role {other}"),
            )
                .into_response();
        }
    };
    let token = match resolve_connect_ws_token(&headers) {
        Ok(token) => token,
        Err(response) => {
            permit.release().await;
            return response;
        }
    };
    if let Err((code, msg)) = bus.authorize_token(sid, role, &token.token).await {
        permit.release().await;
        return (code, msg).into_response();
    }
    let ws = if let Some(protocol) = token.protocol {
        ws.protocols([protocol])
    } else {
        ws
    };
    let preauth_guard = take_preauth_upgrade_guard(preauth_guard);
    ws.on_upgrade(move |ws| async move {
        let _preauth_guard = preauth_guard;
        let result = connect::handle_ws(bus, q, ws).await;
        permit.release().await;
        if let Err(e) = result {
            iroha_logger::warn!(%e, "connect ws session ended with error");
        }
    })
}

#[cfg(feature = "connect")]
#[allow(dead_code)]
fn _assert_websocket_send() {
    fn assert_send<T: Send>() {}
    fn assert_sync<T: Sync>() {}
    assert_send::<WebSocketUpgrade>();
    assert_sync::<WebSocketUpgrade>();
}

#[cfg(feature = "connect")]
fn require_connect_enabled(app: &SharedAppState) -> Result<(), Error> {
    if app.connect_enabled {
        Ok(())
    } else {
        Err(Error::AppServiceUnavailable {
            code: "connect_disabled",
            message: "Iroha Connect is disabled by node configuration".to_owned(),
        })
    }
}

#[cfg(feature = "connect")]
async fn handler_connect_ws(
    State(app): State<SharedAppState>,
    preauth_guard: Option<Extension<PreAuthGuardHandoff>>,
    headers: axum::http::HeaderMap,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    ws: WebSocketUpgrade,
) -> axum::response::Response {
    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }
    let query = match parse_connect_ws_query(raw_query.as_deref()) {
        Ok(q) => q,
        Err(response) => return response,
    };
    handle_connect_ws_logic(app, headers, query, ws, preauth_guard).await
}

#[cfg(feature = "connect")]
async fn handler_connect_session(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    NoritoJson(req): NoritoJson<routing::ConnectSessionRequest>,
) -> Result<JsonBody<routing::ConnectSessionResponse>> {
    use base64::{Engine as _, engine::general_purpose::URL_SAFE_NO_PAD as B64};

    require_connect_enabled(&app)?;

    let remote_ip = connect_remote_ip_from_headers(&headers).map_err(|message| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(message.to_owned()),
        ))
    })?;
    app.connect_bus
        .pre_session_create(remote_ip)
        .await
        .map_err(|(code, msg)| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(format!(
                    "connect session rejected ({code}): {msg}"
                )),
            ))
        })?;

    let missing_sid = req.sid.is_none();
    let chain_id = app.chain_id.clone();
    let JsonBody(response) = routing::handle_connect_session(chain_id, NoritoJson(req)).await?;
    assert!(!missing_sid, "connect session handler missing sid");

    let malformed = |msg: String| {
        Error::Query(iroha_data_model::ValidationFail::QueryFailed(
            iroha_data_model::query::error::QueryExecutionFail::Conversion(msg),
        ))
    };

    let sid_bytes = B64
        .decode(response.sid.as_bytes())
        .map_err(|err| malformed(format!("connect session sid decode failed: {err}")))?;
    let sid: crate::connect::Sid = sid_bytes
        .try_into()
        .map_err(|_| malformed("connect session sid had wrong length".into()))?;

    app.connect_bus
        .clone()
        .register_tokens(
            sid,
            response.token_app.clone(),
            response.token_wallet.clone(),
            response.token_management.clone(),
            response.token_relay.clone(),
        )
        .await
        .map_err(|err| match err {
            crate::connect::RegisterSessionError::Exists => {
                malformed("connect session already exists for provided sid".to_string())
            }
            crate::connect::RegisterSessionError::Capacity => {
                malformed("connect session capacity reached; try again later".to_string())
            }
        })?;

    Ok(JsonBody(response))
}

#[cfg(feature = "connect")]
async fn handler_connect_session_delete(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::Path(sid_str): axum::extract::Path<String>,
) -> axum::response::Response {
    use axum::http::StatusCode;

    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }

    match crate::connect::decode_sid(&sid_str) {
        Ok(sid) => {
            let token = match parse_authorization_token(&headers) {
                Ok(Some(token)) => token,
                Ok(None) => {
                    return (
                        StatusCode::UNAUTHORIZED,
                        "connect: missing management token",
                    )
                        .into_response();
                }
                Err(response) => return response,
            };
            if !app
                .connect_bus
                .authorize_management_token(sid, &token)
                .await
            {
                return StatusCode::NOT_FOUND.into_response();
            }
            let removed = app
                .connect_bus
                .clone()
                .terminate_session(sid, crate::connect::CLOSE_REASON_PURGED)
                .await;
            if removed {
                StatusCode::NO_CONTENT.into_response()
            } else {
                StatusCode::NOT_FOUND.into_response()
            }
        }
        Err(_) => (StatusCode::BAD_REQUEST, "connect: bad sid").into_response(),
    }
}

#[cfg(feature = "connect")]
#[allow(clippy::result_large_err)]
fn parse_connect_ws_query(
    raw: Option<&str>,
) -> Result<routing::ConnectWsQuery, axum::response::Response> {
    use axum::http::StatusCode;
    let mut sid = None;
    let mut role = None;
    if let Some(qs) = raw {
        for pair in qs.split('&') {
            if pair.is_empty() {
                continue;
            }
            let mut parts = pair.splitn(2, '=');
            let key = parts.next().unwrap_or("");
            let value_raw = parts.next().unwrap_or("");
            let value = match urlencoding::decode(value_raw) {
                Ok(decoded) => decoded.into_owned(),
                Err(_) => {
                    return Err((
                        StatusCode::BAD_REQUEST,
                        "connect query has invalid encoding",
                    )
                        .into_response());
                }
            };
            match key {
                "sid" => sid = Some(value),
                "role" => role = Some(value),
                "token" => {
                    return Err((
                        StatusCode::BAD_REQUEST,
                        "connect query must not include token; use Authorization or Sec-WebSocket-Protocol",
                    )
                        .into_response());
                }
                _ => {}
            }
        }
    }
    fn normalize_role(raw: &str) -> Option<String> {
        match raw.trim().to_ascii_lowercase().as_str() {
            "app" => Some("app".to_string()),
            "wallet" => Some("wallet".to_string()),
            _ => None,
        }
    }

    match (sid, role) {
        (Some(sid), Some(role_raw)) => {
            let Some(role) = normalize_role(&role_raw) else {
                return Err(
                    (StatusCode::BAD_REQUEST, "connect query has invalid role").into_response()
                );
            };
            Ok(routing::ConnectWsQuery { sid, role })
        }
        _ => Err((StatusCode::BAD_REQUEST, "connect query missing sid/role").into_response()),
    }
}

const CONNECT_PROTOCOL_TOKEN_PREFIX: &str = "iroha-connect.token.v1.";

#[derive(Debug)]
struct ConnectWsToken {
    token: String,
    protocol: Option<String>,
}

#[derive(Debug)]
struct ProtocolToken {
    token: String,
    protocol: String,
}

#[allow(clippy::result_large_err)]
fn resolve_connect_ws_token(
    headers: &axum::http::HeaderMap,
) -> Result<ConnectWsToken, axum::response::Response> {
    use axum::http::StatusCode;

    let auth_token = parse_authorization_token(headers)?;
    let protocol_token = parse_protocol_token(headers)?;

    if let Some(auth) = auth_token {
        if let Some(proto) = protocol_token.as_ref() {
            if proto.token != auth {
                return Err((
                    StatusCode::BAD_REQUEST,
                    "connect: conflicting tokens in Authorization and Sec-WebSocket-Protocol headers",
                )
                    .into_response());
            }
            return Ok(ConnectWsToken {
                token: auth,
                protocol: Some(proto.protocol.clone()),
            });
        }
        return Ok(ConnectWsToken {
            token: auth,
            protocol: None,
        });
    }

    if let Some(proto) = protocol_token {
        return Ok(ConnectWsToken {
            token: proto.token,
            protocol: Some(proto.protocol),
        });
    }

    Err((
        StatusCode::BAD_REQUEST,
        "connect: missing token; send Authorization: Bearer <token> or Sec-WebSocket-Protocol: iroha-connect.token.v1.<base64url>",
    )
        .into_response())
}

#[cfg(all(test, feature = "connect"))]
mod connect_token_tests {
    use axum::http::{HeaderMap, HeaderName, StatusCode, header};

    use super::{connect_remote_ip_from_headers, parse_connect_ws_query, resolve_connect_ws_token};

    #[test]
    fn connect_query_rejects_token_param() {
        let err = parse_connect_ws_query(Some("sid=abc&role=app&token=deadbeef"))
            .expect_err("token param should be rejected");
        assert_eq!(err.status(), StatusCode::BAD_REQUEST);
    }

    #[test]
    fn connect_query_rejects_invalid_role() {
        let err = parse_connect_ws_query(Some("sid=abc&role=operator"))
            .expect_err("invalid role should be rejected");
        assert_eq!(err.status(), StatusCode::BAD_REQUEST);
    }

    #[test]
    fn connect_query_accepts_case_insensitive_role() {
        let ok = parse_connect_ws_query(Some("sid=abc&role=Wallet"))
            .expect("case-insensitive role should be accepted");
        assert_eq!(ok.role, "wallet");
    }

    #[test]
    fn resolve_connect_ws_token_requires_headers() {
        let headers = HeaderMap::new();
        let err = resolve_connect_ws_token(&headers).expect_err("missing token should fail");
        assert_eq!(err.status(), StatusCode::BAD_REQUEST);
    }

    #[test]
    fn resolve_connect_ws_token_accepts_bearer() {
        let mut headers = HeaderMap::new();
        headers.insert(header::AUTHORIZATION, "Bearer test-token".parse().unwrap());
        let token = resolve_connect_ws_token(&headers).expect("bearer token ok");
        assert_eq!(token.token, "test-token");
        assert!(token.protocol.is_none());
    }

    #[test]
    fn connect_remote_ip_requires_injected_header() {
        let headers = HeaderMap::new();
        let err = connect_remote_ip_from_headers(&headers).expect_err("missing remote addr");
        assert_eq!(err, "connect: remote addr unavailable");
    }

    #[test]
    fn connect_remote_ip_accepts_valid_injected_header() {
        let mut headers = HeaderMap::new();
        headers.insert(
            HeaderName::from_static(crate::limits::REMOTE_ADDR_HEADER),
            "203.0.113.7".parse().unwrap(),
        );
        let ip = connect_remote_ip_from_headers(&headers).expect("remote addr");
        assert_eq!(ip.to_string(), "203.0.113.7");
    }

    #[test]
    fn connect_remote_ip_rejects_invalid_injected_header() {
        let mut headers = HeaderMap::new();
        headers.insert(
            HeaderName::from_static(crate::limits::REMOTE_ADDR_HEADER),
            "not-an-ip".parse().unwrap(),
        );
        let err = connect_remote_ip_from_headers(&headers).expect_err("invalid remote addr");
        assert_eq!(err, "connect: remote addr unavailable");
    }
}

#[allow(clippy::result_large_err)]
fn parse_authorization_token(
    headers: &axum::http::HeaderMap,
) -> Result<Option<String>, axum::response::Response> {
    use axum::http::{StatusCode, header};

    let Some(value) = headers.get(header::AUTHORIZATION) else {
        return Ok(None);
    };
    let value_str = value
        .to_str()
        .map_err(|_| {
            (
                StatusCode::BAD_REQUEST,
                "connect: invalid authorization header",
            )
                .into_response()
        })?
        .trim();
    let mut parts = value_str.split_whitespace();
    let scheme = parts.next().unwrap_or_default();
    let token = parts.next().unwrap_or("");
    if parts.next().is_some() {
        return Err((
            StatusCode::BAD_REQUEST,
            "connect: malformed authorization header",
        )
            .into_response());
    }
    if !scheme.eq_ignore_ascii_case("bearer") {
        return Err((
            StatusCode::BAD_REQUEST,
            "connect: authorization header must use Bearer scheme",
        )
            .into_response());
    }
    let token = token.trim();
    if token.is_empty() {
        return Err((StatusCode::BAD_REQUEST, "connect: bearer token is empty").into_response());
    }
    Ok(Some(token.to_owned()))
}

#[allow(clippy::result_large_err)]
fn parse_protocol_token(
    headers: &axum::http::HeaderMap,
) -> Result<Option<ProtocolToken>, axum::response::Response> {
    use axum::http::{StatusCode, header};

    let mut values_iter = headers.get_all(header::SEC_WEBSOCKET_PROTOCOL).iter();
    let Some(first_value) = values_iter.next() else {
        return Ok(None);
    };
    for value in std::iter::once(first_value).chain(values_iter) {
        let value_str = value
            .to_str()
            .map_err(|_| {
                (
                    StatusCode::BAD_REQUEST,
                    "connect: invalid Sec-WebSocket-Protocol header",
                )
                    .into_response()
            })?
            .trim();
        for entry in value_str.split(',') {
            let candidate = entry.trim();
            if let Some(encoded) = candidate.strip_prefix(CONNECT_PROTOCOL_TOKEN_PREFIX) {
                let token = decode_protocol_token(encoded)?;
                return Ok(Some(ProtocolToken {
                    token,
                    protocol: candidate.to_string(),
                }));
            }
        }
    }
    Ok(None)
}

#[allow(clippy::result_large_err)]
fn decode_protocol_token(encoded: &str) -> Result<String, axum::response::Response> {
    use axum::http::StatusCode;
    use base64::{Engine as _, engine::general_purpose::URL_SAFE_NO_PAD as B64};

    let bytes = B64.decode(encoded).map_err(|_| {
        (
            StatusCode::BAD_REQUEST,
            "connect: invalid protocol token encoding",
        )
            .into_response()
    })?;
    if bytes.is_empty() {
        return Err((StatusCode::BAD_REQUEST, "connect: protocol token is empty").into_response());
    }
    String::from_utf8(bytes).map_err(|_| {
        (
            StatusCode::BAD_REQUEST,
            "connect: protocol token must be valid utf-8",
        )
            .into_response()
    })
}

#[cfg(feature = "connect")]
async fn handler_connect_status(
    State(app): State<SharedAppState>,
    headers: axum::http::HeaderMap,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> axum::response::Response {
    use axum::http::StatusCode;

    if let Err(error) = require_connect_enabled(&app) {
        return error.into_response();
    }

    let bus = app.connect_bus.clone();
    if let Some(raw) = raw_query.as_deref() {
        let mut sid_query = None;
        for pair in raw.split('&') {
            if pair.is_empty() {
                continue;
            }
            let mut parts = pair.splitn(2, '=');
            let key = parts.next().unwrap_or_default();
            let value = parts.next().unwrap_or_default();
            if key == "sid" {
                sid_query = Some(match urlencoding::decode(value) {
                    Ok(value) => value.into_owned(),
                    Err(_) => {
                        return (StatusCode::BAD_REQUEST, "connect: invalid sid query")
                            .into_response();
                    }
                });
            }
        }
        if let Some(sid_query) = sid_query {
            let sid = match crate::connect::decode_sid(&sid_query) {
                Ok(sid) => sid,
                Err(_) => return (StatusCode::BAD_REQUEST, "connect: bad sid").into_response(),
            };
            let token = match parse_authorization_token(&headers) {
                Ok(Some(token)) => token,
                Ok(None) => {
                    return (
                        StatusCode::UNAUTHORIZED,
                        "connect: missing management token",
                    )
                        .into_response();
                }
                Err(response) => return response,
            };
            return match bus.session_status(sid, &token).await {
                Some(status) => JsonBody(status).into_response(),
                None => StatusCode::NOT_FOUND.into_response(),
            };
        }
    }

    let status = bus.status().await;
    #[cfg(feature = "telemetry")]
    {
        if app.telemetry.allows_metrics() {
            let metrics = app.telemetry.metrics().await;
            metrics
                .torii_connect_sessions_total
                .set(status.sessions_total as u64);
            metrics
                .torii_connect_sessions_active
                .set(status.sessions_active as u64);
            metrics
                .torii_connect_buffered_sessions
                .set(status.buffered_sessions as u64);
            metrics
                .torii_connect_total_buffer_bytes
                .set(status.total_buffer_bytes as u64);
            metrics
                .torii_connect_dedupe_size
                .set(status.dedupe_size as u64);
            for entry in &status.per_ip_sessions {
                metrics
                    .torii_connect_per_ip_sessions
                    .with_label_values(&[entry.ip.as_str()])
                    .set(entry.sessions as u64);
            }
        }
    }
    let mut public_status = status;
    public_status.per_ip_sessions.clear();
    JsonBody(public_status).into_response()
}

#[cfg(feature = "app_api")]
fn require_signed_alias_request(
    app: &SharedAppState,
    headers: &axum::http::HeaderMap,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    body: &[u8],
) -> Result<AccountId, Error> {
    require_signed_account_request(
        app,
        headers,
        method,
        uri,
        body,
        "alias_auth_required",
        "signed account headers are required",
    )
}

#[cfg(feature = "app_api")]
#[allow(clippy::too_many_arguments)]
fn require_signed_account_request(
    app: &SharedAppState,
    headers: &axum::http::HeaderMap,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    body: &[u8],
    error_code: &'static str,
    error_message: &'static str,
) -> Result<AccountId, Error> {
    match crate::app_auth::verify_canonical_request(&app.state, headers, method, uri, body, None)? {
        Some(verified) => Ok(verified.account),
        None => Err(Error::AppUnauthorized {
            code: error_code,
            message: error_message.to_owned(),
        }),
    }
}

#[cfg(feature = "app_api")]
fn multisig_alias_resolve_authority(
    app: &SharedAppState,
    headers: &axum::http::HeaderMap,
    method: &axum::http::Method,
    uri: &axum::http::Uri,
    body: &[u8],
    _selector: &routing::MultisigAccountSelectorDto,
) -> Result<Option<AccountId>, Error> {
    // Multisig authority specs and proposals are sensitive authorization state. Require the
    // canonical account signature for both alias and concrete-account selectors so switching
    // selector shape can never downgrade an authenticated read to an anonymous one.
    require_signed_account_request(
        app,
        headers,
        method,
        uri,
        body,
        "multisig_read_auth_required",
        "signed account headers are required to read multisig authority state",
    )
    .map(Some)
}

#[cfg(feature = "app_api")]
fn alias_setup_plan_report_response(
    status_code: StatusCode,
    status: iroha_data_model::alias_setup::AliasSetupStatusV1,
    code: impl Into<String>,
    resource: Option<String>,
    expected: Option<String>,
    actual: Option<String>,
    remediation: impl Into<String>,
) -> AxResponse {
    use iroha_data_model::alias_setup::{
        AliasSetupDiagnosticV1, AliasSetupReportV1, AliasSetupSeverityV1,
        AliasSetupValidationPhaseV1,
    };

    let report = AliasSetupReportV1::new(
        status,
        vec![AliasSetupDiagnosticV1 {
            phase: AliasSetupValidationPhaseV1::Planning,
            code: code.into(),
            severity: if status == iroha_data_model::alias_setup::AliasSetupStatusV1::Pending {
                AliasSetupSeverityV1::Warning
            } else {
                AliasSetupSeverityV1::Error
            },
            resource,
            config_path: None,
            expected,
            actual,
            remediation: remediation.into(),
        }],
    );
    (status_code, JsonBody(report)).into_response()
}

#[cfg(feature = "app_api")]
fn alias_setup_dependency_rank(intent: &iroha_data_model::alias_setup::AliasIntentV1) -> u8 {
    use iroha_data_model::alias_setup::AliasIntentV1;

    match intent {
        AliasIntentV1::Dataspace(_) => 0,
        AliasIntentV1::Domain(_) => 1,
        AliasIntentV1::AccountAlias(_) => 2,
    }
}

#[cfg(feature = "app_api")]
fn alias_setup_parent_target(
    target: &iroha_data_model::alias_setup::AliasTargetV1,
) -> Option<iroha_data_model::alias_setup::AliasTargetV1> {
    use iroha_data_model::alias_setup::{AliasTargetV1, ResolvedDataSpaceV1};

    match target {
        AliasTargetV1::Dataspace(_) => None,
        AliasTargetV1::Domain(domain) => Some(AliasTargetV1::Dataspace(domain.parent_dataspace())),
        AliasTargetV1::AccountAlias(alias) => alias
            .parent_domain()
            .map(AliasTargetV1::Domain)
            .or_else(|| {
                Some(AliasTargetV1::Dataspace(ResolvedDataSpaceV1::new(
                    alias.canonical_name.dataspace.clone(),
                    alias.dataspace_id,
                )))
            }),
    }
}

#[cfg(feature = "app_api")]
fn alias_setup_parent_expiry_warning(
    child: &iroha_data_model::alias_setup::AliasTargetV1,
    parent: &iroha_data_model::alias_setup::AliasTargetV1,
    child_expiry_ms: u64,
    parent_expiry_ms: u64,
) -> Option<iroha_data_model::alias_setup::AliasSetupDiagnosticV1> {
    use iroha_data_model::alias_setup::{
        AliasSetupDiagnosticV1, AliasSetupSeverityV1, AliasSetupValidationPhaseV1,
    };

    (parent_expiry_ms < child_expiry_ms).then(|| AliasSetupDiagnosticV1 {
        phase: AliasSetupValidationPhaseV1::Planning,
        code: "alias.plan.parent_lease_expires_first".to_owned(),
        severity: AliasSetupSeverityV1::Warning,
        resource: Some(child.to_string()),
        config_path: None,
        expected: Some(format!(
            "parent `{parent}` expiry at or after {child_expiry_ms}"
        )),
        actual: Some(format!("parent expiry {parent_expiry_ms}")),
        remediation:
            "renew the parent lease explicitly if the child must remain routable for its full term"
                .to_owned(),
    })
}

#[cfg(feature = "app_api")]
fn alias_setup_transaction_size_blocker(
    canonical_unsigned_payload_bytes: usize,
    maximum_transaction_bytes: usize,
) -> Option<iroha_data_model::alias_setup::AliasSetupDiagnosticV1> {
    use iroha_data_model::alias_setup::{
        AliasSetupDiagnosticV1, AliasSetupSeverityV1, AliasSetupValidationPhaseV1,
    };

    (canonical_unsigned_payload_bytes > maximum_transaction_bytes).then(|| {
        AliasSetupDiagnosticV1 {
            phase: AliasSetupValidationPhaseV1::Planning,
            code: "alias.plan.transaction_oversized".to_owned(),
            severity: AliasSetupSeverityV1::Error,
            resource: None,
            config_path: None,
            expected: Some(format!(
                "canonical unsigned transaction payload no larger than {maximum_transaction_bytes} bytes"
            )),
            actual: Some(format!(
                "canonical unsigned transaction payload is {canonical_unsigned_payload_bytes} bytes"
            )),
            remediation:
                "reduce the declarative setup intent; the planner will never split it into multiple transactions"
                    .to_owned(),
        }
    })
}

#[cfg(feature = "app_api")]
const ALIAS_SETUP_PLAN_TTL_MS: u64 = 60_000;

#[cfg(feature = "app_api")]
fn alias_setup_plan_deadline(now_ms: u64, guarded_deadline_ms: Option<u64>) -> u64 {
    let planner_deadline_ms = now_ms.saturating_add(ALIAS_SETUP_PLAN_TTL_MS);
    guarded_deadline_ms.map_or(planner_deadline_ms, |guarded_deadline_ms| {
        planner_deadline_ms.min(guarded_deadline_ms)
    })
}

#[cfg(feature = "app_api")]
async fn handler_alias_setup_plan(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    use iroha_core::alias_setup::classify_alias_intent_with_planned_parents_and_endorsement_policy;
    use iroha_data_model::{
        alias_setup::{
            AliasAssetTotalV1, AliasFramedInstructionV1, AliasLeaseQuoteV1, AliasPlanAnchorV1,
            AliasPlanResourceV1, AliasSetupPlanRequestV1, AliasSetupStatusV1,
            AliasTransactionPlanBodyV1, AliasTransactionPlanV1,
        },
        isi::{InstructionBox, alias_setup::EnsureAlias},
    };

    check_public_contract_read_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/aliases/setup/plan",
        "alias_setup_plan",
        false,
    )
    .await?;
    let authority = require_signed_alias_request(&app, &headers, &method, &uri, body.as_ref())?;
    let mut request: AliasSetupPlanRequestV1 =
        norito::json::from_slice(body.as_ref()).map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(error.to_string()),
            ))
        })?;
    if request.schema_version != AliasSetupPlanRequestV1::VERSION {
        return Ok(alias_setup_plan_report_response(
            StatusCode::BAD_REQUEST,
            AliasSetupStatusV1::Blocked,
            "alias.plan.version_unsupported",
            None,
            Some(AliasSetupPlanRequestV1::VERSION.to_string()),
            Some(request.schema_version.to_string()),
            "encode the request using the supported AliasSetupPlanRequestV1 layout",
        ));
    }
    if request.intents.is_empty() {
        return Ok(alias_setup_plan_report_response(
            StatusCode::BAD_REQUEST,
            AliasSetupStatusV1::Blocked,
            "alias.plan.empty",
            None,
            Some("at least one EnsureAlias intent".to_owned()),
            Some("zero intents".to_owned()),
            "add the dataspace, domain, or account-alias resource to the setup request",
        ));
    }

    request.intents.sort_by(|left, right| {
        alias_setup_dependency_rank(&left.intent)
            .cmp(&alias_setup_dependency_rank(&right.intent))
            .then_with(|| left.intent.target().cmp(&right.intent.target()))
    });
    let mut targets = BTreeSet::new();
    for ensure in &request.intents {
        let target = ensure.intent.target();
        if !targets.insert(target.clone()) {
            return Ok(alias_setup_plan_report_response(
                StatusCode::CONFLICT,
                AliasSetupStatusV1::Blocked,
                "alias.plan.duplicate_resource",
                Some(target.to_string()),
                Some("one exact intent per resource".to_owned()),
                Some("duplicate resource".to_owned()),
                "remove the duplicate intent and request a new plan",
            ));
        }
    }

    let state_view = app.state.view();
    let Some(latest_block) = state_view.latest_block() else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            None,
            Some("a committed block anchor".to_owned()),
            Some("no committed block".to_owned()),
            "wait for bootstrap or block synchronization, then request a new plan",
        ));
    };
    let Some(latest_block_hash) = state_view.latest_block_hash() else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            None,
            Some("a canonical committed block hash".to_owned()),
            Some("block hash unavailable".to_owned()),
            "wait for block synchronization, then request a new plan",
        ));
    };
    let now_ms =
        u64::try_from(latest_block.header().creation_time().as_millis()).unwrap_or(u64::MAX);
    let world = state_view.world();
    let nexus = state_view.nexus();
    let catalog = &nexus.dataspace_catalog;
    let default_domain_endorsement_required = nexus.enabled && nexus.endorsement.quorum > 0;
    let mut resources = Vec::with_capacity(request.intents.len());
    let mut instructions = Vec::with_capacity(request.intents.len());
    let mut transaction_instructions = Vec::with_capacity(request.intents.len());
    let mut totals = BTreeMap::<AssetDefinitionId, Quantity>::new();
    let mut planned_dataspaces = BTreeMap::new();
    let mut planned_domains = BTreeSet::new();
    let mut planned_authority_dataspaces = BTreeSet::new();
    let mut planned_authority_domains = BTreeSet::new();
    let mut planned_expiries = BTreeMap::new();
    let mut warnings = Vec::new();
    let mut valid_until_ms = alias_setup_plan_deadline(now_ms, None);

    for (index, ensure) in request.intents.into_iter().enumerate() {
        let target = ensure.intent.target();
        let disposition = match classify_alias_intent_with_planned_parents_and_endorsement_policy(
            world,
            catalog,
            &planned_dataspaces,
            &planned_domains,
            &ensure.intent,
            now_ms,
            default_domain_endorsement_required,
        ) {
            Ok(disposition) => disposition,
            Err(error) => {
                return Ok(alias_setup_plan_report_response(
                    StatusCode::CONFLICT,
                    AliasSetupStatusV1::Blocked,
                    error.code(),
                    Some(target.to_string()),
                    None,
                    Some(error.message().to_owned()),
                    "resolve the reported drift explicitly, then request a new plan",
                ));
            }
        };
        let authorized_by_planned_parent = match &ensure.intent {
            iroha_data_model::alias_setup::AliasIntentV1::AccountAlias(intent) => {
                intent.alias.canonical_name.domain_id().map_or_else(
                    || planned_authority_dataspaces.contains(&intent.alias.dataspace_id),
                    |domain| planned_authority_domains.contains(&domain),
                )
            }
            _ => false,
        };
        if matches!(
            disposition,
            iroha_data_model::alias_setup::AliasPlanDispositionV1::Repair
                | iroha_data_model::alias_setup::AliasPlanDispositionV1::Create
        ) && !authorized_by_planned_parent
            && let Err(error) = iroha_core::alias_setup::validate_alias_intent_authority(
                world,
                &authority,
                &ensure.intent,
            )
        {
            return Ok(alias_setup_plan_report_response(
                StatusCode::FORBIDDEN,
                AliasSetupStatusV1::Blocked,
                error.code(),
                Some(target.to_string()),
                Some("the resource owner or exact applicable management scope".to_owned()),
                Some(authority.to_string()),
                "use the resource owner as transaction authority or grant the exact management scope, then request a new plan",
            ));
        }
        if iroha_core::alias_setup::alias_intent_owner(&ensure.intent) == &authority {
            match &ensure.intent {
                iroha_data_model::alias_setup::AliasIntentV1::Dataspace(intent) => {
                    planned_authority_dataspaces.insert(intent.dataspace.dataspace_id);
                }
                iroha_data_model::alias_setup::AliasIntentV1::Domain(intent) => {
                    planned_authority_domains.insert(intent.domain.canonical_name.clone());
                }
                iroha_data_model::alias_setup::AliasIntentV1::AccountAlias(_) => {}
            }
        }
        if let iroha_data_model::alias_setup::AliasIntentV1::Dataspace(intent) = &ensure.intent {
            planned_dataspaces.insert(
                intent.dataspace.canonical_name.clone(),
                intent.dataspace.dataspace_id,
            );
        }
        if let iroha_data_model::alias_setup::AliasIntentV1::Domain(intent) = &ensure.intent {
            planned_domains.insert(intent.domain.canonical_name.clone());
        }
        let quote = if disposition == iroha_data_model::alias_setup::AliasPlanDispositionV1::Create
        {
            if let Err(error) = iroha_core::alias_setup::validate_configured_alias_payment_asset(
                world,
                &target,
                &state_view.nexus().fees.fee_asset_id,
            ) {
                return Ok(alias_setup_plan_report_response(
                    StatusCode::CONFLICT,
                    AliasSetupStatusV1::Blocked,
                    error.code(),
                    Some(target.to_string()),
                    None,
                    Some(error.message().to_owned()),
                    "align the SNS policy and pricing tiers with the configured fee asset, then request a new plan",
                ));
            }
            let selector = iroha_core::alias_setup::selector_for_resolved_alias_target(&target)
                .map_err(|error| Error::AppConflict {
                    code: error.code(),
                    message: error.message().to_owned(),
                })?;
            let owner = iroha_core::alias_setup::alias_intent_owner(&ensure.intent);
            let quote = match iroha_core::sns::quote_resolved_name_registration(
                world,
                selector,
                owner,
                ensure.acquisition.term_years,
                ensure.acquisition.pricing_class_hint,
                now_ms,
            ) {
                Ok(quote) => quote,
                Err(error) => {
                    return Ok(alias_setup_plan_report_response(
                        StatusCode::CONFLICT,
                        AliasSetupStatusV1::Blocked,
                        "alias.quote.unavailable",
                        Some(target.to_string()),
                        None,
                        Some(error.to_string()),
                        "adjust the lease request or live SNS policy, then request a new plan",
                    ));
                }
            };
            if let Err(error) = iroha_core::alias_setup::validate_alias_quote_guard(
                world,
                &quote,
                &ensure.quote_guard,
                now_ms,
            ) {
                return Ok(alias_setup_plan_report_response(
                    StatusCode::CONFLICT,
                    AliasSetupStatusV1::Blocked,
                    error.code(),
                    Some(target.to_string()),
                    None,
                    Some(error.message().to_owned()),
                    "refresh the guarded quote and request a new plan",
                ));
            }
            valid_until_ms = valid_until_ms.min(ensure.quote_guard.valid_until_ms);
            let current = totals
                .get(&quote.payment_asset_definition_id)
                .cloned()
                .unwrap_or_else(Quantity::zero);
            let total = current.try_add(&quote.charge_amount).map_err(|error| {
                Error::Query(iroha_data_model::ValidationFail::InternalError(format!(
                    "alias plan total overflow: {error}"
                )))
            })?;
            totals.insert(quote.payment_asset_definition_id.clone(), total);
            Some(AliasLeaseQuoteV1 {
                target: target.clone(),
                pricing_class: quote.pricing_class,
                exact_amount: quote.charge_amount,
                guard: ensure.quote_guard.clone(),
                expires_at_ms: quote.expires_at_ms,
                grace_expires_at_ms: quote.grace_expires_at_ms,
                redemption_expires_at_ms: quote.redemption_expires_at_ms,
            })
        } else {
            None
        };

        let instruction: InstructionBox = EnsureAlias::new(
            ensure.intent.clone(),
            ensure.acquisition,
            ensure.quote_guard.clone(),
        )
        .into();
        let (wire_id, framed_payload) =
            iroha_data_model::isi::framed_instruction_payload(&instruction).ok_or_else(|| {
                Error::Query(iroha_data_model::ValidationFail::InternalError(
                    "EnsureAlias is missing from the instruction registry".to_owned(),
                ))
            })?;
        let instruction_index = u32::try_from(index).map_err(|_| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(
                "alias setup instruction index exceeds u32".to_owned(),
            ))
        })?;
        instructions.push(AliasFramedInstructionV1 {
            wire_id: wire_id.to_owned(),
            framed_payload,
        });
        transaction_instructions.push(instruction);
        let child_expiry_ms = quote.as_ref().map_or_else(
            || {
                iroha_core::alias_setup::selector_for_resolved_alias_target(&target)
                    .ok()
                    .and_then(|selector| {
                        iroha_core::sns::get_name_record_by_selector(world, &selector, now_ms).ok()
                    })
                    .map(|record| record.expires_at_ms)
            },
            |quote| Some(quote.expires_at_ms),
        );
        if let (Some(parent), Some(child_expiry_ms)) =
            (alias_setup_parent_target(&target), child_expiry_ms)
        {
            let parent_expiry_ms = planned_expiries.get(&parent).copied().or_else(|| {
                iroha_core::alias_setup::selector_for_resolved_alias_target(&parent)
                    .ok()
                    .and_then(|selector| {
                        iroha_core::sns::get_name_record_by_selector(world, &selector, now_ms).ok()
                    })
                    .map(|record| record.expires_at_ms)
            });
            if let Some(warning) = parent_expiry_ms.and_then(|parent_expiry_ms| {
                alias_setup_parent_expiry_warning(
                    &target,
                    &parent,
                    child_expiry_ms,
                    parent_expiry_ms,
                )
            }) {
                warnings.push(warning);
            }
        }
        if let Some(child_expiry_ms) = child_expiry_ms {
            planned_expiries.insert(target.clone(), child_expiry_ms);
        }
        resources.push(AliasPlanResourceV1 {
            intent: ensure.intent,
            disposition,
            quote,
            instruction_index: Some(instruction_index),
        });
    }

    let totals_by_asset = totals
        .into_iter()
        .map(|(payment_asset, amount)| AliasAssetTotalV1 {
            payment_asset,
            amount,
        })
        .collect();
    let canonical_unsigned_payload = TransactionPayload {
        chain: app.chain_id.as_ref().clone(),
        authority: authority.clone(),
        creation_time_ms: now_ms,
        instructions: transaction_instructions.into(),
        time_to_live_ms: None,
        nonce: None,
        fee_payment: iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        metadata: iroha_data_model::metadata::Metadata::default(),
        attachments: None,
    };
    let canonical_unsigned_payload_bytes =
        norito::codec::encode_adaptive(&canonical_unsigned_payload).len();
    let blockers = alias_setup_transaction_size_blocker(
        canonical_unsigned_payload_bytes,
        app.transaction_max_content_len,
    )
    .into_iter()
    .collect();
    let plan = AliasTransactionPlanV1::new(AliasTransactionPlanBodyV1 {
        version: AliasTransactionPlanBodyV1::VERSION,
        authority,
        chain_id: app.chain_id.as_ref().clone(),
        anchor: AliasPlanAnchorV1 {
            block_height: u64::try_from(state_view.height()).unwrap_or(u64::MAX),
            block_hash: Hash::from(latest_block_hash),
        },
        resources,
        instructions,
        totals_by_asset,
        warnings,
        blockers,
        valid_until_ms,
    });
    Ok(JsonBody(plan).into_response())
}

#[cfg(feature = "app_api")]
const ALIAS_LIFECYCLE_PLAN_TTL_MS: u64 = 60_000;

#[cfg(feature = "app_api")]
fn alias_lifecycle_instruction_frame(
    instruction: &iroha_data_model::isi::InstructionBox,
) -> Result<iroha_data_model::alias_setup::AliasFramedInstructionV1, Error> {
    let (wire_id, framed_payload) = iroha_data_model::isi::framed_instruction_payload(instruction)
        .ok_or_else(|| {
            Error::Query(iroha_data_model::ValidationFail::InternalError(
                "alias lifecycle instruction is missing from the instruction registry".to_owned(),
            ))
        })?;
    Ok(iroha_data_model::alias_setup::AliasFramedInstructionV1 {
        wire_id: wire_id.to_owned(),
        framed_payload,
    })
}

#[cfg(feature = "app_api")]
async fn handler_alias_lease_renew_plan(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    use iroha_data_model::{
        alias_setup::{
            AliasAssetTotalV1, AliasLeaseQuoteV1, AliasLeaseRenewPlanRequestV1,
            AliasLifecycleOperationV1, AliasLifecyclePlanDispositionV1,
            AliasLifecycleTransactionPlanBodyV1, AliasLifecycleTransactionPlanV1,
            AliasPlanAnchorV1, AliasSetupStatusV1,
        },
        isi::InstructionBox,
    };

    check_public_contract_read_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/aliases/lease/renew/plan",
        "alias_lease_renew_plan",
        false,
    )
    .await?;
    let authority = require_signed_alias_request(&app, &headers, &method, &uri, body.as_ref())?;
    let request: AliasLeaseRenewPlanRequestV1 =
        norito::json::from_slice(body.as_ref()).map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(error.to_string()),
            ))
        })?;
    if request.schema_version != AliasLeaseRenewPlanRequestV1::VERSION {
        return Ok(alias_setup_plan_report_response(
            StatusCode::BAD_REQUEST,
            AliasSetupStatusV1::Blocked,
            "alias.renew.plan.version_unsupported",
            Some(request.renewal.target.to_string()),
            Some(AliasLeaseRenewPlanRequestV1::VERSION.to_string()),
            Some(request.schema_version.to_string()),
            "encode the request using the supported AliasLeaseRenewPlanRequestV1 layout",
        ));
    }

    let state_view = app.state.view();
    let Some(latest_block) = state_view.latest_block() else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            Some(request.renewal.target.to_string()),
            Some("a committed block anchor".to_owned()),
            Some("no committed block".to_owned()),
            "wait for bootstrap or block synchronization, then request a new plan",
        ));
    };
    let Some(latest_block_hash) = state_view.latest_block_hash() else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            Some(request.renewal.target.to_string()),
            Some("a canonical committed block hash".to_owned()),
            Some("block hash unavailable".to_owned()),
            "wait for block synchronization, then request a new plan",
        ));
    };
    let now_ms =
        u64::try_from(latest_block.header().creation_time().as_millis()).unwrap_or(u64::MAX);
    let quote = match iroha_core::alias_setup::classify_alias_lease_renewal(
        state_view.world(),
        &state_view.nexus().dataspace_catalog,
        &authority,
        &request.renewal,
        now_ms,
    ) {
        Ok(quote) => quote,
        Err(error) => {
            return Ok(alias_setup_plan_report_response(
                StatusCode::CONFLICT,
                AliasSetupStatusV1::Blocked,
                error.code(),
                Some(request.renewal.target.to_string()),
                None,
                Some(error.message().to_owned()),
                "refresh the live lease and guarded quote, then request a new plan",
            ));
        }
    };
    if let Err(error) = iroha_core::alias_setup::validate_configured_alias_payment_asset(
        state_view.world(),
        &request.renewal.target,
        &state_view.nexus().fees.fee_asset_id,
    ) {
        return Ok(alias_setup_plan_report_response(
            StatusCode::CONFLICT,
            AliasSetupStatusV1::Blocked,
            error.code(),
            Some(request.renewal.target.to_string()),
            None,
            Some(error.message().to_owned()),
            "align the SNS policy and pricing tiers with the configured fee asset, then request a new plan",
        ));
    }
    let instruction: InstructionBox = request.renewal.clone().into();
    let frame = alias_lifecycle_instruction_frame(&instruction)?;
    let lease_quote = AliasLeaseQuoteV1 {
        target: request.renewal.target.clone(),
        pricing_class: quote.pricing_class,
        exact_amount: quote.charge_amount.clone(),
        guard: request.renewal.quote_guard.clone(),
        expires_at_ms: quote.expires_at_ms,
        grace_expires_at_ms: quote.grace_expires_at_ms,
        redemption_expires_at_ms: quote.redemption_expires_at_ms,
    };
    let valid_until_ms = request.renewal.quote_guard.valid_until_ms;
    let plan = AliasLifecycleTransactionPlanV1::new(AliasLifecycleTransactionPlanBodyV1 {
        version: AliasLifecycleTransactionPlanBodyV1::VERSION,
        authority,
        chain_id: app.chain_id.as_ref().clone(),
        anchor: AliasPlanAnchorV1 {
            block_height: u64::try_from(state_view.height()).unwrap_or(u64::MAX),
            block_hash: Hash::from(latest_block_hash),
        },
        operation: AliasLifecycleOperationV1::RenewLease(request.renewal),
        disposition: AliasLifecyclePlanDispositionV1::Apply,
        instruction: Some(frame),
        quote: Some(lease_quote),
        totals_by_asset: vec![AliasAssetTotalV1 {
            payment_asset: quote.payment_asset_definition_id,
            amount: quote.charge_amount,
        }],
        warnings: Vec::new(),
        blockers: Vec::new(),
        valid_until_ms,
    });
    Ok(JsonBody(plan).into_response())
}

#[cfg(feature = "app_api")]
async fn handler_alias_auto_renew_plan(
    State(app): State<SharedAppState>,
    method: axum::http::Method,
    uri: axum::http::Uri,
    headers: axum::http::HeaderMap,
    axum::extract::ConnectInfo(remote): axum::extract::ConnectInfo<std::net::SocketAddr>,
    body: axum::body::Bytes,
) -> Result<AxResponse, Error> {
    use iroha_data_model::{
        alias_setup::{
            AliasAutoRenewPlanRequestV1, AliasLifecycleOperationV1,
            AliasLifecyclePlanDispositionV1, AliasLifecycleTransactionPlanBodyV1,
            AliasLifecycleTransactionPlanV1, AliasPlanAnchorV1, AliasSetupStatusV1,
        },
        isi::InstructionBox,
    };

    check_public_contract_read_route_rate_limit(
        &app,
        &headers,
        remote.ip(),
        "v1/aliases/auto-renew/plan",
        "alias_auto_renew_plan",
        false,
    )
    .await?;
    let authority = require_signed_alias_request(&app, &headers, &method, &uri, body.as_ref())?;
    let request: AliasAutoRenewPlanRequestV1 =
        norito::json::from_slice(body.as_ref()).map_err(|error| {
            Error::Query(iroha_data_model::ValidationFail::QueryFailed(
                iroha_data_model::query::error::QueryExecutionFail::Conversion(error.to_string()),
            ))
        })?;
    if request.schema_version != AliasAutoRenewPlanRequestV1::VERSION {
        return Ok(alias_setup_plan_report_response(
            StatusCode::BAD_REQUEST,
            AliasSetupStatusV1::Blocked,
            "alias.auto_renew.plan.version_unsupported",
            Some(request.configuration.target.to_string()),
            Some(AliasAutoRenewPlanRequestV1::VERSION.to_string()),
            Some(request.schema_version.to_string()),
            "encode the request using the supported AliasAutoRenewPlanRequestV1 layout",
        ));
    }

    let state_view = app.state.view();
    let Some(latest_block) = state_view.latest_block() else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            Some(request.configuration.target.to_string()),
            Some("a committed block anchor".to_owned()),
            Some("no committed block".to_owned()),
            "wait for bootstrap or block synchronization, then request a new plan",
        ));
    };
    let Some(latest_block_hash) = state_view.latest_block_hash() else {
        return Ok(alias_setup_plan_report_response(
            StatusCode::SERVICE_UNAVAILABLE,
            AliasSetupStatusV1::Pending,
            "alias.plan.anchor_pending",
            Some(request.configuration.target.to_string()),
            Some("a canonical committed block hash".to_owned()),
            Some("block hash unavailable".to_owned()),
            "wait for block synchronization, then request a new plan",
        ));
    };
    let now_ms =
        u64::try_from(latest_block.header().creation_time().as_millis()).unwrap_or(u64::MAX);
    let disposition = match iroha_core::alias_setup::classify_alias_auto_renew(
        state_view.world(),
        &state_view.nexus().dataspace_catalog,
        &authority,
        &request.configuration,
        now_ms,
    ) {
        Ok(disposition) => disposition,
        Err(error) => {
            return Ok(alias_setup_plan_report_response(
                StatusCode::CONFLICT,
                AliasSetupStatusV1::Blocked,
                error.code(),
                Some(request.configuration.target.to_string()),
                None,
                Some(error.message().to_owned()),
                "refresh the owner, revision, and policy fields, then request a new plan",
            ));
        }
    };
    let instruction = if disposition == AliasLifecyclePlanDispositionV1::Apply {
        let instruction: InstructionBox = request.configuration.clone().into();
        Some(alias_lifecycle_instruction_frame(&instruction)?)
    } else {
        None
    };
    let plan = AliasLifecycleTransactionPlanV1::new(AliasLifecycleTransactionPlanBodyV1 {
        version: AliasLifecycleTransactionPlanBodyV1::VERSION,
        authority,
        chain_id: app.chain_id.as_ref().clone(),
        anchor: AliasPlanAnchorV1 {
            block_height: u64::try_from(state_view.height()).unwrap_or(u64::MAX),
            block_hash: Hash::from(latest_block_hash),
        },
        operation: AliasLifecycleOperationV1::ConfigureAutoRenew(request.configuration),
        disposition,
        instruction,
        quote: None,
        totals_by_asset: Vec::new(),
        warnings: Vec::new(),
        blockers: Vec::new(),
        valid_until_ms: now_ms.saturating_add(ALIAS_LIFECYCLE_PLAN_TTL_MS),
    });
    Ok(JsonBody(plan).into_response())
}

